package com.stepwise;

import com.google.gson.Gson;
import com.stepwise.engine.CoreEngine;
import com.stepwise.guide.StepwiseGuide;
import com.stepwise.guide.MilestonesFile;
import com.stepwise.persistence.ConfigStore;
import com.stepwise.persistence.StepwisePersistence;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;

/**
 * Builds an engine over the last account's saved progress, for the panel to show while
 * nobody is logged in.
 *
 * <p>A separate engine from the plugin's, so showing the last account never touches the live
 * engine's state or moves the snapshot version the panel waits on.
 *
 * <p>Pass a store from {@link ConfigStore#readOnly}. Building the engine runs code that
 * writes (loading saves the guide version, a resolve can latch steps), and the read-only
 * store drops every one of those writes, so the account's saved state is never changed.
 */
public final class LastSession
{
	private LastSession()
	{
	}

	/**
	 * The RS profile holding {@code playerName}'s saved progress, for a session summary that
	 * carries no profile key.
	 *
	 * <p>One account owns a profile per world type, and a renamed account's old profiles keep
	 * the old name. The profiles with saved progress decide; when they all belong to one
	 * account, its standard-world one. Anything less certain returns null, because choosing
	 * between profiles could show another account's progress under this name.
	 *
	 * @param hasProgress whether a profile key holds saved progress
	 * @return the profile key, or null when no single profile fits
	 */
	public static String profileNamed(String playerName, List<RuneScapeProfile> profiles,
		Predicate<String> hasProgress)
	{
		if (playerName == null)
		{
			return null;
		}
		List<RuneScapeProfile> saved = new ArrayList<>();
		for (RuneScapeProfile profile : profiles)
		{
			if (playerName.equals(profile.getDisplayName()) && hasProgress.test(profile.getKey()))
			{
				saved.add(profile);
			}
		}
		if (saved.size() == 1)
		{
			return saved.get(0).getKey();
		}
		for (RuneScapeProfile profile : saved)
		{
			// Two accounts have held this name, and nothing says which one played last.
			long account = saved.get(0).getAccountHash();
			if (account == RuneScapeProfile.ACCOUNT_HASH_INVALID || profile.getAccountHash() != account)
			{
				return null;
			}
		}
		String standard = null;
		for (RuneScapeProfile profile : saved)
		{
			if (profile.getType() == RuneScapeProfileType.STANDARD)
			{
				if (standard != null)
				{
					return null;
				}
				standard = profile.getKey();
			}
		}
		return standard;
	}

	/**
	 * The account's progress as the engine would resolve it at login, from saved state
	 * alone.
	 *
	 * @param store a read-only store over the account's RS profile
	 * @return the engine, or null when the store holds no saved player state
	 */
	public static CoreEngine build(StepwiseGuide guide, MilestonesFile milestones,
		ConfigStore store, Gson gson)
	{
		StepwisePersistence persistence = new StepwisePersistence(store, gson);
		CoreEngine engine = new CoreEngine(guide, persistence, milestones);
		engine.loadPersistedState();
		if (engine.getPlayerState() == null)
		{
			return null;
		}
		// Login primes the kingdom once its scan has written the kingdom's varbits. Here the
		// saved varbits stand in for that scan.
		engine.primeKingdomFromLogin();
		return engine;
	}
}

package com.stepwise;

import net.runelite.api.GameState;

/**
 * Decides when the panel's welcome page takes the last session, from the game states the
 * plugin sees. Client thread only.
 */
final class LastSessionGate
{
	/**
	 * Whether the panel is showing a logged-in account's live card. Cleared when the last
	 * session replaces it and when the plugin restarts, never by a hop: a hop that ends at the
	 * login screen (a world that turned the player away, a connection lost mid-hop) still
	 * replaces the card.
	 */
	private boolean accountOnPanel;

	/**
	 * Whether the last session has been shown since start-up, so a failed login attempt,
	 * which also returns to the login screen, does not build it again.
	 */
	private boolean lastSessionShown;

	/**
	 * Whether the client is still short of a login: booting, at the login screen, or logging
	 * in. A plugin started then has no account to load and shows the last session instead.
	 */
	static boolean isBeforeLogin(GameState state)
	{
		return state == GameState.UNKNOWN
			|| state == GameState.STARTING
			|| state == GameState.LOGIN_SCREEN
			|| state == GameState.LOGIN_SCREEN_AUTHENTICATOR
			|| state == GameState.LOGGING_IN;
	}

	/** An account has loaded and the panel shows it. */
	void accountLoaded()
	{
		accountOnPanel = true;
	}

	/**
	 * Whether this game state change puts the last session on the welcome page. Only the
	 * login screen does: a hop leaves the panel on the account hopping, which comes straight
	 * back, and a failed login changes nothing already on show.
	 */
	boolean showsLastSessionOn(GameState state)
	{
		return state == GameState.LOGIN_SCREEN && (accountOnPanel || !lastSessionShown);
	}

	/** The welcome page has taken the last session, replacing any account on the panel. */
	void lastSessionShown()
	{
		accountOnPanel = false;
		lastSessionShown = true;
	}

	/** Back to start-up, for a plugin that is disabled and enabled again. */
	void reset()
	{
		accountOnPanel = false;
		lastSessionShown = false;
	}
}

package com.stepwise;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;

/**
 * Stepwise's settings.
 */
@ConfigGroup("stepwise")
public interface StepwiseConfig extends Config
{
	@ConfigSection(
		name = "Step Overlay",
		description = "The current step drawn over the game",
		position = 10
	)
	String stepOverlaySection = "stepOverlay";

	@ConfigSection(
		name = "In-Game Helpers",
		description = "Highlights and InfoBoxes in the game view",
		position = 20
	)
	String helpersSection = "helpers";

	@ConfigSection(
		name = "Notifications",
		description = "Alerts when a game event finishes your current step",
		position = 30
	)
	String notificationsSection = "notifications";

	@ConfigItem(
		keyName = "showStepOverlay",
		name = "Show Step Overlay",
		description = "Show the current step as an in-game overlay. Hold the drag hotkey (Alt by default)"
			+ " to move or resize it.",
		section = stepOverlaySection,
		position = 11
	)
	default boolean showStepOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightLampSkill",
		name = "Highlight the Guide's Skill on XP Lamps",
		description = "Outline the skill the guide recommends when an XP lamp, tome or book asks"
			+ " you to choose one.",
		section = helpersSection,
		position = 21
	)
	default boolean highlightLampSkill()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBirdhouseInfoBox",
		name = "Show Bird House InfoBox",
		description = "Count down your bird house run in an InfoBox while any house is seeded.",
		section = helpersSection,
		position = 22
	)
	default boolean showBirdhouseInfoBox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyStepComplete",
		name = "Step Complete",
		description = "Notify when a game event finishes your current step. Steps in the In Progress"
			+ " list, and steps you finished before reaching them, are checked off silently.",
		section = notificationsSection,
		position = 31
	)
	default Notification notifyStepComplete()
	{
		return Notification.OFF;
	}
}

