import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Value;

/**
 * Tracks the four Fossil Island bird house spaces: their build tier, state, and
 * (for seeded houses) a wall-clock "ready" time. No RuneLite dependency: the plugin
 * reads the varps and player region and passes them in.
 *
 * <p>Bird houses have no "ready" varp, so completion is wall-clock only:
 * {@code readyAt = seededAt + 50min}, as in RuneLite's Time Tracking plugin.
 * {@code seededAt} is stamped when a house is first seen seeded (worst case a full
 * 50 minutes) and refined from the "Seed level is: X/10" dialog.
 */
public class BirdhouseTracker {

    /** 50 minutes, the same for every tier. */
    public static final long FILL_DURATION_SECONDS = 3000;
    /** Seed level shown in the check dialog runs 10 (just seeded) down to 0 (spent). */
    public static final int SEED_LEVEL_MAX = 10;
    public static final long SECONDS_PER_LEVEL = FILL_DURATION_SECONDS / SEED_LEVEL_MAX;

    /** More houses than this emptying in one update counts as stale-varp noise. */
    private static final int RESET_GUARD_THRESHOLD = 2;

    /**
     * The reset guard applies only for this many in-region ticks, long enough for the
     * transmit varps to sync. After that a mass-empty (houses dismantled while unobserved)
     * is accepted, so persisted timers cannot stay seeded forever.
     */
    private static final int RESET_GUARD_SETTLE_TICKS = 3;

    // --- Enums ---

    /**
     * The four bird house spaces on Fossil Island. The game's southern Mushroom Meadow space
     * stands at the entrance to the Tar Swamp, well south of the meadow's mushtree, so the
     * player-facing label names it by the swamp, as the OSRS Wiki does.
     */
    @Getter
    @AllArgsConstructor
    public enum BirdhouseSpace {
        MEADOW_NORTH(1626, "Mushroom Meadow"),
        MEADOW_SOUTH(1627, "Tar Swamp"),
        VALLEY_NORTH(1628, "Verdant Valley, north-east"),
        VALLEY_SOUTH(1629, "Verdant Valley, south-west");

        private final int varpId;
        /** Where the space is, as a player names it. */
        private final String label;

        public static BirdhouseSpace fromVarpId(int varpId) {
            for (BirdhouseSpace s : values()) {
                if (s.varpId == varpId) {
                    return s;
                }
            }
            return null;
        }
    }

    public enum BirdhouseState {
        EMPTY,
        BUILT,
        SEEDED,
        UNKNOWN;

        public static BirdhouseState fromVarpValue(int varp) {
            if (varp < 0 || varp > BirdhouseTier.values().length * 3) {
                return UNKNOWN;
            }
            if (varp == 0) {
                return EMPTY;
            }
            if (varp % 3 == 0) {
                return SEEDED;
            }
            return BUILT;
        }
    }

    /** Build tier of a house, in varp order. The item ID doubles as the InfoBox icon. */
    @Getter
    @AllArgsConstructor
    public enum BirdhouseTier {
        NORMAL(21512),
        OAK(21515),
        WILLOW(21518),
        TEAK(21521),
        MAPLE(22192),
        MAHOGANY(22195),
        YEW(22198),
        MAGIC(22201),
        REDWOOD(22204);

        private final int itemId;

        /** Tier for a varp value, or null if the space is empty / the value is out of range. */
        public static BirdhouseTier fromVarpValue(int varp) {
            int index = (varp - 1) / 3;
            if (varp <= 0 || index >= values().length) {
                return null;
            }
            return values()[index];
        }
    }

    /** Persisted per-house record: the raw varp plus when we believe it was seeded. */
    @Value
    public static class PersistedEntry {
        int varpId;
        int varpValue;
        long seededAtEpochSec;
    }

    /** Live per-house state. seededAt is only meaningful while the house is SEEDED. */
    private static final class Entry {
        final int varpValue;
        // volatile: written on the client thread (update/probe), read on the EDT (TimerPanel).
        volatile long seededAtEpochSec;

        Entry(int varpValue, long seededAtEpochSec) {
            this.varpValue = varpValue;
            this.seededAtEpochSec = seededAtEpochSec;
        }
    }

    /** Concurrent: written on the client thread, read by the timer panel on the EDT. */
    private final Map<BirdhouseSpace, Entry> data = new ConcurrentHashMap<>();

    /** In-region ticks since entering the region — scopes the reset guard. */
    private int inRegionTicks;

    // --- Update ---

    /**
     * Fold in the current varp values. Samples only while the player is in a Fossil
     * Island region, because elsewhere the transmit varps are stale. Mirrors RuneLite's
     * {@code BirdHouseTracker.updateData}, including the reset guard: varps lag a tick on
     * region entry and briefly read 0.
     *
     * @return true if any house changed, so the caller should persist and refresh the UI
     */
    public boolean update(Map<BirdhouseSpace, Integer> varps, boolean inRegion, long nowEpochSec) {
        if (!inRegion) {
            inRegionTicks = 0;
            return false;
        }
        inRegionTicks++;

        Map<BirdhouseSpace, Entry> changes = new EnumMap<>(BirdhouseSpace.class);
        int removalCount = 0;

        for (BirdhouseSpace space : BirdhouseSpace.values()) {
            int varp = varps.getOrDefault(space, 0);
            Entry old = data.get(space);
            int oldVarp = old == null ? -1 : old.varpValue;

            if (varp != oldVarp) {
                changes.put(space, new Entry(varp, nowEpochSec));
            }

            if (varp <= 0 && oldVarp > 0) {
                removalCount++;
            }
        }

        if (inRegionTicks <= RESET_GUARD_SETTLE_TICKS && removalCount > RESET_GUARD_THRESHOLD) {
            return false;
        }

        if (changes.isEmpty()) {
            return false;
        }

        data.putAll(changes);
        return true;
    }

    // --- Persistence ---

    /** Restore persisted houses on login, before the first {@link #update}. */
    public void loadPersisted(Collection<PersistedEntry> entries) {
        clear();
        if (entries == null) {
            return;
        }
        for (PersistedEntry e : entries) {
            BirdhouseSpace space = BirdhouseSpace.fromVarpId(e.getVarpId());
            if (space != null) {
                data.put(space, new Entry(e.getVarpValue(), e.getSeededAtEpochSec()));
            }
        }
    }

    /**
     * Forget all bird house timers. Backs the panel's Reset Bird Houses button, and every load.
     *
     * <p>Also restarts the region-entry count. A login enters the region afresh, and its
     * first varps lag as on any entry. A count carried over from the last session on Fossil
     * Island would skip the reset guard.
     */
    public void clear() {
        data.clear();
        inRegionTicks = 0;
    }

    /** Snapshot for saving to config. */
    public Collection<PersistedEntry> exportForPersist() {
        List<PersistedEntry> out = new ArrayList<>();
        for (Map.Entry<BirdhouseSpace, Entry> e : data.entrySet()) {
            out.add(new PersistedEntry(e.getKey().getVarpId(), e.getValue().varpValue,
                    e.getValue().seededAtEpochSec));
        }
        return out;
    }

    // --- Seed-level probe ---

    /**
     * Refine one house's timer from a "Seed level is: X/10" reading. No-op if the house
     * isn't currently seeded.
     */
    public void applySeedProbe(BirdhouseSpace space, int seedLevel, long nowEpochSec) {
        // One read, so a clear between two reads cannot leave a null entry behind the check.
        Entry e = data.get(space);
        if (e == null || BirdhouseState.fromVarpValue(e.varpValue) != BirdhouseState.SEEDED) {
            return;
        }
        int level = Math.max(0, Math.min(SEED_LEVEL_MAX, seedLevel));
        long elapsed = (SEED_LEVEL_MAX - level) * SECONDS_PER_LEVEL;
        e.seededAtEpochSec = nowEpochSec - elapsed;
    }

    // --- Queries ---

    public BirdhouseState stateOf(BirdhouseSpace space) {
        Entry e = data.get(space);
        return e == null ? BirdhouseState.EMPTY : BirdhouseState.fromVarpValue(e.varpValue);
    }

    /** Build tier of a house, or null if not built. */
    public BirdhouseTier tierOf(BirdhouseSpace space) {
        Entry e = data.get(space);
        return e == null ? null : BirdhouseTier.fromVarpValue(e.varpValue);
    }

    /** Seconds until ready, or 0 if the house isn't seeded / is already ready. */
    public long remainingSeconds(BirdhouseSpace space, long nowEpochSec) {
        long readyAt = readyAtEpochSeconds(space);
        return readyAt < 0 ? 0 : Math.max(0, readyAt - nowEpochSec);
    }

    /**
     * A house's wait as a tooltip line ends: "ready", "1 minute left", "45 minutes left".
     * Minutes round up, so a house never reads ready early.
     */
    public static String timeLeft(long remainingSeconds) {
        if (remainingSeconds <= 0) {
            return "ready";
        }
        long minutes = (remainingSeconds + 59) / 60;
        return minutes + (minutes == 1 ? " minute left" : " minutes left");
    }

    public boolean isReady(BirdhouseSpace space, long nowEpochSec) {
        return isSeeded(space) && remainingSeconds(space, nowEpochSec) == 0;
    }

    /**
     * Epoch second at which the house becomes ready to dismantle, or -1 if it isn't
     * seeded. Independent of "now", so it also serves a house that already completed.
     */
    public long readyAtEpochSeconds(BirdhouseSpace space) {
        // One read of the entry: the panel calls this on the EDT while the client thread writes.
        Entry e = data.get(space);
        return e != null && BirdhouseState.fromVarpValue(e.varpValue) == BirdhouseState.SEEDED
                ? e.seededAtEpochSec + FILL_DURATION_SECONDS : -1;
    }

    public boolean isSeeded(BirdhouseSpace space) {
        return stateOf(space) == BirdhouseState.SEEDED;
    }

    public boolean anySeeded() {
        return Arrays.stream(BirdhouseSpace.values()).anyMatch(this::isSeeded);
    }
}

package com.stepwise.engine;

import java.util.Set;

import com.stepwise.model.PlayerState;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * The Vale Totems bow string spool: how many strings it holds, and where it is.
 *
 * <p>Read like the plank sack: the game keeps the string count in one varbit and transmits it
 * without the spool being opened, so the count is always current. Strings wound onto the
 * spool leave the inventory and the bank, so without this a full spool reads as no bow
 * string at all.
 *
 * <p>The count is bound to the account, not the item: per the wiki, a replacement spool from
 * the Vale Research Exchange picks the charges back up. Callers still require a spool to be
 * present, because a player with no spool cannot use the strings yet.
 */
public final class BowStringSpool {

    private BowStringSpool() {
    }

    /** The spool itself: one item id, with no open/closed pair or charged variants. */
    private static final Set<Integer> SPOOL_ITEM_IDS = Set.of(ItemID.BOWSTRING_SPOOL);

    /**
     * The count varbit, exposed so the plugin can scan it at login. No completion condition
     * names it, so it is absent from {@code requiredVarIds} and would otherwise stay unread
     * after a relog until the player next winds or unwinds a string.
     */
    public static final Set<Integer> CONTENT_VARBIT_IDS = Set.of(VarbitID.BOWSTRING_SPOOL_CHARGES);

    /**
     * How many bow strings the spool holds, or 0 for anything else.
     *
     * <p>Ignores where the spool is. {@code ResolutionEngine} checks that per location.
     */
    public static int stored(PlayerState state, int itemId) {
        if (state == null || itemId != ItemID.BOW_STRING) {
            return 0;
        }
        Integer count = state.getVarbits().get(VarbitID.BOWSTRING_SPOOL_CHARGES);
        return (count != null && count > 0) ? count : 0;
    }

    /** True when a spool is in the inventory or worn. */
    public static boolean carried(PlayerState state) {
        return HeldItems.carried(state, SPOOL_ITEM_IDS);
    }

    /** True when a spool is sitting in the bank. */
    public static boolean banked(PlayerState state) {
        return HeldItems.banked(state, SPOOL_ITEM_IDS);
    }
}

package com.stepwise.engine;

import com.stepwise.guide.CompletionCondition;
import com.stepwise.guide.CompositeMode;
import com.stepwise.guide.GuideStep;
import com.stepwise.guide.StepwiseGuide;
import com.stepwise.guide.ItemLocation;
import com.stepwise.guide.MilestonesFile;
import com.stepwise.guide.NpcInteractions;
import com.stepwise.guide.StepId;
import com.stepwise.guide.StepStatus;
import com.stepwise.guide.WatchedObjectIds;
import com.stepwise.model.AccountType;
import com.stepwise.model.EquipmentSlot;
import com.stepwise.model.ItemStack;
import com.stepwise.model.PlayerState;
import com.stepwise.model.QuestStatus;
import com.stepwise.persistence.StepwisePersistence;
import com.stepwise.snapshot.CompletionCriterion;
import com.stepwise.snapshot.DashboardSnapshot;
import com.stepwise.snapshot.DetailedStep;
import com.stepwise.sailing.BoatVarbits;
import com.stepwise.snapshot.GuidePosition;
import com.stepwise.snapshot.ResolvedStep;
import com.stepwise.snapshot.CurrentStepSummary;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;

/**
 * Central orchestrator.
 * Holds PlayerState, StepwiseGuide, the current guide step, the timer trackers, and step overrides.
 * Each game event flows through here, mutates state, checks for auto-latch,
 * and rebuilds the dashboard snapshot.
 */
@Slf4j
public class CoreEngine {

    @Getter
    private final StepwiseGuide guide;

    /**
     * Volatile: the timer panel reads it on the EDT on its own clock, with no hand-off from
     * the client thread, so only the volatile write publishes a freshly loaded state whole.
     */
    @Getter
    private volatile PlayerState playerState;

    /**
     * The step the panel and overlay present as current: the last step to resolve ACTIVE. It
     * stays put on a pass with no ACTIVE step, and is null before the first resolve after a
     * login or account change.
     */
    private StepId currentStepId;

    @Getter
    private final BirdhouseTracker birdhouseTracker;

    @Getter
    private final TearsOfGuthixTracker tearsOfGuthixTracker;

    @Getter
    private final KingdomTracker kingdomTracker;

    private final Set<StepId> completedSteps;

    final Set<StepId> skippedSteps;

    /**
     * Steps the user explicitly undid. Suppresses auto-latch until the step is manually
     * re-completed, or until no pathway would latch it any more (see resolveAndRebuild).
     */
    final Set<StepId> suppressedSteps;

    /**
     * How many Mark Done and Skip clicks the Recent section keeps. Five covers a sitting's
     * worth of In Progress clicks (a farm run's background steps) and keeps Recent, with its
     * own two rows either side of the current step, within one screen.
     */
    static final int RECENT_MANUAL_LIMIT = 5;

    /**
     * The latest Mark Done and Skip clicks, newest first, at most {@link #RECENT_MANUAL_LIMIT}.
     * Recent lists them wherever they sit in the guide. Without this a step done from the In
     * Progress list, often far behind the current step, could never be undone. Saved with the
     * account, like the sets Undo edits, so a relog does not take the Undo away.
     */
    private final List<StepId> recentManualSteps;

    private final StepwisePersistence persistence;

    private final MilestonesFile milestonesFile;

    final Map<StepId, GuideStep> stepIndex;

    /**
     * Reverse prerequisite index: maps a step ID to all steps that list it as a prerequisite.
     * Used to auto-complete pure travel steps when a dependent step's condition is already met.
     */
    private final Map<StepId, Set<StepId>> prerequisiteOf;

    /**
     * Runs a Runnable on the client thread. EDT-callable mutation methods (markStepDone,
     * skipStep, etc.) route through it to serialize access to shared mutable state.
     */
    private Consumer<Runnable> clientThreadExecutor;

    /**
     * True if the persisted completedSteps set was empty when loadPersistedState() ran.
     * Captured before resolveAndRebuild(), whose per-step auto-latch would otherwise mask a
     * fresh install. onLogin() consumes it before running performMilestoneLatch(), so the latch
     * fires once.
     */
    private boolean noPersistedProgress;

    /** Test visibility: whether the fresh-install milestone latch is armed. */
    boolean isMilestoneLatchArmed() {
        return noPersistedProgress;
    }

    /**
     * Set by {@link #resetGuideProgress()} and consumed by StepwisePlugin on the next
     * game tick to trigger a full login re-scan (varbits, varps, milestone latch).
     * Volatile because it is written from the Swing EDT and read from the client thread.
     */
    private volatile boolean resetPending;

    /**
     * Set by {@link #afterEvent()} when game state changes. {@link #flushIfDirty()}
     * consumes it once per game tick, so a tick's events share one resolve pass.
     */
    private boolean resolveDirty;

    /** The object ids the loaded guide asks about — the only spawns worth recording. */
    private final WatchedObjectIds watchedObjects;
    private final NpcInteractions watchedNpcs;

    /** Watches the Slayer vars for the one tick a task is killed out. */
    private final SlayerTaskTracker slayerTasks = new SlayerTaskTracker();

    /**
     * Watched object ids seen since the client started, kept beside {@link #playerState}
     * rather than only in it.
     *
     * <p>The scene loads before the profile does. Spawn events for the login region arrive
     * before {@code StepwisePlugin.readAccount}, which replaces {@link #playerState} wholesale
     * with the copy read from config, so a sighting written straight into the state would be lost.
     * For a player who logs in at home and stays in the region, those are the only spawns.
     *
     * <p>Sightings accumulate here and are folded into the state each time it is
     * (re)assigned. Bounded by {@link #watchedObjects}, and idempotent to replay.
     */
    private final Set<Integer> objectsSeenThisSession = new HashSet<>();

    /**
     * NPC interactions observed this session, held and adopted as
     * {@link #objectsSeenThisSession} is. Bounded by {@link #watchedNpcs}.
     */
    private final Set<String> npcInteractionsSeenThisSession = new HashSet<>();

    @Getter
    private DashboardSnapshot lastSnapshot;

    /**
     * The steps a game-event flush latched while each was the active step, oldest first.
     * {@link #takeAutoCompletedSteps} hands them on and clears the list. A click flushes
     * between ticks, so a tick can collect more than one. Client thread only.
     */
    private final List<StepId> autoCompletedSteps = new ArrayList<>();

    /** Set by a login scan until the next flush, which reads the scanned state. */
    private boolean loginResolvePending;

    /**
     * Monotonic counter the panel compares to decide whether to redraw. Incremented when the
     * snapshot's content changes, when bird house timers change, and on a guide reset.
     */
    @Getter
    private long snapshotVersion;

    public CoreEngine(StepwiseGuide guide, StepwisePersistence persistence, MilestonesFile milestonesFile) {
        this.guide = guide;
        this.persistence = persistence;
        this.milestonesFile = milestonesFile;
        this.birdhouseTracker = new BirdhouseTracker();
        this.tearsOfGuthixTracker = new TearsOfGuthixTracker();
        this.kingdomTracker = new KingdomTracker();
        this.completedSteps = new HashSet<>();
        this.skippedSteps = new HashSet<>();
        this.suppressedSteps = new HashSet<>();
        this.recentManualSteps = new ArrayList<>();
        this.lastSnapshot = null;

        this.watchedObjects = WatchedObjectIds.fromGuide(guide);
        this.watchedNpcs = NpcInteractions.fromGuide(guide);
        this.stepIndex = new HashMap<>();
        this.prerequisiteOf = new HashMap<>();
        for (GuideStep step : guide.allSteps()) {
            stepIndex.put(step.getId(), step);
            if (step.getPrerequisites() != null) {
                for (StepId prereq : step.getPrerequisites()) {
                    prerequisiteOf.computeIfAbsent(prereq, k -> new HashSet<>()).add(step.getId());
                }
            }
        }
    }

    /**
     * Set the executor for routing EDT mutations to the client thread.
     * Must be called before any panel interaction (e.g. button clicks).
     */
    public void setClientThreadExecutor(Consumer<Runnable> executor) {
        this.clientThreadExecutor = executor;
    }

    public Set<StepId> getCompletedSteps() {
        return Collections.unmodifiableSet(completedSteps);
    }

    /**
     * Load the current RS profile's saved state, replacing whatever the engine held.
     *
     * <p>Runs at every login, not once per client run. The engine outlives a logout, so the
     * account logging in may not be the one that left.
     */
    public void loadPersistedState() {
        clearAccountState();

        PlayerState saved = persistence.loadPlayerState();
        if (saved != null) {
            this.playerState = saved;
            log.debug("Restored saved player state");
        }
        // The login scene's spawns are held in the session set; re-adopt them after the swap.
        adoptSightingsSeenThisSession();

        Set<StepId> completed = persistence.loadCompletedSteps();
        this.noPersistedProgress = completed.isEmpty();
        this.completedSteps.addAll(completed);

        this.skippedSteps.addAll(persistence.loadSkippedSteps());
        this.suppressedSteps.addAll(persistence.loadSuppressedSteps());

        List<StepId> recentManual = persistence.loadRecentManualSteps();
        this.recentManualSteps.addAll(
                recentManual.subList(0, Math.min(recentManual.size(), RECENT_MANUAL_LIMIT)));

        String savedVersion = persistence.loadGuideVersion();
        if (savedVersion != null && !savedVersion.equals(guide.getVersion())) {
            // The shipped guide differs from the one this progress was saved against. Completed
            // steps stay as saved. The logged-out preview loads read-only and logs this at DEBUG.
            // The real load at the next login logs it at INFO.
            if (persistence.isReadOnly()) {
                log.debug("Guide version differs from the saved one ({} → {}), completed steps kept",
                        savedVersion, guide.getVersion());
            } else {
                log.info("Guide version differs from the saved one ({} → {}), completed steps kept",
                        savedVersion, guide.getVersion());
            }
        }
        persistence.saveGuideVersion(guide.getVersion());

        birdhouseTracker.loadPersisted(persistence.loadBirdhouses());
        tearsOfGuthixTracker.loadPersisted(persistence.loadTearsOfGuthixReset());
        tearsOfGuthixTracker.loadPersistedAdventures(persistence.loadTearsOfGuthixAdventures());
        kingdomTracker.loadPersisted(persistence.loadKingdom());

        resolveAndRebuild();

        log.debug("Loaded {} completed, {} skipped steps", completedSteps.size(), skippedSteps.size());
    }

    /**
     * Forget everything held for the account that played last, so the load starts from an
     * account with nothing saved.
     *
     * <p>Without this, a second account logging in during the same client run would inherit
     * the first account's steps, player state and timers, and its next save would write them
     * into its own profile. A load that throws part-way still leaves part of the account, so
     * nothing may be saved after a failed load.
     *
     * <p>Every per-account field is cleared here except those kept across logins. Kept: the
     * sightings held for the session (they belong to the account logging in and are adopted
     * after the load), the Slayer baseline (dropped at logout instead), the snapshot and its
     * version (the load rebuilds the snapshot, and the panel needs the version to only move
     * forward), and everything built from the guide.
     */
    private void clearAccountState() {
        playerState = null;
        completedSteps.clear();
        skippedSteps.clear();
        suppressedSteps.clear();
        recentManualSteps.clear();
        noPersistedProgress = false;
        resetPending = false;
        currentStepId = null;
        autoCompletedSteps.clear();
        loginResolvePending = false;
        birdhouseTracker.clear();
        tearsOfGuthixTracker.clear();
        kingdomTracker.clear();
    }

    // ---------------------------------------------------------------
    // Event handlers — called from StepwisePlugin @Subscribe methods
    // ---------------------------------------------------------------

    public void onLogin(String playerName, AccountType accountType,
                        Map<String, EventApplier.SkillSnapshot> skills,
                        int questPoints, List<String> completedQuests,
                        List<String> startedQuests,
                        List<ItemStack> inventory,
                        Map<EquipmentSlot, ItemStack> equipment) {

        if (playerState == null) {
            playerState = new PlayerState(playerName, accountType);
        } else {
            playerState.setPlayerName(playerName);
            if (accountType != null) {
                playerState.setAccountType(accountType);
            }
        }

        adoptSightingsSeenThisSession();

        EventApplier.applyLoginState(playerState, skills, questPoints,
                completedQuests, startedQuests, inventory, equipment);

        afterEvent();

        // Milestone auto-latch: only on first login with no persisted progress
        // (see noPersistedProgress).
        if (noPersistedProgress && milestonesFile != null) {
            noPersistedProgress = false;
            performMilestoneLatch();
        }
        loginResolvePending = true;
    }

    /**
     * The steps a game-event flush latched while each was the active step, since the last
     * call, oldest first. Clears the list.
     */
    public List<GuideStep> takeAutoCompletedSteps() {
        List<GuideStep> steps = new ArrayList<>();
        for (StepId id : autoCompletedSteps) {
            steps.add(stepIndex.get(id));
        }
        autoCompletedSteps.clear();
        return steps;
    }

    /**
     * Apply milestone auto-latching: mark all steps up to the furthest cleared milestone's
     * anchor as completed, then rebuild the dashboard. Only called when there is no
     * existing persisted progress.
     */
    void performMilestoneLatch() {
        List<StepId> latched = MilestoneLatcher.computeLatchedSteps(milestonesFile, guide, playerState);
        if (latched.isEmpty()) {
            return;
        }
        completedSteps.addAll(latched);
        persistence.markDirty();
        resolveAndRebuild();
    }

    /**
     * Apply one game event to the player state and mark the state changed. Events before
     * the profile has loaded are dropped: the login scan re-reads everything they carried.
     */
    private void update(Consumer<PlayerState> change) {
        if (playerState == null) return;
        change.accept(playerState);
        afterEvent();
    }

    public void onStatChanged(String skillName, long xp, int level) {
        update(s -> EventApplier.applyStatChanged(s, skillName, xp, level));
    }

    public void onInventoryChanged(List<ItemStack> items) {
        update(s -> s.setInventory(items));
    }

    public void onBankChanged(List<ItemStack> items) {
        update(s -> {
            s.setBank(items);
            s.setBankLastSeen(Instant.now());
        });
    }

    /**
     * Replace the tracked tackle box contents. The game reports this container only when
     * the player opens the tackle box, so like the bank it is a snapshot of the last look.
     */
    public void onTackleBoxChanged(List<ItemStack> items) {
        update(s -> s.setTackleBox(items));
    }

    /** Replace the tracked seed vault contents, reported only when the player opens it. */
    public void onSeedVaultChanged(List<ItemStack> items) {
        update(s -> s.setSeedVault(items));
    }

    /** Replace one boat's cargo hold contents, reported only while the player looks in it. */
    public void onCargoHoldChanged(int slot, List<ItemStack> items) {
        update(s -> s.setCargoHold(slot, items));
    }

    public void onSeedBoxChanged(List<ItemStack> items) {
        update(s -> EventApplier.applySeedBoxChanged(s, items));
    }

    /** Records seeds the player has put in their seed box. */
    public void onSeedBoxStored(ItemStack stored) {
        update(s -> EventApplier.applySeedBoxStored(s, stored));
    }

    /**
     * Records seeds leaving the seed box, emptied into the bag or planted out of it.
     *
     * @param itemName as the game named it; a name the box is not holding is ignored
     * @param quantity how many left, as a positive number
     */
    public void onSeedBoxTaken(String itemName, int quantity) {
        update(s -> EventApplier.applySeedBoxTaken(s, itemName, quantity));
    }

    /**
     * Updates the tracked rune pouch contents (rune item ID → quantity), read from the
     * pouch varbits. Runes stored in a pouch are otherwise invisible to {@code hasItem}
     * checks because they leave the inventory item array.
     */
    public void onRunePouchChanged(Map<Integer, Integer> contents) {
        update(s -> s.setRunePouch(contents));
    }

    /** Called when items leave the inventory while a deposit box is open. */
    public void onDepositInferred(List<ItemStack> depositedItems) {
        update(s -> EventApplier.applyDepositInference(s, depositedItems));
    }

    public void onEquipmentChanged(Map<EquipmentSlot, ItemStack> equipment) {
        update(s -> EventApplier.replaceEquipment(s, equipment));
    }

    public void onQuestCompleted(String questName, int totalQuestPoints) {
        update(s -> {
            s.getQuests().put(questName, QuestStatus.COMPLETED);
            s.setQuestPoints(totalQuestPoints);
        });
        observeKingdomOnQuest(questName);
    }

    public void onQuestProgress(String questName, String questState, Integer newValue) {
        update(s -> EventApplier.applyQuestProgress(s, questName, questState, newValue));
        observeKingdomOnQuest(questName);
    }

    /** Set a kill count to the absolute value a chat message states. */
    public void onKillCount(String boss, long count) {
        update(s -> s.getKillCounts().put(boss, count));
    }

    /** Count one NPC kill detected via ActorDeath. */
    public void onNpcKill(String npcName) {
        update(s -> s.getKillCounts().merge(npcName, 1L, Long::sum));
    }

    public void onCollectionLog(String itemName) {
        update(s -> s.getCollectionLog().add(itemName));
    }

    public void onDiaryCompleted(String area, String difficulty) {
        update(s -> EventApplier.applyDiaryCompleted(s, area, difficulty));
    }

    public void onRegionChanged(int newRegionId) {
        update(s -> s.setRegionId(newRegionId));
        observeKingdomVisit(newRegionId);
    }

    /**
     * Records the bank interface opening or closing, which shows or hides the current step's
     * route-assumption reminders. Nothing is persisted, so only the snapshot is marked stale.
     */
    public void onBankOpenChanged(boolean open) {
        if (playerState == null || playerState.isBankOpen() == open) return;
        playerState.setBankOpen(open);
        resolveDirty = true;
    }

    /**
     * Record a built object seen in the loaded scene, for {@code objectPresent} conditions.
     *
     * <p>Called for every scene-object spawn, thousands per region load. The first check is
     * an allocation-free lookup that rejects almost every spawn; the second dedupes repeat
     * sightings such as house furniture re-spawning on every visit.
     *
     * <p>Reachable before the profile is loaded; see {@link #objectsSeenThisSession}.
     *
     * @param objectId scene object id, from any of the four object-spawn event types
     */
    public void onObjectSpawned(int objectId) {
        if (!watchedObjects.contains(objectId)) {
            return;
        }
        if (!objectsSeenThisSession.add(objectId)) {
            return;
        }
        if (playerState != null && playerState.getObservedObjects().add(objectId)) {
            afterEvent();
        }
    }

    /**
     * Record that the player clicked a tracked menu option on an NPC the guide asks about.
     *
     * <p>The game keeps no record of a conversation, so this is the only evidence an
     * {@code npcInteraction} step has. Reachable before the profile is loaded, like
     * {@link #onObjectSpawned}.
     *
     * @param npcName the NPC as the game names it
     * @param action  the menu option clicked
     */
    public void onNpcInteraction(String npcName, String action) {
        if (!watchedNpcs.watches(npcName)) {
            return;
        }
        String key = NpcInteractions.record(npcName, action);
        if (!npcInteractionsSeenThisSession.add(key)) {
            return;
        }
        if (playerState != null && playerState.getObservedNpcInteractions().add(key)) {
            afterEvent();
        }
    }

    /**
     * Fold this session's sightings (objects built, NPCs spoken to) into the current
     * {@link #playerState}. Called wherever the state is created or replaced. Idempotent:
     * both the session sets and the state's sets are grow-only.
     */
    private void adoptSightingsSeenThisSession() {
        if (playerState == null) {
            return;
        }
        if (!objectsSeenThisSession.isEmpty()) {
            playerState.getObservedObjects().addAll(objectsSeenThisSession);
        }
        if (!npcInteractionsSeenThisSession.isEmpty()) {
            playerState.getObservedNpcInteractions().addAll(npcInteractionsSeenThisSession);
        }
    }

    /**
     * Drop the sightings held for the session that is ending, at a logout or a world hop.
     *
     * <p>The engine outlives sessions, so without this the next login, possibly on another
     * account, would adopt the previous player's sightings into its grow-only profile sets.
     *
     * <p>Nothing is lost: once a session is established every sighting is written straight
     * into {@link #playerState} and saved with it.
     */
    public void forgetSessionSightings() {
        objectsSeenThisSession.clear();
        npcInteractionsSeenThisSession.clear();
    }

    /**
     * Fold one tick's Slayer task var sample in, crediting a master when a task is killed out.
     *
     * <p>Sampled per tick rather than on var changes because the decision needs the remaining
     * count and the streak read together; see {@link SlayerTaskTracker}.
     *
     * <p>Persists a completion immediately. Unlike a varbit-backed fact, nothing can re-read
     * it, so a crash before the next periodic save would lose it.
     */
    public void onSlayerTaskSample(int count, int master, int streak, int wildernessStreak) {
        if (playerState == null) return;

        // `noSlayerTask` reads only whether a task is in hand, so only the zero crossing
        // calls afterEvent. Calling it per kill would mark the profile dirty on every kill.
        //
        // A negative reading (varp never set) is kept as-is: it equals the "not sampled yet"
        // sentinel.
        int previous = playerState.getSlayerTaskCount();
        if (previous != count) {
            playerState.setSlayerTaskCount(count);
            if ((previous == 0) != (count == 0)) {
                afterEvent();
            }
        }

        Integer finished = slayerTasks.observe(count, master, streak, wildernessStreak);
        if (finished == null) return;
        int total = playerState.getSlayerTasksCompleted().merge(finished, 1, Integer::sum);
        log.debug("Slayer task completed for master {} (total {})", finished, total);
        // afterEvent before the save: afterEvent marks the profile dirty and the save clears it.
        afterEvent();
        persistence.forceSave(playerState, completedSteps, skippedSteps, suppressedSteps);
    }

    /** Drop the Slayer baseline at logout, so the next account's first sample re-seeds it. */
    public void onSlayerTrackingReset() {
        slayerTasks.reset();
        if (playerState != null) {
            // The count belongs to the account that just left. Keeping it would answer the
            // next login's first resolve from a stale value before any tick has sampled.
            playerState.setSlayerTaskCount(PlayerState.SLAYER_TASK_COUNT_UNREAD);
        }
    }

    /**
     * Track an arbitrary varbit value change for VarbitValue completion conditions
     * (e.g. individual achievement diary tasks).
     */
    public void onVarbitValueChanged(int varbitId, int value) {
        if (playerState == null) return;
        Integer prev = playerState.getVarbits().get(varbitId);
        if (prev != null && prev == value) return;
        playerState.getVarbits().put(varbitId, value);
        observeTearsOfGuthixVarbit(varbitId, value);
        observeKingdomVarbit(varbitId);
        observeBoatOwnershipVarbit(varbitId, value);
        afterEvent();
    }

    /**
     * Drops a cargo hold snapshot when its boat stops being the player's. The hold goes with
     * the boat, and the next boat in that slot starts empty.
     */
    private void observeBoatOwnershipVarbit(int varbitId, int value) {
        int slot = BoatVarbits.slotOfOwnedVarbit(varbitId);
        if (slot >= 0 && value == 0) {
            playerState.clearCargoHold(slot);
        }
    }

    /**
     * Track a VarPlayer value change for VarpBitValue completion conditions
     * (e.g. individual achievement diary tasks stored as bit fields).
     */
    public void onVarpValueChanged(int varpId, int value) {
        if (playerState == null) return;
        Integer prev = playerState.getVarps().get(varpId);
        if (prev != null && prev == value) return;
        playerState.getVarps().put(varpId, value);
        afterEvent();
    }

    // ---------------------------------------------------------------
    // Bird house varbit events
    // ---------------------------------------------------------------

    /**
     * Fold the current bird house varp values into the tracker; see
     * {@link BirdhouseTracker#update}. Persists on any change.
     *
     * @return true if any house changed, so the plugin should refresh the InfoBoxes
     */
    public boolean updateBirdhouses(Map<BirdhouseTracker.BirdhouseSpace, Integer> varps,
                                    boolean inRegion, long nowEpochSec) {
        boolean changed = birdhouseTracker.update(varps, inRegion, nowEpochSec);
        if (changed) {
            persistence.saveBirdhouses(birdhouseTracker.exportForPersist());
        }
        return changed;
    }

    /**
     * Start the weekly Tears of Guthix clock when the in-cave tick bar starts running.
     * See {@link TearsOfGuthixTracker} for why the visit is stamped rather than read.
     */
    private void observeTearsOfGuthixVarbit(int varbitId, int value) {
        if (varbitId != TearsOfGuthixTracker.IN_CAVE_TICKS_VARBIT) {
            return;
        }
        // Entering the cave starts both the weekly clock and the adventuring gate, so the
        // tracker arms them together.
        if (tearsOfGuthixTracker.observeVisit(value, Instant.now().getEpochSecond(),
                playerState != null ? playerState.getTotalXp() : -1L,
                playerState != null ? playerState.getQuestPoints() : -1)) {
            saveTearsOfGuthix();
        }
    }

    private void saveTearsOfGuthix() {
        persistence.saveTearsOfGuthixReset(tearsOfGuthixTracker.exportForPersist());
        persistence.saveTearsOfGuthixAdventures(
                tearsOfGuthixTracker.exportAdventuresForPersist());
    }

    /** Fold a live change to one of the kingdom's varbits into {@link #kingdomTracker}. */
    private void observeKingdomVarbit(int varbitId) {
        for (int id : KingdomTracker.VARBIT_IDS) {
            if (id == varbitId) {
                observeKingdom();
                return;
            }
        }
    }

    /**
     * Primes {@link #kingdomTracker} from the login scan, which writes the kingdom varbits
     * straight into playerState and so bypasses {@link #onVarbitValueChanged}. Safe to call
     * every login: an unchanged observation is a no-op. A login on the islands needs no visit
     * here, because the region tracker announces the first region of every session.
     */
    public void primeKingdomFromLogin() {
        observeKingdom();
    }

    /**
     * Finishing Throne of Miscellania changes no kingdom varbit, so nothing else would observe
     * the kingdom before the next login, and the Kingdom row would stay hidden until then.
     */
    private void observeKingdomOnQuest(String questName) {
        if (KingdomTracker.QUEST_NAME.equals(questName)) {
            observeKingdom();
        }
    }

    private void observeKingdom() {
        if (!KingdomTracker.questCompleted(playerState)) {
            return;
        }
        Map<Integer, Integer> varbits = playerState.getVarbits();
        kingdomTracker.observeAllocation(varbits);
        if (kingdomTracker.observe(
                varbits.getOrDefault(KingdomTracker.APPROVAL_VARBIT, 0),
                varbits.getOrDefault(KingdomTracker.COFFER_VARBIT, 0),
                varbits.getOrDefault(KingdomTracker.POOL_VARBIT, 0),
                Instant.now().getEpochSecond())) {
            persistence.saveKingdom(kingdomTracker.exportForPersist());
        }
    }

    /** Standing on Miscellania or Etceteria counts as a visit, which holds off the 30-day pause. */
    private void observeKingdomVisit(int regionId) {
        if (!KingdomTracker.isKingdomRegion(regionId)
                || !KingdomTracker.questCompleted(playerState)) {
            return;
        }
        if (kingdomTracker.markVisit(Instant.now().getEpochSecond())) {
            persistence.saveKingdom(kingdomTracker.exportForPersist());
        }
    }

    /**
     * Offer a game chat line to the Tears of Guthix clock, for Juna's eligibility notice.
     *
     * <p>Offered every game message, so the cheap match runs first.
     */
    public void onTearsOfGuthixMessage(String message) {
        if (!TearsOfGuthixTracker.isEligibilityMessage(message)) {
            return;
        }
        if (tearsOfGuthixTracker.markEligible(Instant.now().getEpochSecond())) {
            saveTearsOfGuthix();
            afterEvent();
        }
    }

    /**
     * Offer a line of NPC dialogue, or a message box, to the Tears of Guthix clock.
     *
     * <p>Juna's refusal arms the adventuring gate (100,000 experience or a quest point since
     * the last visit) from the current totals unless a cave entry already holds an unmet
     * baseline, and any line of hers that states the wait sets the clock.
     *
     * @param dialogue one line, its widget tags already stripped
     * @return true if anything moved
     */
    public boolean onTearsOfGuthixDialogue(String dialogue) {
        if (playerState == null || !TearsOfGuthixTracker.questCompleted(playerState)) {
            return false;
        }
        TearsOfGuthixTracker.JunaLine line = TearsOfGuthixTracker.parseJunaLine(dialogue);
        if (line == null) {
            if (TearsOfGuthixTracker.isJunaSpeaking(dialogue)) {
                log.debug("Juna said something unread: {}", dialogue);
            }
            return false;
        }
        if (!tearsOfGuthixTracker.applyJunaLine(line, Instant.now().getEpochSecond(),
                playerState.getTotalXp(), playerState.getQuestPoints())) {
            return false;
        }
        saveTearsOfGuthix();
        afterEvent();
        log.debug("Tears of Guthix clock set from Juna: {} day(s), adventures needed: {}",
                line.getDaysRemaining(), line.isWantsAdventures());
        return true;
    }

    /**
     * Set the Tears of Guthix clock from the journal page the player has open.
     *
     * <p>An unreadable page is logged, not guessed at: the sentence is composed by the
     * server.
     *
     * @param journalText the page's text, its widget tags already stripped
     * @return true if the clock moved
     */
    public boolean onTearsOfGuthixJournal(String journalText) {
        // Before the quest is finished the page is a walkthrough with no weekly visit to clock.
        if (!TearsOfGuthixTracker.questCompleted(playerState)) {
            return false;
        }
        int days = TearsOfGuthixTracker.parseJournalDays(journalText);
        if (days == TearsOfGuthixTracker.JOURNAL_DAYS_UNREAD) {
            log.debug("Tears of Guthix journal page states no readable wait: {}", journalText);
            return false;
        }
        if (!tearsOfGuthixTracker.setWaitDays(days, Instant.now().getEpochSecond())) {
            return false;
        }
        saveTearsOfGuthix();
        afterEvent();
        log.debug("Tears of Guthix clock set from the quest journal: {} day(s)", days);
        return true;
    }

    /**
     * Refine one bird house's timer from a "Seed level is: X/10" check dialog.
     */
    public void applyBirdhouseSeedProbe(BirdhouseTracker.BirdhouseSpace space,
                                        int seedLevel, long nowEpochSec) {
        birdhouseTracker.applySeedProbe(space, seedLevel, nowEpochSec);
        persistence.saveBirdhouses(birdhouseTracker.exportForPersist());
    }

    // ---------------------------------------------------------------
    // Manual step overrides
    // ---------------------------------------------------------------

    /**
     * Mark a step as done. Safe to call from any thread — if called from the EDT,
     * the actual mutation is dispatched to the client thread.
     */
    public void markStepDone(StepId stepId) {
        Runnable action = () -> {
            flushBeforeClick();
            completedSteps.add(stepId);
            skippedSteps.remove(stepId);
            suppressedSteps.remove(stepId);
            resetKillCountsForStep(stepId);
            recordManualAction(stepId);
            persistence.markDirty();
            resolveAndRebuild();
            log.debug("Step {} marked done", stepId.getValue());
        };
        runOnClientThread(action);
    }

    /**
     * Skip a step. Safe to call from any thread.
     */
    public void skipStep(StepId stepId) {
        Runnable action = () -> {
            flushBeforeClick();
            skippedSteps.add(stepId);
            completedSteps.remove(stepId);
            recordManualAction(stepId);
            persistence.markDirty();
            resolveAndRebuild();
            log.debug("Step {} skipped", stepId.getValue());
        };
        runOnClientThread(action);
    }

    /**
     * Skip several steps as one action. Safe to call from any thread.
     *
     * <p>Batched {@link #skipStep}: skipping every step of a run of guide entries resolves and
     * redraws once, not once per step. Unlike {@link #skipStep} it records nothing in
     * {@link #recentManualSteps}: the batch moves the active step past the skipped steps, so
     * Recent's rows behind the active step already offer Undo on its tail, and recording
     * each step would push the player's own clicks out of the bounded list.
     */
    public void skipSteps(Collection<StepId> stepIds) {
        if (stepIds == null || stepIds.isEmpty()) {
            return;
        }
        List<StepId> batch = new ArrayList<>(stepIds);
        Runnable action = () -> {
            flushBeforeClick();
            for (StepId stepId : batch) {
                skippedSteps.add(stepId);
                completedSteps.remove(stepId);
            }
            persistence.markDirty();
            resolveAndRebuild();
            log.debug("{} steps skipped: {}", batch.size(), batch);
        };
        runOnClientThread(action);
    }

    /**
     * Undo a step completion. Safe to call from any thread.
     */
    public void undoStep(StepId stepId) {
        Runnable action = () -> {
            flushBeforeClick();
            completedSteps.remove(stepId);
            skippedSteps.remove(stepId);
            suppressedSteps.add(stepId);
            if (recentManualSteps.remove(stepId)) {
                persistence.saveRecentManualSteps(recentManualSteps);
            }
            persistence.markDirty();
            resolveAndRebuild();
            log.debug("Step {} undone, still suppressed: {}", stepId.getValue(),
                    suppressedSteps.contains(stepId));
        };
        runOnClientThread(action);
    }

    /**
     * Resolve the game events still waiting for the tick flush before a click changes the
     * guide state. Otherwise the click's resolve, which never announces, would latch a step
     * the game finished and its notification would be lost.
     */
    private void flushBeforeClick() {
        flushIfDirty();
    }

    /**
     * Put a Mark Done or Skip click at the head of {@link #recentManualSteps} and save the list
     * at once, so a crash before the next debounced save still leaves its Undo. Runs on the
     * client thread with the action it records.
     */
    private void recordManualAction(StepId stepId) {
        recentManualSteps.remove(stepId);
        recentManualSteps.add(0, stepId);
        while (recentManualSteps.size() > RECENT_MANUAL_LIMIT) {
            recentManualSteps.remove(recentManualSteps.size() - 1);
        }
        persistence.saveRecentManualSteps(recentManualSteps);
    }

    /** The latest Mark Done and Skip clicks, newest first. */
    List<StepId> getRecentManualSteps() {
        return Collections.unmodifiableList(recentManualSteps);
    }

    // ---------------------------------------------------------------
    // Guide progress reset
    // ---------------------------------------------------------------

    /**
     * Wipe all guide progression (completed, skipped, suppressed steps). Creates a fresh
     * PlayerState carrying over only what live game state cannot re-supply, force-saves it,
     * and sets {@link #resetPending} so StepwisePlugin re-runs the full login scan on the next
     * game tick.
     *
     * <p>Safe to call from any thread.
     */
    public void resetGuideProgress() {
        Runnable action = () -> {
            completedSteps.clear();
            skippedSteps.clear();
            suppressedSteps.clear();
            recentManualSteps.clear();
            persistence.saveRecentManualSteps(recentManualSteps);

            PlayerState old = playerState;
            playerState = old == null ? new PlayerState(null, null)
                    : new PlayerState(old.getPlayerName(), old.getAccountType());
            if (old != null) {
                // Preserve bank, tackle box, seed vault, seed box and cargo holds: each is
                // reported only when the player opens it. Losing the seed box would make
                // carried seeds read as missing.
                if (old.getBank() != null) {
                    playerState.setBank(old.getBank());
                }
                playerState.setBankLastSeen(old.getBankLastSeen());
                playerState.setTackleBox(old.getTackleBox());
                playerState.setSeedVault(old.getSeedVault());
                playerState.setSeedBox(old.getSeedBox());
                old.getCargoHolds().forEach(playerState::setCargoHold);
                // Finished Slayer tasks, object sightings and NPC conversations have no game
                // var to re-read; these sets are their only record. A quest dialogue cannot be
                // re-opened once the quest moves past it.
                playerState.getSlayerTasksCompleted().putAll(old.getSlayerTasksCompleted());
                playerState.getObservedObjects().addAll(old.getObservedObjects());
                playerState.getObservedNpcInteractions().addAll(old.getObservedNpcInteractions());
            }

            persistence.forceSave(playerState, completedSteps, skippedSteps, suppressedSteps);

            lastSnapshot = null;
            snapshotVersion++;

            resetPending = true;

            log.info("Guide progress reset (bank preserved: {} items, tackle box: {} items, "
                            + "seed vault: {} items, seed box: {} items, cargo holds: {}, "
                            + "observed objects: {})",
                    playerState.getBank().size(), playerState.getTackleBox().size(),
                    playerState.getSeedVault().size(), playerState.getSeedBox().size(),
                    playerState.getCargoHolds().size(), playerState.getObservedObjects().size());
        };
        runOnClientThread(action);
    }

    /**
     * Clear the bank snapshot from PlayerState, independently of guide progress. Safe to
     * call from any thread.
     */
    public void clearBankSnapshot() {
        // Called from a panel button on the EDT. PlayerState readings are plain fields that
        // rely on client-thread-only access, so the mutation must hop threads.
        runOnClientThread(() -> {
            if (playerState == null) {
                return;
            }
            flushBeforeClick();
            playerState.setBank(Collections.emptyList());
            playerState.setBankLastSeen(null);
            persistence.markDirty();
            resolveAndRebuild();
            log.info("Bank snapshot cleared");
        });
    }

    /**
     * Clear all bird house timers and their persisted state, independently of
     * {@link #resetGuideProgress()}. Houses in view re-discover at a fresh 50 minutes.
     * Safe to call from any thread.
     */
    public void resetBirdhouseTimers() {
        runOnClientThread(() -> {
            birdhouseTracker.clear();
            persistence.saveBirdhouses(Collections.emptyList());
            markTimersDirty();
            log.info("Bird house timers reset");
        });
    }

    /**
     * Bump the snapshot version so the side panel refreshes on the next tick. Bird house
     * timers change without a guide event, which would not move
     * {@link #snapshotVersion}. Client-thread only.
     */
    public void markTimersDirty() {
        snapshotVersion++;
    }

    public boolean isResetPending() {
        return resetPending;
    }

    /** Consume the reset-pending flag after StepwisePlugin has re-scanned. */
    public void consumeResetPending() {
        this.resetPending = false;
    }

    // ---------------------------------------------------------------
    // Periodic save (call from GameTick)
    // ---------------------------------------------------------------

    public void tickSave() {
        persistence.saveIfNeeded(playerState, completedSteps, skippedSteps, suppressedSteps);
    }

    public void forceSave() {
        persistence.forceSave(playerState, completedSteps, skippedSteps, suppressedSteps);
        saveSessionSummary();
    }

    /**
     * Update the session summary in non-profile config, so the welcome screen can show
     * "last session" info before the next login.
     *
     * <p>Skipped while the player's name is unknown, which a login that gave up waiting for
     * it can leave. The welcome page heads the summary with the name, so the previous summary
     * stays rather than one with no name.
     */
    public void saveSessionSummary() {
        if (lastSnapshot == null || lastSnapshot.getGuidePosition() == null) {
            return;
        }
        String playerName = playerState != null ? playerState.getPlayerName() : null;
        if (playerName == null || playerName.isBlank()) {
            return;
        }
        GuidePosition pos = lastSnapshot.getGuidePosition();
        persistence.saveSessionSummary(
                playerName,
                pos.getStepIndex(),
                pos.getTotalSteps(),
                pos.getChapter(),
                completedSteps.size(),
                guide.minutesDone(completedSteps),
                guide.getTotalMinutes());
    }

    // ---------------------------------------------------------------
    // Internal
    // ---------------------------------------------------------------

    /**
     * Run an action on the client thread via {@link #clientThreadExecutor}, or inline when
     * none is set.
     */
    private void runOnClientThread(Runnable action) {
        if (clientThreadExecutor != null) {
            clientThreadExecutor.accept(action);
        } else {
            action.run();
        }
    }

    private void afterEvent() {
        persistence.markDirty();
        resolveDirty = true;
    }

    /**
     * Resolve once if any event dirtied state since the last flush. StepwisePlugin calls it
     * each game tick and once the login scan finishes. Mark Done, Skip, Undo and clearing the
     * bank snapshot call it before they change the state.
     */
    public void flushIfDirty() {
        if (resolveDirty) {
            resolveDirty = false;
            // The flush after a login scan (login, world hop or reset) checks off steps the
            // game already shows done. That is not news, so it does not notify.
            boolean announce = !loginResolvePending;
            loginResolvePending = false;
            resolveAndRebuild(announce);
        }
    }

    /**
     * Trigger a resolve-and-rebuild pass after external state changes
     * (e.g. bulk var population at login). Marks persistence dirty.
     */
    public void triggerResolve() {
        afterEvent();
    }

    /**
     * Returns true if every prerequisite of the step is completed or skipped. A step at the
     * reachable frontier whose transient condition is met reflects the player doing it, not
     * coincidental game state.
     *
     * <p>Reads the persisted completed/skipped sets, unlike the resolver's frontier check,
     * which uses the in-progress resolve map. The resolveAndRebuild fixpoint loop reconciles
     * the two by re-resolving after each latch iteration.
     */
    private boolean prerequisitesComplete(GuideStep step) {
        return prerequisitesCompleteExcept(step, null);
    }

    /** As {@link #prerequisitesComplete}, but the {@code except} prerequisite need not be done. */
    private boolean prerequisitesCompleteExcept(GuideStep step, StepId except) {
        if (step.getPrerequisites() == null || step.getPrerequisites().isEmpty()) {
            return true;
        }
        for (StepId prereq : step.getPrerequisites()) {
            if (!prereq.equals(except)
                    && !completedSteps.contains(prereq) && !skippedSteps.contains(prereq)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Returns true if a downstream consumer whose completion proves this WHOLE step was done is
     * already complete. Only the edges {@link #frontierServesEdges} yields qualify. An arm's edge
     * under an {@code all} composite proves only that arm, and
     * {@link ResolutionEngine#evaluateCondition} already credits it while still demanding the
     * other arms; counting it here would latch the whole step off one arm's consumer.
     */
    private boolean wholeStepServedComplete(GuideStep step) {
        for (StepId served : frontierServesEdges(step.getCompletion())) {
            if (completedSteps.contains(served)) return true;
        }
        return false;
    }

    /**
     * Whether the stock this step gathers has already gone into the steps it serves, read from
     * those steps' own conditions. A consumer gated on this step trusts a met held-item reading
     * only once this step is complete, and this step's served arm is waived only once that
     * consumer has latched. A player who spent the stock before this step latched would wait
     * here for good: once larupia furs are sewn into a fur pouch, the player holds the pouch
     * and no furs are left to count.
     *
     * <p>The condition's own {@code servesSteps} are checked first. Under an {@code all}
     * composite, every required arm that is not met must be covered by {@link #stockSpent};
     * under an {@code any} composite, one covered arm is enough.
     */
    private boolean servedStockSpent(GuideStep step) {
        CompletionCondition condition = step.getCompletion();
        if (stockSpent(condition, step.getId())) {
            return true;
        }
        if (!(condition instanceof CompletionCondition.Composite)) {
            return false;
        }
        CompletionCondition.Composite composite = (CompletionCondition.Composite) condition;
        boolean all = composite.getMode() == CompositeMode.ALL;
        boolean anySpent = false;
        for (CompletionCondition sub : composite.getConditions()) {
            boolean spent = stockSpent(sub, step.getId());
            if (!all && spent) {
                return true;
            }
            if (all && !sub.isOptional() && !spent
                    && !ResolutionEngine.evaluateCondition(sub, playerState, completedSteps)) {
                return false;
            }
            anySpent |= spent;
        }
        return all && anySpent;
    }

    /**
     * Whether every step this condition serves is done, or reads met with this condition's
     * step as its only unfinished prerequisite. Every consumer must qualify: stock bought for
     * two steps is not spent when the first of them is done (cosmic runes for both the earth
     * orbs and the air orb).
     */
    private boolean stockSpent(CompletionCondition condition, StepId producer) {
        List<StepId> serves = condition.getServesSteps();
        if (serves.isEmpty() || ResolutionEngine.unmetProvesIncomplete(condition)) {
            return false;
        }
        for (StepId served : serves) {
            if (!completedSteps.contains(served) && !skippedSteps.contains(served)
                    && !consumerMet(served, producer)) {
                return false;
            }
        }
        return true;
    }

    /** Whether a consumer reads met now and waits on no prerequisite but its producer. */
    private boolean consumerMet(StepId consumerId, StepId producer) {
        GuideStep consumer = stepIndex.get(consumerId);
        if (consumer == null || suppressedSteps.contains(consumerId)) {
            return false;
        }
        if (!prerequisitesCompleteExcept(consumer, producer)) {
            return false;
        }
        return ResolutionEngine.evaluateCondition(consumer.getCompletion(), playerState, completedSteps);
    }

    /**
     * Returns true if the step is a pure travel step: locationReached condition with no
     * servesSteps edges. These steps exist only for narrative flow ("go to Varrock") and
     * can be auto-completed when the player is already past the destination.
     */
    private static boolean isPureTravelStep(GuideStep step) {
        CompletionCondition condition = step.getCompletion();
        if (!(condition instanceof CompletionCondition.LocationReached)) {
            return false;
        }
        List<StepId> serves = condition.getServesSteps();
        return serves == null || serves.isEmpty();
    }

    /**
     * Returns true if any step that lists this step as a prerequisite is completed or has
     * its condition met by the current game state, proving the player is past this step.
     */
    private boolean anyDependentConditionMet(StepId stepId) {
        Set<StepId> dependents = prerequisiteOf.get(stepId);
        if (dependents == null || playerState == null) return false;
        for (StepId dep : dependents) {
            if (completedSteps.contains(dep)) return true;
            GuideStep depStep = stepIndex.get(dep);
            if (depStep != null
                    && ResolutionEngine.evaluateCondition(depStep.getCompletion(), playerState)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Strict variant of {@link #anyDependentConditionMet}: true only if a dependent is in
     * {@code completedSteps}. Used for softLatch steps, so coincidental game state (holding a
     * common item the next step needs) cannot latch them.
     */
    private boolean anyDependentCompleted(StepId stepId) {
        Set<StepId> dependents = prerequisiteOf.get(stepId);
        if (dependents == null) return false;
        for (StepId dep : dependents) {
            if (completedSteps.contains(dep)) return true;
        }
        return false;
    }

    /**
     * Whether this step would auto-latch right now, ignoring its own suppression. The
     * auto-latch loop and the check that lifts an undone step's suppression both use it, so
     * they cannot disagree.
     *
     * <p>The loop latches through serves-edge catch-up, pure-travel and soft-latch pathways
     * as well as the direct condition. A suppression clear that checked only the direct
     * condition would release a step the loop then re-latches, reverting the user's undo.
     *
     * @param id     the step to test
     * @param status the step's status from the current (suppression-aware) resolve pass; passed
     *               in to avoid an O(n) lookup per call inside the latch loop
     */
    private boolean isAutoLatchable(StepId id, StepStatus status) {
        if (completedSteps.contains(id) || skippedSteps.contains(id)) {
            return false;
        }
        GuideStep step = stepIndex.get(id);
        if (step == null) {
            return false;
        }
        // Direct pathway: the resolve pass already considers it complete, or (for a suppressed
        // step, whose status is forced to ACTIVE/PENDING) its raw condition is met now. The
        // second check matters only to the suppression clear; for a non-suppressed step the
        // first dominates it. It mirrors the resolve pass's trust gate: a met transient
        // condition counts only at the prerequisite frontier.
        if (status == StepStatus.COMPLETED) {
            return true;
        }
        if ((ResolutionEngine.isMonotonic(step.getCompletion()) || prerequisitesComplete(step))
                && ResolutionEngine.evaluateCondition(
                        step.getCompletion(), playerState, completedSteps)) {
            return true;
        }
        // Durable-evidence pathway, mirroring the resolve pass's login/reset pre-scan. Needed
        // because isMonotonic is mode-blind and strict: an `any` composite with one
        // durable arm beside a regressing one reads non-monotonic above, yet the pre-scan latches
        // it through the durable arm. Without this the suppression clear would revert an undo of
        // such a step. Adds no latch for a non-suppressed step.
        if (ResolutionEngine.monotonicallyMet(step.getCompletion(), playerState)) {
            return true;
        }
        // Backward-DAG/serves closure, checked BEFORE the ACTIVE gate because ResolutionEngine's
        // closure walk is not frontier- or ACTIVE-gated: a step whose consumers are complete
        // resolves COMPLETED once un-suppressed, however far ahead it sits. Uses the resolver's
        // own composite-aware predicate so the two never diverge.
        if (!ResolutionEngine.unmetProvesIncomplete(step.getCompletion())
                && ResolutionEngine.allServedStepsComplete(step.getCompletion(), completedSteps)) {
            return true;
        }
        // Remaining catch-up pathways fire only at the frontier. BACKGROUND counts: a background
        // step is reachable and merely declines the pointer.
        if (status != StepStatus.ACTIVE && status != StepStatus.BACKGROUND) {
            return false;
        }
        // Frontier prep-step catch-up: a step latches once a consumer that proves the whole step
        // is complete (see frontierServesEdges). Looser than the closure check above, and safe
        // because it fires only at the frontier.
        if (wholeStepServedComplete(step)) {
            return true;
        }
        if (servedStockSpent(step)) {
            return true;
        }
        if (isPureTravelStep(step) && anyDependentConditionMet(id)) {
            return true;
        }
        return step.isSoftLatch() && anyDependentCompleted(id);
    }

    private void resetKillCountsForStep(StepId stepId) {
        if (playerState == null) return;
        GuideStep step = stepIndex.get(stepId);
        if (step == null || step.getCompletion() == null) return;
        resetKillCountsInCondition(step.getCompletion());
    }

    private void resetKillCountsInCondition(CompletionCondition condition) {
        if (condition instanceof CompletionCondition.KillCount) {
            String target = ((CompletionCondition.KillCount) condition).getTarget();
            playerState.getKillCounts().remove(target);
        } else if (condition instanceof CompletionCondition.Composite) {
            for (CompletionCondition sub : ((CompletionCondition.Composite) condition).getConditions()) {
                resetKillCountsInCondition(sub);
            }
        }
    }

    /**
     * Resolve, auto-latch to a fixpoint, and rebuild the snapshot. Never announces a
     * completion: only {@link #flushIfDirty} does.
     */
    private void resolveAndRebuild() {
        resolveAndRebuild(false);
    }

    /**
     * As {@link #resolveAndRebuild()}, recording the active step for
     * {@link #takeAutoCompletedSteps} when {@code announce} is set and that step latches.
     */
    private void resolveAndRebuild(boolean announce) {
        if (playerState == null) return;
        StepId activeBefore = currentStepId;
        boolean activeLatched = false;

        List<ResolvedStep> resolved = ResolutionEngine.resolveSteps(
                playerState, guide, completedSteps, skippedSteps, suppressedSteps);

        // Release a user's undo suppression only once no pathway would auto-latch the step
        // (see isAutoLatchable). A later genuine re-reach can then auto-complete it again.
        Map<StepId, StepStatus> statusByStep = new HashMap<>();
        for (ResolvedStep rs : resolved) {
            statusByStep.put(rs.getStepId(), rs.getStatus());
        }
        suppressedSteps.removeIf(id ->
                !isAutoLatchable(id, statusByStep.getOrDefault(id, StepStatus.PENDING)));

        // Auto-latch every latchable, unsuppressed step (pathways in isAutoLatchable). Pure
        // travel steps latch once a dependent's condition is met, which covers a player in the
        // right city but a different map chunk from the one locationReached names.
        //
        // Fixpoint loop: a softLatch step waits for its dependent to be in completedSteps, and
        // that dependent may be latched in this same pass. Re-resolving between iterations lets
        // the cascade converge in one call. Each step latches at most once, so the step count
        // caps the loop. directLatched collects, across iterations, the steps latched on their
        // own directly-met condition, for the retract check below.
        Set<StepId> directLatched = new HashSet<>();
        int maxIterations = guide.allSteps().size();
        for (int iteration = 0; iteration < maxIterations; iteration++) {
            boolean latched = false;
            for (ResolvedStep rs : resolved) {
                StepId id = rs.getStepId();
                if (suppressedSteps.contains(id)) {
                    continue;
                }
                if (isAutoLatchable(id, rs.getStatus())) {
                    completedSteps.add(id);
                    activeLatched |= id.equals(activeBefore);
                    // Record latch provenance for the retract check. A catch-up latch (serves
                    // edge, closure, pure-travel, softLatch) legitimately has an unmet direct
                    // condition and must never be retracted. Evaluated before
                    // resetKillCountsForStep, which would un-meet a killCount sub-condition.
                    GuideStep step = stepIndex.get(id);
                    if (step != null && ResolutionEngine.evaluateCondition(
                            step.getCompletion(), playerState, completedSteps)) {
                        directLatched.add(id);
                    }
                    latched = true;
                    log.debug("Auto-latched step {} as completed", id.getValue());
                    resetKillCountsForStep(id);
                }
            }

            if (!latched) {
                break;
            }
            resolved = ResolutionEngine.resolveSteps(
                    playerState, guide, completedSteps, skippedSteps, suppressedSteps);
        }

        // Retract the step immediately before active if it was direct-latched this cycle and
        // its condition is no longer met: a bank withdrawal step can latch briefly before the
        // items leave the inventory again. Manual, persisted and catch-up latches are never
        // retracted; retracting a catch-up latch would oscillate with its pathway.
        if (!directLatched.isEmpty()) {
            StepId lastCompleted = null;
            for (ResolvedStep rs : resolved) {
                if (rs.getStatus() == StepStatus.ACTIVE) break;
                if (rs.getStatus() == StepStatus.COMPLETED) lastCompleted = rs.getStepId();
            }
            if (lastCompleted != null && directLatched.contains(lastCompleted)) {
                GuideStep lastStep = stepIndex.get(lastCompleted);
                if (lastStep != null && hasInventoryCondition(lastStep.getCompletion())
                        && !ResolutionEngine.evaluateCondition(
                                lastStep.getCompletion(), playerState, completedSteps)
                        && !ResolutionEngine.allServedStepsComplete(
                                lastStep.getCompletion(), completedSteps)) {
                    completedSteps.remove(lastCompleted);
                    resolved = ResolutionEngine.resolveSteps(
                            playerState, guide, completedSteps, skippedSteps, suppressedSteps);
                    log.debug("Retracted step {} (auto-latched but items left inventory)",
                            lastCompleted.getValue());
                }
            }
        }

        if (announce && activeLatched && completedSteps.contains(activeBefore)) {
            autoCompletedSteps.add(activeBefore);
        }

        StepId activeStepId = null;
        for (ResolvedStep rs : resolved) {
            if (rs.getStatus() == StepStatus.ACTIVE) {
                activeStepId = rs.getStepId();
                if (stepIndex.containsKey(activeStepId)) {
                    currentStepId = activeStepId;
                }
                break;
            }
        }

        DashboardSnapshot newSnapshot = SnapshotBuilder.buildSnapshot(
                playerState, guide, currentStepId, stepIndex, guide.stepContextMap(), resolved,
                recentManualSteps);

        // Bump the version only on a displayed change, so frequent var events don't make the
        // panel rebuild and flicker.
        if (!snapshotContentEquals(lastSnapshot, newSnapshot)) {
            snapshotVersion++;
        }
        lastSnapshot = newSnapshot;
    }

    /**
     * Compare two snapshots by display-relevant fields only.
     *
     * <p>Every drawn field that can move without the guide position moving is compared here,
     * so its part of the panel redraws.
     */
    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    static boolean snapshotContentEquals(DashboardSnapshot a, DashboardSnapshot b) {
        if (a == null || b == null) {
            return a == b;
        }
        GuidePosition posA = a.getGuidePosition();
        GuidePosition posB = b.getGuidePosition();
        if ((posA == null) != (posB == null)) {
            return false;
        }
        if (posA != null && (!Objects.equals(posA.getStepId(), posB.getStepId())
                || posA.getStepIndex() != posB.getStepIndex())) {
            return false;
        }
        if (!currentStepEqual(a.getCurrentStep(), b.getCurrentStep())) {
            return false;
        }
        if (!detailedListEqual(a.getNextDetailed(), b.getNextDetailed())) {
            return false;
        }
        // Compared in full. Recent lists only the first two completions ahead of the active
        // step, so a step completing further down the Upcoming one-liners changes this list
        // and nothing else in the snapshot.
        if (!Objects.equals(a.getNextSteps(), b.getNextSteps())) {
            return false;
        }
        if (!detailedListEqual(a.getBackgroundSteps(), b.getBackgroundSteps())) {
            return false;
        }
        if (!Objects.equals(a.getRouteDeficit(), b.getRouteDeficit())) {
            return false;
        }
        if (!Objects.equals(a.getKingdomHardwood(), b.getKingdomHardwood())) {
            return false;
        }
        return detailedListEqual(a.getRecentCompleted(), b.getRecentCompleted());
    }

    private static boolean currentStepEqual(CurrentStepSummary a, CurrentStepSummary b) {
        if ((a == null) != (b == null)) {
            return false;
        }
        if (a == null) {
            return true;
        }
        // Items-needed entries are discrete display fields, so list equality catches an
        // ownership flip; without it ItemsNeededView never sees the change.
        // The assumption nudges come and go with the bank, which moves nothing else, so
        // without them opening the bank would not redraw.
        return criterionListEqual(a.getCriteria(), b.getCriteria())
                && Objects.equals(a.getItemsNeeded(), b.getItemsNeeded())
                && Objects.equals(a.getAssumptionNudges(), b.getAssumptionNudges());
    }

    private static boolean criterionListEqual(List<CompletionCriterion> a, List<CompletionCriterion> b) {
        if ((a == null) != (b == null)) {
            return false;
        }
        if (a == null) {
            return true;
        }
        if (a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            CompletionCriterion ca = a.get(i);
            CompletionCriterion cb = b.get(i);
            if (ca.isMet() != cb.isMet()) {
                return false;
            }
            if (!Objects.equals(ca.getDescription(), cb.getDescription())) {
                return false;
            }
            if (ca.getProgress() != null && cb.getProgress() != null) {
                if (ca.getProgress().getCurrent() != cb.getProgress().getCurrent()) {
                    return false;
                }
            } else if ((ca.getProgress() == null) != (cb.getProgress() == null)) {
                return false;
            }
        }
        return true;
    }

    private static boolean detailedListEqual(List<DetailedStep> a, List<DetailedStep> b) {
        if ((a == null) != (b == null)) {
            return false;
        }
        if (a == null) {
            return true;
        }
        if (a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (!Objects.equals(a.get(i).getStepId(), b.get(i).getStepId())
                    || a.get(i).isSkipped() != b.get(i).isSkipped()) {
                return false;
            }
            if (!criterionListEqual(a.get(i).getCriteria(), b.get(i).getCriteria())) {
                return false;
            }
        }
        return true;
    }

    /**
     * Returns true if the condition, or any composite sub-condition, is a {@code hasItem} or
     * {@code hasItemTotal} check with {@code location=inventory}. Identifies steps eligible
     * for same-cycle retraction when items leave the inventory.
     */
    static boolean hasInventoryCondition(CompletionCondition condition) {
        if (condition instanceof CompletionCondition.HasItem) {
            return ((CompletionCondition.HasItem) condition).getLocation() == ItemLocation.INVENTORY;
        }
        if (condition instanceof CompletionCondition.HasItemTotal) {
            return ((CompletionCondition.HasItemTotal) condition).getLocation() == ItemLocation.INVENTORY;
        }
        if (condition instanceof CompletionCondition.Composite) {
            for (CompletionCondition sub : ((CompletionCondition.Composite) condition).getConditions()) {
                if (hasInventoryCondition(sub)) return true;
            }
        }
        return false;
    }

    /**
     * The {@code servesSteps} targets whose completion proves the whole step was done: the
     * edge set the frontier catch-up reads.
     * <ul>
     *   <li>A plain condition contributes its own list.</li>
     *   <li>An {@code any} composite contributes its own list and recurses into every arm,
     *       because one arm completes the step.</li>
     *   <li>An {@code all} composite never contributes its arms' edges, because an arm's
     *       consumer proves only that arm ({@link ResolutionEngine#evaluateCondition} credits
     *       it per arm). It contributes its own list only when no arm carries an edge: that
     *       list joins every arm's consumers, so reading it beside edged arms would complete
     *       the whole step as soon as any one arm's consumer finished.</li>
     * </ul>
     * The {@code optional} flag is not consulted.
     *
     * <p>Not the set {@link ResolutionEngine#allServedStepsComplete} reads: that check fails an
     * {@code all} composite at its first edgeless arm, and reads the node's own list only after
     * every edged arm has passed.
     */
    static Set<StepId> frontierServesEdges(CompletionCondition condition) {
        Set<StepId> out = new HashSet<>();
        collectFrontierServesEdges(condition, out);
        return out;
    }

    private static void collectFrontierServesEdges(CompletionCondition condition, Set<StepId> out) {
        if (condition == null) return;
        if (condition instanceof CompletionCondition.Composite) {
            CompletionCondition.Composite composite = (CompletionCondition.Composite) condition;
            if (composite.getMode() == CompositeMode.ALL) {
                boolean anyArmEdged = false;
                for (CompletionCondition sub : composite.getConditions()) {
                    if (carriesAnyServesEdge(sub)) {
                        anyArmEdged = true;
                        break;
                    }
                }
                if (!anyArmEdged && composite.getServesSteps() != null) {
                    out.addAll(composite.getServesSteps());
                }
                return;
            }
            if (composite.getServesSteps() != null) {
                out.addAll(composite.getServesSteps());
            }
            for (CompletionCondition sub : composite.getConditions()) {
                collectFrontierServesEdges(sub, out);
            }
            return;
        }
        List<StepId> serves = condition.getServesSteps();
        if (serves != null) {
            out.addAll(serves);
        }
    }

    /** True if any {@code servesSteps} list anywhere in the tree is non-empty, mode-blind. */
    private static boolean carriesAnyServesEdge(CompletionCondition condition) {
        if (condition == null) return false;
        List<StepId> serves = condition.getServesSteps();
        if (serves != null && !serves.isEmpty()) {
            return true;
        }
        if (condition instanceof CompletionCondition.Composite) {
            for (CompletionCondition sub : ((CompletionCondition.Composite) condition).getConditions()) {
                if (carriesAnyServesEdge(sub)) return true;
            }
        }
        return false;
    }
}

package com.stepwise.engine;

import com.stepwise.model.EquipmentSlot;
import com.stepwise.model.ItemStack;
import com.stepwise.model.PlayerState;
import com.stepwise.model.QuestStatus;
import com.stepwise.model.Skill;
import com.stepwise.model.SkillState;
import lombok.Value;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** The {@link PlayerState} updates that take more than a setter call. */
public final class EventApplier {

    private EventApplier() {
    }

    @Value
    public static class SkillSnapshot {
        int level;
        long xp;
    }

    public static void applyStatChanged(PlayerState state, String skillName, long xp, int level) {
        putSkill(state, skillName, level, xp);
        state.recalculateTotalLevel();
        state.recalculateCombatLevel();
    }

    /** Records one skill reading. A name {@link Skill} does not know is ignored. */
    private static void putSkill(PlayerState state, String skillName, int level, long xp) {
        try {
            state.getSkills().put(Skill.fromString(skillName), new SkillState(level, xp));
        } catch (IllegalArgumentException e) {
            // Not a skill the guide tracks.
        }
    }

    public static void applyLoginState(
            PlayerState state,
            Map<String, SkillSnapshot> skills,
            Integer questPoints,
            List<String> completedQuests,
            List<String> startedQuests,
            List<ItemStack> inventory,
            Map<EquipmentSlot, ItemStack> equipment) {

        if (skills != null) {
            for (Map.Entry<String, SkillSnapshot> entry : skills.entrySet()) {
                putSkill(state, entry.getKey(), entry.getValue().getLevel(), entry.getValue().getXp());
            }
            state.recalculateTotalLevel();
            state.recalculateCombatLevel();
        }

        if (questPoints != null) {
            state.setQuestPoints(questPoints);
        }

        if (completedQuests != null) {
            for (String quest : completedQuests) {
                state.getQuests().put(quest, QuestStatus.COMPLETED);
            }
        }

        if (startedQuests != null) {
            for (String quest : startedQuests) {
                state.getQuests().put(quest, QuestStatus.IN_PROGRESS);
            }
        }

        if (inventory != null) {
            state.setInventory(inventory);
        }

        if (equipment != null) {
            replaceEquipment(state, equipment);
        }
    }

    static void replaceEquipment(PlayerState state, Map<EquipmentSlot, ItemStack> equipment) {
        state.getEquipment().clear();
        state.getEquipment().putAll(equipment);
    }

    /**
     * Replace the tracked seed box contents and stamp them as verified.
     *
     * <p>Fed by the chat listing from checking the box: an empty box reads as an empty list,
     * a full one as the seeds it names. The listing is a whole-box statement, so it replaces
     * the tally rather than adjusting it. This is the only way an over-count comes down.
     */
    public static void applySeedBoxChanged(PlayerState state, List<ItemStack> items) {
        state.setSeedBox(items);
        // The only place verifiedAt is stamped: every other seed-box path adjusts a tally.
        state.setSeedBoxVerifiedAt(Instant.now());
    }

    /**
     * Adds seeds the player has just put in the box.
     *
     * <p>A running tally, unlike every other container here, because the game does not send
     * the seed box's contents as an item container. Seeds boxed before the plugin watched are
     * invisible and a missed movement stays missed until a Check listing replaces the tally,
     * so the tally drifts both ways.
     *
     * <p>{@link #applySeedBoxTaken} clamps at zero, which clears an under-count, but an
     * over-count survives every empty. Only {@link #applySeedBoxChanged} overwrites the whole
     * box.
     */
    public static void applySeedBoxStored(PlayerState state, ItemStack stored) {
        List<ItemStack> box = new ArrayList<>(state.getSeedBox());
        for (int i = 0; i < box.size(); i++) {
            ItemStack held = box.get(i);
            if (held.getItemId() == stored.getItemId()) {
                box.set(i, new ItemStack(held.getItemId(),
                        held.getQuantity() + stored.getQuantity(), held.getName()));
                commitSeedBox(state, box);
                return;
            }
        }
        box.add(stored);
        commitSeedBox(state, box);
    }

    /**
     * Removes seeds that have left the box, whether emptied into the bag or planted.
     *
     * <p>Matched by name, only against what the box holds. The chat line ("Emptied 1 x
     * Asgarnian seed to your inventory") does not name its container, so a name the box does
     * not hold is ignored rather than reported: the line came from another container.
     *
     * @param itemName as the game said it, which for a seed planted straight from the box is
     *                 lower-case, singular or plural — see {@link #namesTheSameItem}
     * @param quantity how many left, as a positive number
     */
    public static void applySeedBoxTaken(PlayerState state, String itemName, int quantity) {
        List<ItemStack> box = new ArrayList<>(state.getSeedBox());
        for (int i = 0; i < box.size(); i++) {
            ItemStack held = box.get(i);
            if (!namesTheSameItem(held.getName(), itemName)) {
                continue;
            }
            int left = held.getQuantity() - quantity;
            if (left > 0) {
                box.set(i, new ItemStack(held.getItemId(), left, held.getName()));
            } else {
                // Clamp at empty: seeds boxed before the plugin watched can make more leave
                // than the tally knew went in.
                box.remove(i);
            }
            commitSeedBox(state, box);
            return;
        }
    }

    /**
     * Case-insensitive name match with an optional trailing "s": the box says "Potato cactus
     * seed" when filled and "3 potato cactus seeds were taken" when planted from.
     */
    private static boolean namesTheSameItem(String held, String spoken) {
        if (held == null || spoken == null) {
            return false;
        }
        if (held.equalsIgnoreCase(spoken)) {
            return true;
        }
        return spoken.length() > 1
                && (spoken.endsWith("s") || spoken.endsWith("S"))
                && held.equalsIgnoreCase(spoken.substring(0, spoken.length() - 1));
    }

    private static void commitSeedBox(PlayerState state, List<ItemStack> box) {
        state.setSeedBox(box);
        // Lets seeds the player has just boxed count as carried rather than as a withdrawal.
        // See PlayerState.seedBoxWatchedAt for why this is separate from verifiedAt.
        state.setSeedBoxWatchedAt(Instant.now());
    }

    /**
     * Merges deposit-box deposits into the existing bank state. A deposit box does not show
     * the bank, so the items that left the inventory are added to the last known bank. The
     * next real bank open corrects it.
     */
    public static void applyDepositInference(PlayerState state, List<ItemStack> depositedItems) {
        List<ItemStack> bank = new ArrayList<>(state.getBank());

        for (ItemStack deposited : depositedItems) {
            boolean merged = false;
            for (int i = 0; i < bank.size(); i++) {
                if (deposited.getName().equalsIgnoreCase(bank.get(i).getName())) {
                    ItemStack existing = bank.get(i);
                    bank.set(i, new ItemStack(
                            existing.getItemId(),
                            existing.getQuantity() + deposited.getQuantity(),
                            existing.getName()));
                    merged = true;
                    break;
                }
            }
            if (!merged) {
                bank.add(deposited);
            }
        }

        state.setBank(bank);
    }

    public static void applyDiaryCompleted(PlayerState state, String area, String difficulty) {
        state.getAchievementDiaries().computeIfAbsent(area, k -> new HashMap<>()).put(difficulty, true);
    }

    /**
     * @param questState as RuneLite's {@code QuestState} names it: {@code IN_PROGRESS} and
     *                   {@code FINISHED} move the quest's status, anything else leaves it
     */
    public static void applyQuestProgress(
            PlayerState state,
            String questName,
            String questState,
            Integer newValue) {

        if ("IN_PROGRESS".equals(questState)) {
            QuestStatus current = state.getQuests().get(questName);
            if (current == null || current == QuestStatus.NOT_STARTED) {
                state.getQuests().put(questName, QuestStatus.IN_PROGRESS);
            }
        } else if ("FINISHED".equals(questState)) {
            state.getQuests().put(questName, QuestStatus.COMPLETED);
        }

        if (newValue != null) {
            state.getQuestProgress().put(questName, newValue);
        }
    }
}

package com.stepwise.engine;

import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import lombok.Value;
import net.runelite.api.ChatMessageType;

/**
 * Stateless parser for OSRS chat messages. Extracts typed event data from
 * game messages (kill count, collection log, diary, seed box).
 *
 * <p>All methods are static and side-effect-free — they parse regex matches
 * into result objects, leaving dispatch to the caller.</p>
 */
public final class EventParser
{
	private static final Pattern KC_PATTERN =
		Pattern.compile("Your (.+) kill count is: (\\d{1,3}(?:,\\d{3})+|\\d+)");
	private static final Pattern KC_RAID_PATTERN =
		Pattern.compile("Your completed (.+) count is: (\\d{1,3}(?:,\\d{3})+|\\d+)");

	private static final Pattern COLLECTION_LOG_PATTERN =
		Pattern.compile("New item added to your collection log: (.+)");

	/**
	 * The message box shown when a diary tier's last task is done: "Congratulations! You have
	 * completed all of the hard tasks in the Karamja area. Speak to Pirate Jackie the Fruit to
	 * claim your reward."
	 */
	private static final Pattern DIARY_PATTERN =
		Pattern.compile(
			"Congratulations! You have completed all of the (easy|medium|hard|elite) tasks in the (.+?) area\\b",
			Pattern.CASE_INSENSITIVE);

	/**
	 * The seed box announcing that its contents moved, in each of the four wordings it uses.
	 *
	 * <p>The chat text is the only source for these counts: the game never sends the
	 * {@code SEED_BOX} item container, so {@code Client#getItemContainer} always answers null.
	 *
	 * <p>Filling and emptying give an exact item name and a count. Planting straight from the
	 * box gives a lower-case name, singular or plural depending on how many the patch takes.
	 * The emptying line never names the box ("Emptied 1 x Asgarnian seed to your inventory"),
	 * so a match on the box's name would miss it.
	 *
	 * <p>Digits are bounded to nine so a malformed line cannot overflow the parse.
	 */
	private static final Pattern SEED_BOX_STORED =
		Pattern.compile("^Stored (\\d{1,9}) x (.+?) in your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_EMPTIED =
		Pattern.compile("^Emptied (\\d{1,9}) x (.+?) to your inventory\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_TAKEN_ONE =
		Pattern.compile("^An? (.+?) was taken from your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);
	private static final Pattern SEED_BOX_TAKEN_MANY =
		Pattern.compile("^(\\d{1,9}) (.+?) were taken from your seed box\\.?$",
			Pattern.CASE_INSENSITIVE);

	/**
	 * The box answering Check with nothing in it.
	 *
	 * <p>The four patterns above are movements, and a sum of movements cannot correct an
	 * over-count. This line is the box describing itself, so it replaces the tally rather
	 * than adjusting it.
	 *
	 * <p>Checking a box prints its contents to chat in one of two shapes. This is one;
	 * {@link #SEED_BOX_CONTENTS_HEADER} is the other.
	 *
	 * <p>The pattern accepts both "the" and "your", and nothing else in the game says
	 * "seed box is empty".
	 */
	private static final Pattern SEED_BOX_EMPTY =
		Pattern.compile("^(?:the|your) seed box is empty\\.?$", Pattern.CASE_INSENSITIVE);

	/**
	 * The box answering Check with something in it: a header, then one line per seed.
	 *
	 * <pre>
	 * The seed box contains:
	 * 1 x Harralander seed.
	 * 2 x Guam seed.
	 * 1 x Potato cactus seed.
	 * </pre>
	 *
	 * <p>Each line arrives as its own message, so reading the listing needs state across
	 * messages. {@code SeedBoxListing} holds that state.
	 */
	private static final Pattern SEED_BOX_CONTENTS_HEADER =
		Pattern.compile("^(?:the|your) seed box contains:?$", Pattern.CASE_INSENSITIVE);

	/**
	 * One line of a listing: a count, the separator, and the seed's name.
	 *
	 * <p>Only valid in the lines following a header. The game prints "1 x Harralander seed."
	 * in many places unrelated to a seed box. See {@link #parseSeedBoxContentsEntry}.
	 */
	private static final Pattern SEED_BOX_CONTENTS_ENTRY =
		Pattern.compile("^(\\d{1,9}) x (.+?)\\.?$", Pattern.CASE_INSENSITIVE);

	private EventParser()
	{
	}

	// ------------------------------------------------------------------
	// Result types
	// ------------------------------------------------------------------

	@Value
	public static class KillCountEvent
	{
		String target;
		int count;
	}

	@Value
	public static class CollectionLogEvent
	{
		String itemName;
	}

	@Value
	public static class DiaryEvent
	{
		String area;
		String tier;
	}

	/**
	 * Seeds moving into or out of a seed box: what moved, and how many, signed by direction.
	 *
	 * <p>The name is the game's text, unresolved. Planting from the box reports a lower-case
	 * name that may be plural. The caller resolves it against the candidates it holds, which
	 * for a seed leaving the box are the box's own contents.
	 */
	@Value
	public static class SeedBoxMove
	{
		/** The item as the game named it, which may be lower-case or plural. */
		String itemName;

		/** How many moved: positive into the box, negative out of it. Never zero. */
		int quantity;
	}

	// ------------------------------------------------------------------
	// Parse methods
	// ------------------------------------------------------------------

	/**
	 * Parses kill count messages (boss KC and raid completion count).
	 */
	public static Optional<KillCountEvent> parseKillCount(String message)
	{
		for (Pattern pattern : List.of(KC_PATTERN, KC_RAID_PATTERN))
		{
			Matcher matcher = pattern.matcher(message);
			if (matcher.find())
			{
				return Optional.of(new KillCountEvent(matcher.group(1),
					Integer.parseInt(matcher.group(2).replace(",", ""))));
			}
		}
		return Optional.empty();
	}

	/**
	 * Parses collection log addition messages.
	 */
	public static Optional<CollectionLogEvent> parseCollectionLog(String message)
	{
		Matcher matcher = COLLECTION_LOG_PATTERN.matcher(message);
		if (matcher.find())
		{
			return Optional.of(new CollectionLogEvent(matcher.group(1).trim()));
		}
		return Optional.empty();
	}

	/**
	 * Parses the message box that announces a finished diary tier, which reaches chat as a
	 * {@code MESBOX} line. The tier is normalized to title case (e.g. "Easy", "Medium"), and
	 * the area is the game's own name for it ("Karamja").
	 */
	public static Optional<DiaryEvent> parseDiary(String message)
	{
		Matcher matcher = DIARY_PATTERN.matcher(message);
		if (matcher.find())
		{
			String difficulty = matcher.group(1);
			String area = matcher.group(2).trim();

			difficulty = difficulty.substring(0, 1).toUpperCase(Locale.ROOT)
				+ difficulty.substring(1).toLowerCase(Locale.ROOT);

			return Optional.of(new DiaryEvent(area, difficulty));
		}
		return Optional.empty();
	}

	/**
	 * Whether the game's own announcements arrive under this chat type.
	 *
	 * <p>{@code SPAM} is easy to leave out. Jagex files repetitive item handling under it
	 * ("You catch some raw shrimps."), and every seed box line is {@code SPAM}, so a listener on
	 * {@code GAMEMESSAGE} alone never hears about the box.
	 *
	 * <p>The client raises these events even when the player filters game chat.
	 */
	public static boolean isReadableGameChat(ChatMessageType type)
	{
		return type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM;
	}

	/**
	 * Seeds moving into or out of a seed box, or empty when the line is about something else.
	 *
	 * <p>Anchored at both ends, so a line that merely mentions a seed box is not mistaken for
	 * an amount. This feeds a running tally that only a Check listing of the box corrects.
	 *
	 * <p>"Emptied ... to your inventory" does not name the box, so another container's
	 * identically-worded line also matches. The caller narrows it by applying a take only
	 * against seeds the box is known to hold.
	 */
	public static Optional<SeedBoxMove> parseSeedBoxMove(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}

		Matcher stored = SEED_BOX_STORED.matcher(message);
		if (stored.matches())
		{
			return moveOf(stored.group(2), Integer.parseInt(stored.group(1)));
		}

		Matcher emptied = SEED_BOX_EMPTIED.matcher(message);
		if (emptied.matches())
		{
			return moveOf(emptied.group(2), -Integer.parseInt(emptied.group(1)));
		}

		Matcher takenOne = SEED_BOX_TAKEN_ONE.matcher(message);
		if (takenOne.matches())
		{
			return moveOf(takenOne.group(1), -1);
		}

		Matcher takenMany = SEED_BOX_TAKEN_MANY.matcher(message);
		if (takenMany.matches())
		{
			return moveOf(takenMany.group(2), -Integer.parseInt(takenMany.group(1)));
		}

		return Optional.empty();
	}

	/**
	 * True when the box has just told us it holds nothing.
	 *
	 * <p>Not a move: the caller replaces the tally with zero rather than subtracting, which
	 * corrects an over-count.
	 */
	public static boolean isSeedBoxReportedEmpty(String message)
	{
		return message != null && SEED_BOX_EMPTY.matcher(message).matches();
	}

	/** True when the box has begun listing what it holds; its seeds are the lines after. */
	public static boolean isSeedBoxContentsHeader(String message)
	{
		return message != null && SEED_BOX_CONTENTS_HEADER.matcher(message).matches();
	}

	/**
	 * One seed of a listing, read as a positive amount.
	 *
	 * <p><b>Only meaningful directly after {@link #isSeedBoxContentsHeader}</b> or another
	 * entry. On its own this matches any "2 x Thing." the game prints. The result reuses
	 * {@link SeedBoxMove}, but its quantity is an amount held, not an amount moved.
	 */
	public static Optional<SeedBoxMove> parseSeedBoxContentsEntry(String message)
	{
		if (message == null)
		{
			return Optional.empty();
		}
		Matcher entry = SEED_BOX_CONTENTS_ENTRY.matcher(message);
		return entry.matches()
			? moveOf(entry.group(2), Integer.parseInt(entry.group(1)))
			: Optional.empty();
	}

	/** Empty for a zero quantity, which is not a change. */
	private static Optional<SeedBoxMove> moveOf(String itemName, int quantity)
	{
		return quantity == 0 ? Optional.empty()
			: Optional.of(new SeedBoxMove(itemName, quantity));
	}

}

package com.stepwise.engine;

import com.stepwise.model.ItemStack;
import com.stepwise.model.PlayerState;

import java.util.Collection;
import java.util.Set;

/** Where a carried container such as the seed box or plank sack sits among the player's items. */
final class HeldItems {

    private HeldItems() {
    }

    /** True when one of these items is in the inventory or worn. */
    static boolean carried(PlayerState state, Set<Integer> itemIds) {
        return state != null
                && (holds(state.getInventory(), itemIds)
                        || state.getEquipment() != null
                                && holds(state.getEquipment().values(), itemIds));
    }

    /** True when one of these items is sitting in the bank. */
    static boolean banked(PlayerState state, Set<Integer> itemIds) {
        return state != null && holds(state.getBank(), itemIds);
    }

    private static boolean holds(Collection<ItemStack> items, Set<Integer> itemIds) {
        if (items == null) {
            return false;
        }
        for (ItemStack item : items) {
            if (item != null && itemIds.contains(item.getItemId())) {
                return true;
            }
        }
        return false;
    }
}

package com.stepwise.engine;

import com.google.gson.Gson;
import com.stepwise.guide.GuideLoader;
import lombok.extern.slf4j.Slf4j;

import java.io.Reader;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Resolves item class names to sets of valid item IDs for hasItem matching.
 *
 * <p>Loaded from {@code /com/stepwise/item_classes.json} in plugin resources. Supports:
 * <ul>
 *   <li><b>Tool classes</b> — any member satisfies (optionally filtered by minTier)</li>
 *   <li><b>Charged items</b> — any variant the class lists satisfies; each class decides
 *       whether its uncharged shell counts</li>
 *   <li><b>Upgrade paths</b> — a base item plus all its upgraded variants satisfy the base check</li>
 * </ul>
 *
 * <p>Resolved ID sets are cached, so repeated evaluations do not allocate. An unknown class
 * resolves to an empty set, and the caller falls back to exact ID matching.
 */
@Slf4j
public final class ItemClassResolver {
    private static final String RESOURCE_PATH = "/com/stepwise/item_classes.json";

    private final Map<String, ToolClass> toolClasses;
    /** Pre-computed valid ID sets for charged items (tier-independent). */
    private final Map<String, Set<Integer>> chargedIdSets = new HashMap<>();
    /** Maps every member ID to the full set of equivalent IDs that satisfy a check for it,
     *  so a lookup works whichever variant the guide data references:
     *  <ul>
     *    <li>upgrade chains: Black mask, Slayer helmet, Slayer helmet (i) share one set</li>
     *    <li>charge variants: a condition on Digsite pendant (1) also matches a full-charge
     *        pendant. An uncharged shell joins only when its class lists it.</li>
     *  </ul> */
    private final Map<Integer, Set<Integer>> idEquivalences = new HashMap<>();
    /** Cached valid ID sets for tool classes, keyed by "className:minTier".
     *  Concurrent because both the client thread and the EDT read it. */
    private final Map<String, Set<Integer>> toolIdCache = new ConcurrentHashMap<>();

    private ItemClassResolver(ItemClassesFile parsed) {
        // Gson leaves a section null when the file writes it as null, and returns null for an
        // empty file; either reads as nothing to resolve.
        ItemClassesFile file = parsed != null ? parsed : new ItemClassesFile();
        this.toolClasses = file.tool_classes != null ? file.tool_classes : Collections.emptyMap();
        Map<String, ChargedItem> chargedItems =
                file.charged_items != null ? file.charged_items : Collections.emptyMap();
        Map<String, UpgradePath> upgradePaths =
                file.upgrade_paths != null ? file.upgrade_paths : Collections.emptyMap();
        for (Map.Entry<String, ChargedItem> entry : chargedItems.entrySet()) {
            chargedIdSets.put(entry.getKey(), Set.copyOf(entry.getValue().getAllValidIds()));
        }

        // The guide names one id while the player may hold another: a condition on "Slayer
        // helmet" (11864) must accept an imbued one such as 25177, and a crafted Digsite
        // pendant (5) must latch a condition catalogued under the (1)-charge id.
        // Each charged class decides in valid_ids whether its uncharged shell counts: a glory
        // lists only charged ids, while any Pharaoh's sceptre satisfies "obtain a sceptre".
        for (UpgradePath path : upgradePaths.values()) {
            Set<Integer> allIds = new HashSet<>();
            allIds.add(path.base.id);
            for (UpgradeMember upgrade : path.upgrades) {
                allIds.add(upgrade.id);
            }
            index(Set.copyOf(allIds));
        }
        chargedIdSets.values().forEach(this::index);

        log.debug("Loaded item classes: {} tool classes, {} charged items, {} upgrade paths",
                toolClasses.size(), chargedIdSets.size(), upgradePaths.size());
    }

    private void index(Set<Integer> equivalentIds) {
        for (int id : equivalentIds) {
            idEquivalences.put(id, equivalentIds);
        }
    }

    /**
     * Load item class data from the plugin JAR resource.
     * Returns an empty resolver if the resource is missing or malformed.
     */
    public static ItemClassResolver loadFromResource(Gson gson) {
        return GuideLoader.readResource(RESOURCE_PATH, reader -> parse(reader, gson),
                () -> new ItemClassResolver(new ItemClassesFile()));
    }

    /** Builds a resolver from item class JSON; a null or empty section resolves nothing. */
    static ItemClassResolver parse(Reader reader, Gson gson) {
        return new ItemClassResolver(gson.fromJson(reader, ItemClassesFile.class));
    }

    /**
     * Resolve a class name to the set of valid item IDs that satisfy it.
     *
     * <p>For tool classes, returns all member IDs at or above the given minTier.
     * For charged items, returns every id the class lists, which leaves out the uncharged
     * shell unless the class counts it.
     *
     * <p>Repeated calls with the same arguments return the same cached set instance.
     *
     * @param className the item class name (e.g. "hammer", "ring_of_dueling")
     * @param minTier   minimum tier for tiered classes, or null for any tier
     * @return set of valid item IDs, empty if class not recognized
     */
    public Set<Integer> resolveValidIds(String className, Integer minTier) {
        Set<Integer> chargedIds = chargedIdSets.get(className);
        if (chargedIds != null) {
            return chargedIds;
        }

        ToolClass tool = toolClasses.get(className);
        if (tool == null) {
            return Collections.emptySet();
        }

        String cacheKey = minTier != null ? className + ":" + minTier : className;
        return toolIdCache.computeIfAbsent(cacheKey, key -> {
            Set<Integer> ids = new HashSet<>();
            for (ToolMember member : tool.members) {
                if (minTier == null || member.tier == null || member.tier >= minTier) {
                    ids.add(member.id);
                }
            }
            return Collections.unmodifiableSet(ids);
        });
    }

    /**
     * Get all item IDs equivalent to the given item: every member of its upgrade chain or
     * its charge-variant set. Lookups work from any member, not just the base item.
     *
     * @param itemId any item ID that may belong to an upgrade chain or charge-variant set
     * @return set containing all equivalent IDs, or null if the item has no equivalence set
     */
    public Set<Integer> resolveEquivalentIds(int itemId) {
        return idEquivalences.get(itemId);
    }

    // --- JSON data classes ---

    /** The resource's top level; Gson binds the snake_case keys by field name. */
    private static class ItemClassesFile {
        Map<String, ToolClass> tool_classes = Collections.emptyMap();
        Map<String, ChargedItem> charged_items = Collections.emptyMap();
        Map<String, UpgradePath> upgrade_paths = Collections.emptyMap();
    }

    private static class ToolClass {
        List<ToolMember> members = Collections.emptyList();
    }

    private static class ToolMember {
        int id;
        Integer tier;
    }

    private static class ChargedItem {
        List<Integer> valid_ids = Collections.emptyList();
        // Trimmed/imbued variants also included in valid_ids resolution
        List<Integer> trimmed_valid_ids;
        List<Integer> imbued_valid_ids;

        /** Get all valid IDs including cosmetic/imbued variants. */
        List<Integer> getAllValidIds() {
            List<Integer> all = new ArrayList<>(valid_ids);
            if (trimmed_valid_ids != null) {
                all.addAll(trimmed_valid_ids);
            }
            if (imbued_valid_ids != null) {
                all.addAll(imbued_valid_ids);
            }
            return all;
        }
    }

    private static class UpgradePath {
        UpgradeMember base;
        List<UpgradeMember> upgrades = Collections.emptyList();
    }

    private static class UpgradeMember {
        int id;
    }
}

package com.stepwise.engine;

import com.stepwise.model.PlayerState;
import com.stepwise.model.QuestStatus;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.stream.IntStream;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;

/**
 * The Kingdom of Miscellania's approval, coffer and uncollected resources, projected to today.
 *
 * <p>The client receives all three at login, wherever the player stands, but they describe the
 * kingdom as of its last server update. That update can run at login or only on a visit, so an
 * observation is dated by the day its values last <em>changed</em>, as RuneLite's own Kingdom
 * plugin does: a login-time update changes them and dates them today, and a lazy one leaves
 * them alone, so the old date still fits.
 *
 * <p>From that date the kingdom is replayed one UTC day at a time. Each day withdraws 10% of the
 * coffer up to a cap, turns the coins withdrawn and the approval into resource points, and decays
 * approval. After 30 days without a visit the kingdom stops until the player returns.
 */
public class KingdomTracker {

    /** Key this quest's completion is stored under in {@link PlayerState#getQuests()}. */
    public static final String QUEST_NAME = "Throne of Miscellania";

    /** Raises the worker count, the withdrawal cap, and slows approval decay. */
    public static final String ROYAL_TROUBLE = "Royal Trouble";

    public static final int APPROVAL_VARBIT = VarbitID.MISC_APPROVAL;
    public static final int COFFER_VARBIT = VarbitID.MISC_COFFERS;

    /** The uncollected resource points. Named for the bits it occupies, but it is the whole value. */
    public static final int POOL_VARBIT = VarbitID.MISC_RESTOTAL_LOWBITS;

    /** The hardwood choice on the management screen; see {@link Hardwood}. */
    public static final int HARDWOOD_TYPE_VARBIT = VarbitID.MISC_RAREWOOD_TYPE;

    /** The Herbs labour's choice: 0 herbs, 1 flax. */
    public static final int HERBS_OR_FLAX_VARBIT = VarbitID.MISC_HERBS_OR_FLAX;

    /**
     * A form of labour on the management screen, with the varbit counting its workers, 0–10.
     * Each varbit draws its own category's pips on that screen (RuneLite's {@code VarbitID}
     * names them {@code MISC_POINTS_*}).
     */
    @Getter
    @AllArgsConstructor
    public enum Labour {
        MINING(VarbitID.MISC_POINTS_MINE),
        WOOD(VarbitID.MISC_POINTS_WOOD),
        HERBS(VarbitID.MISC_POINTS_HERB),
        FISHING(VarbitID.MISC_POINTS_FISH),
        HARDWOOD(VarbitID.MISC_POINTS_RAREWOOD),
        FARM(VarbitID.MISC_POINTS_FARM);

        private final int varbit;
    }

    /** Every varbit the tracker reads. */
    public static final int[] VARBIT_IDS = IntStream.concat(
            IntStream.of(APPROVAL_VARBIT, COFFER_VARBIT, POOL_VARBIT, HARDWOOD_TYPE_VARBIT,
                    HERBS_OR_FLAX_VARBIT),
            Arrays.stream(Labour.values()).mapToInt(Labour::getVarbit)).toArray();

    /** The guide's hardwood crew: the most one category takes. */
    static final int HARDWOOD_CREW = 10;

    /**
     * Points one day earns at a full coffer and 100% approval after Royal Trouble: the day the
     * wiki's yield table describes. Items per point are the same before Royal Trouble (595 maple
     * from 762 points, 892 from 1,143), so the table converts any pool.
     */
    private static final int TABLE_DAY_POINTS = 1_143;

    /**
     * The hardwood choice, in varbit order. The management screen's three radio buttons are
     * {@code choosemahogany}, {@code chooseteak} and {@code chooseboth}, lit at 0, 1 and 2.
     */
    @Getter
    @AllArgsConstructor
    public enum Hardwood {
        MAHOGANY("mahogany"),
        TEAK("teak"),
        BOTH("both");

        private final String label;

        /** The choice as advice names it: "both" alone does not say which woods. */
        String woods() {
            return this == BOTH ? "teak and mahogany" : label;
        }

        /** The choice a varbit value stands for, or null for a value the screen has no button for. */
        static Hardwood fromVarbit(int value) {
            Hardwood[] all = values();
            return value >= 0 && value < all.length ? all[value] : null;
        }

        /** The choice a guide parameter names, or null for anything else. */
        public static Hardwood named(String label) {
            for (Hardwood h : values()) {
                if (h.label.equalsIgnoreCase(label)) {
                    return h;
                }
            }
            return null;
        }
    }

    /** What the workers are set to. Immutable, so a reader never sees half of it. */
    private static final class Allocation {

        /** Workers per {@link Labour}, by ordinal. */
        private final int[] workers;
        private final Hardwood hardwood;
        private final boolean flax;

        private Allocation(int[] workers, Hardwood hardwood, boolean flax) {
            this.workers = workers;
            this.hardwood = hardwood;
            this.flax = flax;
        }

        int on(Labour labour) {
            return workers[labour.ordinal()];
        }
    }

    /** One item a collection would hand over, estimated. */
    @Value
    public static class Yield {
        String item;
        int quantity;
    }

    private static final int MISCELLANIA_REGION = 10044;
    private static final int ETCETERIA_REGION = 10300;

    static final int MAX_APPROVAL = 127;

    /** Approval never decays below 25%. */
    static final int APPROVAL_FLOOR = 32;

    /** The most resource points one collection holds: the varbit's 18 bits. */
    static final int POOL_CAP = 262_143;

    /** Days without a visit after which the kingdom stops withdrawing and producing. */
    static final int PAUSE_DAYS = 30;

    /**
     * At or below this the trip is due. A week of decay after Royal Trouble lands here, which is
     * the guide's "visit at least once a week".
     */
    public static final int DUE_APPROVAL_PERCENT = 93;

    private static final int WITHDRAWAL_CAP = 50_000;
    private static final int WITHDRAWAL_CAP_ROYAL_TROUBLE = 75_000;

    /**
     * Daily decay in thousandths of an approval point: 2.5% of 127 before Royal Trouble, 1% after.
     * Thousandths keep the replay in integers, so a week of decay lands on the same percent every
     * run.
     */
    private static final int DECAY_MILLI = 3175;
    private static final int DECAY_MILLI_ROYAL_TROUBLE = 1270;

    private static final long DAY_SECONDS = 86400L;

    private static final long NO_VISIT = -1L;

    /** The last observation, or null before the first. One object, so readers never see halves. */
    private volatile State state;

    /**
     * The worker allocation this session, or null until read. Not persisted: the client sends it
     * at every login, and advice about a setting nobody has read this session could be stale.
     */
    private volatile Allocation allocation;

    private static final class State {

        private final int approval;
        private final int coffer;
        private final int pool;

        /** UTC epoch day the three values last changed. */
        private final long observedDay;

        /**
         * UTC epoch day of the first observation. Unlike {@link #observedDay} it never moves, so
         * it can stand in for a visit not yet seen without sliding the pause later.
         */
        private final long firstObservedDay;

        /** UTC epoch day the player last stood in the kingdom, or {@link #NO_VISIT}. */
        private final long lastVisitDay;

        /**
         * Whether the player has held approval at 100%. Until then the guide is not yet asking
         * for upkeep, so falling approval is not a reason to go.
         */
        private final boolean maintained;

        private State(int approval, int coffer, int pool, long observedDay, long firstObservedDay,
                      long lastVisitDay, boolean maintained) {
            this.approval = approval;
            this.coffer = coffer;
            this.pool = pool;
            this.observedDay = observedDay;
            this.firstObservedDay = firstObservedDay;
            this.lastVisitDay = lastVisitDay;
            this.maintained = maintained;
        }
    }

    /** The kingdom as projected to one day. */
    @Value
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    public static class Reading {

        int approvalPercent;

        int coffer;

        /** Uncollected resource points. */
        int pool;

        /** Whole UTC days since the player last stood in the kingdom, or -1 if never seen. */
        int daysSinceVisit;

        /** Whether 30 days have passed without a visit, so the kingdom has stopped. */
        boolean paused;

        /** Whether the coffer is under ten days' cap, below which the daily yield shrinks. */
        boolean cofferLow;

        /** Whole days until the trip is due; zero when it is due now. */
        int daysUntilDue;

        public boolean isDue() {
            return daysUntilDue == 0;
        }
    }

    /** Whether the player has finished the quest, and so has a kingdom at all. */
    public static boolean questCompleted(PlayerState state) {
        return state != null && state.getQuests().get(QUEST_NAME) == QuestStatus.COMPLETED;
    }

    public static boolean royalTroubleCompleted(PlayerState state) {
        return state != null && state.getQuests().get(ROYAL_TROUBLE) == QuestStatus.COMPLETED;
    }

    /** Whether a region is Miscellania or Etceteria, where standing counts as a visit. */
    public static boolean isKingdomRegion(int regionId) {
        return regionId == MISCELLANIA_REGION || regionId == ETCETERIA_REGION;
    }

    /**
     * Fold in the three values as the client reports them now.
     *
     * <p>An approval of 0 is ignored: after the quest, approval never falls below 25%, so 0 means
     * the varbits have not loaded yet.
     *
     * @return true if anything moved, so the caller should persist it
     */
    public boolean observe(int approval, int coffer, int pool, long nowEpochSec) {
        if (approval <= 0) {
            return false;
        }
        State prev = state;
        if (prev != null && prev.approval == approval && prev.coffer == coffer
                && prev.pool == pool) {
            return false;
        }
        long today = utcDay(nowEpochSec);
        state = prev == null
                ? new State(approval, coffer, pool, today, today, NO_VISIT,
                        approval >= MAX_APPROVAL)
                : new State(approval, coffer, pool, today, prev.firstObservedDay,
                        prev.lastVisitDay, prev.maintained || approval >= MAX_APPROVAL);
        return true;
    }

    /**
     * Fold in the worker allocation as the client reports it now.
     *
     * <p>Leaves the allocation unread unless every allocation varbit is present. Reading a gap as
     * 0 would mean "no workers" and draw advice; a state without a scan has none of them.
     *
     * @param varbits the player's varbit values by id
     */
    public void observeAllocation(Map<Integer, Integer> varbits) {
        Integer hardwood = varbits.get(HARDWOOD_TYPE_VARBIT);
        Integer herbsOrFlax = varbits.get(HERBS_OR_FLAX_VARBIT);
        if (hardwood == null || herbsOrFlax == null) {
            return;
        }
        int[] workers = new int[Labour.values().length];
        for (Labour labour : Labour.values()) {
            Integer count = varbits.get(labour.varbit);
            if (count == null) {
                return;
            }
            workers[labour.ordinal()] = count;
        }
        allocation = new Allocation(workers, Hardwood.fromVarbit(hardwood), herbsOrFlax == 1);
    }

    /**
     * What a collection would hand over from this many resource points, under the allocation read
     * this session; empty before it is read. Only each job's main resource is estimated. The
     * extras are left out: herb seeds and the split of herbs by type have no rate on the wiki,
     * and the bird nests and gems that come with logs and coal are a few per hundred.
     *
     * <p>Each item scales the wiki's daily yield at 10 workers by the workers on it and by the pool
     * in days of {@link #TABLE_DAY_POINTS}. The allocation at collection decides the whole pool,
     * so this is what collecting now would give.
     */
    public List<Yield> collectionEstimate(int pool) {
        Allocation a = allocation;
        List<Yield> yields = new ArrayList<>();
        if (a == null || pool <= 0) {
            return yields;
        }
        addYield(yields, "coal", 546, a.on(Labour.MINING), pool);
        addYield(yields, "maple logs", 892, a.on(Labour.WOOD), pool);
        if (a.flax) {
            addYield(yields, "flax", 1250, a.on(Labour.HERBS), pool);
        } else {
            addYield(yields, "grimy herbs", 61, a.on(Labour.HERBS), pool);
        }
        // The kingdom hands fish over raw or cooked as the player chose, in the same amounts.
        addYield(yields, "raw or cooked tuna", 440, a.on(Labour.FISHING), pool);
        addYield(yields, "raw or cooked swordfish", 132, a.on(Labour.FISHING), pool);
        // A hardwood value the screen has no button for names no wood, so it estimates none
        // rather than guessing one.
        int hardwoodWorkers = a.on(Labour.HARDWOOD);
        if (a.hardwood == Hardwood.MAHOGANY) {
            addYield(yields, "mahogany logs", 223, hardwoodWorkers, pool);
        } else if (a.hardwood == Hardwood.TEAK) {
            addYield(yields, "teak logs", 301, hardwoodWorkers, pool);
        } else if (a.hardwood == Hardwood.BOTH) {
            addYield(yields, "teak logs", 121, hardwoodWorkers, pool);
            addYield(yields, "mahogany logs", 121, hardwoodWorkers, pool);
        }
        addYield(yields, "seeds", 481, a.on(Labour.FARM), pool);
        return yields;
    }

    private static void addYield(List<Yield> yields, String item, int dailyAtTenWorkers,
                                 int workers, int pool) {
        long quantity = (long) dailyAtTenWorkers * workers * pool / (10L * TABLE_DAY_POINTS);
        if (quantity > 0) {
            yields.add(new Yield(item, (int) quantity));
        }
    }

    /**
     * What to change so the hardwood workers match the guide, or null when they already do,
     * when the guide names no hardwood, or before the setting has been read.
     *
     * <p>Null before Royal Trouble too: the hardwood category opens with it, so a player who
     * skipped ahead without the quest could not act on the advice.
     *
     * @param wanted       the hardwoods the guide accepts at this stage, first choice first
     * @param royalTrouble whether the player has finished Royal Trouble
     */
    public String hardwoodAdvice(List<String> wanted, boolean royalTrouble) {
        Allocation a = allocation;
        if (a == null || wanted == null || !royalTrouble) {
            return null;
        }
        List<Hardwood> accepted = new ArrayList<>();
        for (String label : wanted) {
            Hardwood h = Hardwood.named(label);
            if (h != null) {
                accepted.add(h);
            }
        }
        if (accepted.isEmpty()) {
            return null;
        }
        // A crew already on an accepted hardwood keeps it: switching to mahogany early is the
        // guide's own advice, and a short crew should not be told to undo it. With nobody on
        // hardwood the choice is only the screen's default, so the first choice stands.
        int workers = a.on(Labour.HARDWOOD);
        boolean onAccepted = workers > 0 && accepted.contains(a.hardwood);
        Hardwood target = onAccepted ? a.hardwood : accepted.get(0);
        if (workers < HARDWOOD_CREW) {
            return "Put " + HARDWOOD_CREW + " workers on " + target.woods();
        }
        return onAccepted ? null : "Switch hardwood to " + target.woods();
    }

    /**
     * Record that the player is standing in the kingdom today. Only the day matters, since the
     * pause counts whole days.
     *
     * <p>Before any observation there is nothing to attach the visit to, so it is dropped. The
     * login scan observes before the first region change, so this costs nothing in practice.
     *
     * @return true if the visit day moved, so the caller should persist it
     */
    public boolean markVisit(long nowEpochSec) {
        State prev = state;
        long today = utcDay(nowEpochSec);
        if (prev == null || prev.lastVisitDay == today) {
            return false;
        }
        state = new State(prev.approval, prev.coffer, prev.pool, prev.observedDay,
                prev.firstObservedDay, today, prev.maintained);
        return true;
    }

    /** Project the kingdom to now, or null before anything has been observed. */
    public Reading readAt(long nowEpochSec, boolean royalTrouble) {
        State s = state;
        if (s == null) {
            return null;
        }
        long today = utcDay(nowEpochSec);
        int cap = royalTrouble ? WITHDRAWAL_CAP_ROYAL_TROUBLE : WITHDRAWAL_CAP;
        int decay = royalTrouble ? DECAY_MILLI_ROYAL_TROUBLE : DECAY_MILLI;

        // Until a visit is seen, the last visit is taken as the first observation, the latest
        // it can be, so the pause shown is the latest it can come.
        long visitDay = s.lastVisitDay != NO_VISIT ? s.lastVisitDay : s.firstObservedDay;
        long lastRunningDay = visitDay + PAUSE_DAYS;

        Replay now = new Replay(s);
        for (long day = s.observedDay + 1; day <= Math.min(today, lastRunningDay); day++) {
            now.advanceDay(cap, decay);
        }

        // The pause is always a reason to go. Falling approval is one only once the player
        // keeps it up, and it can only bring the trip forward.
        int daysUntilDue = (int) Math.max(0, lastRunningDay - today);
        if (s.maintained) {
            Replay ahead = now.copy();
            for (int d = 0; d < daysUntilDue; d++) {
                if (ahead.percent() <= DUE_APPROVAL_PERCENT) {
                    daysUntilDue = d;
                    break;
                }
                ahead.advanceDay(cap, decay);
            }
        }

        int daysSinceVisit = s.lastVisitDay != NO_VISIT ? (int) (today - s.lastVisitDay) : -1;
        return new Reading(now.percent(), (int) now.coffer, (int) now.pool, daysSinceVisit,
                today > lastRunningDay, now.coffer < 10L * cap, daysUntilDue);
    }

    /** The kingdom's three values mid-replay. */
    private static final class Replay {

        private int approvalMilli;
        private long coffer;
        private long pool;

        private Replay(State s) {
            this(s.approval * 1000, s.coffer, s.pool);
        }

        private Replay(int approvalMilli, long coffer, long pool) {
            this.approvalMilli = approvalMilli;
            this.coffer = coffer;
            this.pool = pool;
        }

        Replay copy() {
            return new Replay(approvalMilli, coffer, pool);
        }

        /**
         * One UTC day: withdraw from the coffer, turn the coins and today's approval into
         * resource points, then decay approval.
         */
        void advanceDay(int cap, int decayMilli) {
            long withdrawn = coffer > 10L * cap ? cap : coffer / 10;
            coffer -= withdrawn;
            long points = (withdrawn * 100 / 8333) * (approvalMilli / 1000) / 100;
            pool = Math.min(POOL_CAP, pool + points);
            approvalMilli = Math.max(APPROVAL_FLOOR * 1000, approvalMilli - decayMilli);
        }

        int percent() {
            return KingdomTracker.percent(approvalMilli);
        }
    }

    private static int percent(int approvalMilli) {
        return approvalMilli * 100 / (MAX_APPROVAL * 1000);
    }

    private static long utcDay(long epochSec) {
        return Math.floorDiv(epochSec, DAY_SECONDS);
    }

    /** The observation as one line for the RS profile, or null before the first. */
    public String exportForPersist() {
        State s = state;
        if (s == null) {
            return null;
        }
        return s.approval + ":" + s.coffer + ":" + s.pool + ":" + s.observedDay + ":"
                + s.firstObservedDay + ":" + s.lastVisitDay + ":" + (s.maintained ? 1 : 0);
    }

    /** Forget the observation and the allocation setting. */
    public void clear() {
        state = null;
        allocation = null;
    }

    /** Restore an {@link #exportForPersist()} line. Anything unreadable leaves no observation. */
    public void loadPersisted(String stored) {
        state = parse(stored);
        // A new account's setting arrives with its login scan; the last account's must not
        // stand in until then.
        allocation = null;
    }

    private static State parse(String stored) {
        if (stored == null || stored.isEmpty()) {
            return null;
        }
        String[] parts = stored.split(":");
        if (parts.length != 7) {
            return null;
        }
        try {
            return new State(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]),
                    Integer.parseInt(parts[2]), Long.parseLong(parts[3]),
                    Long.parseLong(parts[4]), Long.parseLong(parts[5]), "1".equals(parts[6]));
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

package com.stepwise.engine;

import com.stepwise.guide.StepwiseGuide;
import com.stepwise.guide.Milestone;
import com.stepwise.guide.MilestonesFile;
import com.stepwise.guide.StepId;
import com.stepwise.model.PlayerState;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Evaluates milestones against current player state to find the guide's auto-latch position.
 *
 * <p>The file lists milestones in guide order, so the last cleared one is the furthest. It wins,
 * and every guide step up to and including its anchor is marked completed. An unmet earlier
 * milestone does not block later ones. Each milestone is independent evidence of position, and a
 * player can skip an optional target (e.g. leave Wintertodt before Firemaking 99) while being
 * sections ahead.
 */
@Slf4j
public final class MilestoneLatcher {

    private MilestoneLatcher() {
    }

    /**
     * Compute the list of step IDs that should be marked completed by milestone auto-latching.
     *
     * @param milestonesFile the loaded milestones file, or {@code null} to skip latching
     * @param guide          the guide
     * @param playerState    current player game state
     * @return ordered list of step IDs from step 1 up to the furthest cleared milestone's
     *         anchor, or an empty list if no milestones are cleared
     */
    public static List<StepId> computeLatchedSteps(
            MilestonesFile milestonesFile,
            StepwiseGuide guide,
            PlayerState playerState) {

        if (milestonesFile == null || playerState == null) {
            return Collections.emptyList();
        }

        Milestone lastCleared = null;
        for (Milestone milestone : milestonesFile.getMilestones()) {
            if (ResolutionEngine.evaluateCondition(milestone.getCriteria(), playerState)) {
                lastCleared = milestone;
                log.debug("Milestone cleared: {} ({})", milestone.getId(), milestone.getLabel());
            } else {
                log.debug("Milestone not cleared: {}", milestone.getId());
            }
        }

        if (lastCleared == null) {
            log.debug("Milestone latch: no milestones cleared, starting from guide beginning");
            return Collections.emptyList();
        }

        StepId anchorId = new StepId(lastCleared.getAnchorStepId());
        List<StepId> latched = new ArrayList<>();
        boolean anchorFound = false;
        for (var step : guide.allSteps()) {
            latched.add(step.getId());
            if (step.getId().equals(anchorId)) {
                anchorFound = true;
                break;
            }
        }

        if (!anchorFound) {
            log.warn("Milestone latch: anchor step '{}' not found in guide, skipping latch",
                    lastCleared.getAnchorStepId());
            return Collections.emptyList();
        }

        log.info("Milestone latch: {} steps fast-forwarded to anchor {} (milestone: {})",
                latched.size(), lastCleared.getAnchorStepId(), lastCleared.getId());
        return latched;
    }
}

package com.stepwise.engine;

import java.util.Arrays;
import java.util.Set;
import java.util.stream.Collectors;

import com.stepwise.model.PlayerState;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * The Mahogany Homes plank sack: what it holds, and where it is.
 *
 * <p>A carried container like the seed box, but read like the rune pouch: the game keeps one
 * count varbit per plank type and transmits it without the sack being opened, so the contents
 * are always current. Planks in the sack appear in neither the inventory nor the bank.
 */
public final class PlankSack {

    private PlankSack() {
    }

    /** The sack itself: a single id, with no open/closed pair and no charged variants. */
    private static final Set<Integer> SACK_ITEM_IDS = Set.of(ItemID.PLANK_SACK);

    /** Per-plank-type count varbits, index-aligned with {@link #PLANK_ITEM_IDS}. */
    private static final int[] COUNT_VARBITS = {
            VarbitID.PLANK_SACK_PLAIN,
            VarbitID.PLANK_SACK_OAK,
            VarbitID.PLANK_SACK_TEAK,
            VarbitID.PLANK_SACK_MAHOGANY,
            VarbitID.PLANK_SACK_CAMPHOR,
            VarbitID.PLANK_SACK_IRONWOOD,
            VarbitID.PLANK_SACK_ROSEWOOD,
    };

    /** Plank item IDs, index-aligned with {@link #COUNT_VARBITS}. */
    private static final int[] PLANK_ITEM_IDS = {
            ItemID.WOODPLANK,
            ItemID.PLANK_OAK,
            ItemID.PLANK_TEAK,
            ItemID.PLANK_MAHOGANY,
            ItemID.PLANK_CAMPHOR,
            ItemID.PLANK_IRONWOOD,
            ItemID.PLANK_ROSEWOOD,
    };

    /**
     * The count varbits, exposed so the plugin can scan them at login. No completion
     * condition names them, so they are absent from {@code requiredVarIds} and would
     * otherwise stay unread until the player next moved a plank in or out.
     */
    public static final Set<Integer> CONTENT_VARBIT_IDS =
            Arrays.stream(COUNT_VARBITS).boxed().collect(Collectors.toUnmodifiableSet());

    /**
     * How many planks of {@code itemId} the sack holds, or 0 for anything it cannot hold.
     *
     * <p>Ignores where the sack is; {@code ResolutionEngine} checks that per location.
     */
    public static int stored(PlayerState state, int itemId) {
        if (state == null || itemId == 0) {
            return 0;
        }
        for (int type = 0; type < PLANK_ITEM_IDS.length; type++) {
            if (PLANK_ITEM_IDS[type] == itemId) {
                Integer count = state.getVarbits().get(COUNT_VARBITS[type]);
                return (count != null && count > 0) ? count : 0;
            }
        }
        return 0;
    }

    /** True when a plank sack is in the inventory or worn. */
    public static boolean carried(PlayerState state) {
        return HeldItems.carried(state, SACK_ITEM_IDS);
    }

    /** True when a plank sack is sitting in the bank. */
    public static boolean banked(PlayerState state) {
        return HeldItems.banked(state, SACK_ITEM_IDS);
    }
}

package com.stepwise.engine;

import java.util.Optional;

/**
 * Tracks the player's current region with debounce logic.
 *
 * <p>A <em>change</em> is only emitted after the player has been in the new region for a
 * stable number of game ticks, so running along a border does not flap.</p>
 *
 * <p>The first region of a session is emitted at once. The login region has no border
 * flicker to settle, and holding it back would leave position readers blind until the
 * player crossed a boundary.</p>
 */
public class RegionTracker
{
	private static final int REGION_STABLE_TICKS = 2;

	private int lastRegionId = -1;
	private int pendingRegionId = -1;
	private int regionStableTicks = 0;

	/**
	 * Updates region tracking with the current region ID.
	 *
	 * @param currentRegionId the player's current region ID
	 * @return the region to announce — the first one this session, or a later one once the
	 *         player has held it long enough to count as a move — otherwise empty
	 */
	public Optional<Integer> update(int currentRegionId)
	{
		if (currentRegionId == lastRegionId)
		{
			pendingRegionId = -1;
			regionStableTicks = 0;
			return Optional.empty();
		}

		if (currentRegionId == pendingRegionId)
		{
			regionStableTicks++;
		}
		else
		{
			pendingRegionId = currentRegionId;
			regionStableTicks = 1;
		}

		// The first region of the session is emitted undebounced (see class doc).
		if (lastRegionId == -1 || regionStableTicks >= REGION_STABLE_TICKS)
		{
			lastRegionId = currentRegionId;
			pendingRegionId = -1;
			regionStableTicks = 0;
			return Optional.of(currentRegionId);
		}
		return Optional.empty();
	}

	/**
	 * Resets all tracking state. Call on login/logout/world hop.
	 */
	public void reset()
	{
		lastRegionId = -1;
		pendingRegionId = -1;
		regionStableTicks = 0;
	}
}

