package com.stepwise.guide;

import com.google.gson.annotations.SerializedName;
import lombok.Builder;
import lombok.Value;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Value
@Builder
public class StepwiseGuide {
    @SerializedName("title") String title;
    @SerializedName("version") String version;
    /**
     * The guide's whole length in minutes of play, by the guide's own timings: the sum of every
     * entry's {@link Entry#getEstimatedDurationMinutes()}.
     */
    @SerializedName("totalMinutes") Double totalMinutes;
    @SerializedName("chapters") List<Chapter> chapters;

    /** All steps in guide order. Populated by {@link GuideLoader#freezeGuide(StepwiseGuide)}. */
    @lombok.Getter(lombok.AccessLevel.NONE)
    transient List<GuideStep> allStepsCached;

    /** Step ID &rarr; chapter/section/entry context. Populated by {@link GuideLoader#freezeGuide(StepwiseGuide)}. */
    @lombok.Getter(lombok.AccessLevel.NONE)
    transient Map<StepId, StepContext> stepContextMapCached;

    /**
     * Step ID string &rarr; position in {@link #allSteps()}. Populated by
     * {@link GuideLoader#freezeGuide(StepwiseGuide)} so a snapshot does not rebuild it.
     */
    @lombok.Getter(lombok.AccessLevel.NONE)
    transient Map<String, Integer> stepPositionIndexCached;

    /** Every step's route assumptions, placed by guide position. Populated by {@link GuideLoader#freezeGuide(StepwiseGuide)}. */
    @lombok.Getter(lombok.AccessLevel.NONE)
    transient List<AssumptionSpan> assumptionSpansCached;

    /** Steps carrying {@link GuideStep#getKingdomHardwood()}, in guide order. Populated by {@link GuideLoader#freezeGuide(StepwiseGuide)}. */
    @lombok.Getter(lombok.AccessLevel.NONE)
    transient List<HardwoodCarrier> hardwoodCarriersCached;

    public List<GuideStep> allSteps() {
        return allStepsCached;
    }

    public Map<StepId, StepContext> stepContextMap() {
        return stepContextMapCached;
    }

    public Map<String, Integer> stepPositionIndex() {
        return stepPositionIndexCached;
    }

    /**
     * Minutes of play the completed steps account for, by the guide's own timings. Each step takes an equal
     * share of its entry's minutes, since the guide times entries, not steps. An untimed or
     * step-less entry counts nothing, and so does a completed id the loaded guide lacks.
     */
    public double minutesDone(Set<StepId> completed) {
        double done = 0;
        if (chapters == null) {
            return done;
        }
        for (Chapter chapter : chapters) {
            if (chapter.getSections() == null) continue;
            for (Section section : chapter.getSections()) {
                if (section.getEntries() == null) continue;
                for (Entry entry : section.getEntries()) {
                    List<GuideStep> steps = entry.getSteps();
                    Double minutes = entry.getEstimatedDurationMinutes();
                    if (steps == null || steps.isEmpty() || minutes == null) continue;
                    double share = minutes / steps.size();
                    for (GuideStep step : steps) {
                        if (completed.contains(step.getId())) {
                            done += share;
                        }
                    }
                }
            }
        }
        return done;
    }

    /** Every step's route assumptions, placed by guide position, in guide order. */
    public List<AssumptionSpan> assumptionSpans() {
        return assumptionSpansCached;
    }

    /** Steps that set the Miscellania hardwood advice, in guide order. */
    public List<HardwoodCarrier> hardwoodCarriers() {
        return hardwoodCarriersCached;
    }

    /**
     * Every condition the guide asks about, step and pre-step completions alike, with each
     * composite replaced by its arms. Pre-steps count because the panel's checklist evaluates
     * them.
     */
    public List<CompletionCondition> leafConditions() {
        List<CompletionCondition> leaves = new ArrayList<>();
        for (GuideStep step : allSteps()) {
            addLeaves(step.getCompletion(), leaves);
            if (step.getPreSteps() != null) {
                for (PreStep preStep : step.getPreSteps()) {
                    addLeaves(preStep.getCompletion(), leaves);
                }
            }
        }
        return leaves;
    }

    private static void addLeaves(CompletionCondition condition, List<CompletionCondition> leaves) {
        if (condition instanceof CompletionCondition.Composite) {
            for (CompletionCondition arm : ((CompletionCondition.Composite) condition).getConditions()) {
                addLeaves(arm, leaves);
            }
        } else if (condition != null) {
            leaves.add(condition);
        }
    }

    static List<GuideStep> flattenSteps(List<Chapter> chapters) {
        if (chapters == null) {
            return Collections.emptyList();
        }
        List<GuideStep> result = new ArrayList<>();
        for (Chapter chapter : chapters) {
            if (chapter.getSections() == null) continue;
            for (Section section : chapter.getSections()) {
                if (section.getEntries() == null) continue;
                for (Entry entry : section.getEntries()) {
                    if (entry.getSteps() == null) continue;
                    result.addAll(entry.getSteps());
                }
            }
        }
        return result;
    }

    static Map<String, Integer> buildStepPositionIndex(List<GuideStep> steps) {
        Map<String, Integer> index = new HashMap<>();
        for (int i = 0; i < steps.size(); i++) {
            index.put(steps.get(i).getId().getValue(), i);
        }
        return index;
    }

    /**
     * Each step's assumptions, in force from the step itself up to the {@code untilStep}.
     * An assumption whose {@code untilStep} the guide does not have, or does not place after
     * the host, is dropped rather than run to the end of the guide: a reminder that never
     * stops is worse than one that never starts. An assumption without a check is dropped too.
     */
    static List<AssumptionSpan> buildAssumptionSpans(List<GuideStep> steps,
                                                     Map<String, Integer> positionIndex) {
        List<AssumptionSpan> spans = new ArrayList<>();
        for (int i = 0; i < steps.size(); i++) {
            List<StepAssumption> assumes = steps.get(i).getAssumes();
            if (assumes == null) {
                continue;
            }
            for (StepAssumption assumption : assumes) {
                if (assumption == null || assumption.getCheck() == null) {
                    continue;
                }
                int until = Integer.MAX_VALUE;
                if (assumption.getUntilStep() != null) {
                    Integer at = positionIndex.get(assumption.getUntilStep().getValue());
                    if (at == null || at <= i) {
                        continue;
                    }
                    until = at;
                }
                spans.add(new AssumptionSpan(i, until, assumption));
            }
        }
        return spans;
    }

    /**
     * The steps that set the hardwood advice, in guide order, each list copied immutable so a
     * snapshot can hand it out without a defensive copy. Null entries are dropped.
     */
    static List<HardwoodCarrier> buildHardwoodCarriers(List<GuideStep> steps) {
        List<HardwoodCarrier> carriers = new ArrayList<>();
        for (GuideStep step : steps) {
            if (step.getKingdomHardwood() == null) {
                continue;
            }
            List<String> names = new ArrayList<>();
            for (String name : step.getKingdomHardwood()) {
                if (name != null) {
                    names.add(name);
                }
            }
            if (!names.isEmpty()) {
                carriers.add(new HardwoodCarrier(step.getId(), List.copyOf(names)));
            }
        }
        return carriers;
    }

    static Map<StepId, StepContext> buildStepContextMap(List<Chapter> chapters) {
        if (chapters == null) {
            return Collections.emptyMap();
        }
        Map<StepId, StepContext> map = new HashMap<>();
        for (Chapter chapter : chapters) {
            if (chapter.getSections() == null) continue;
            for (Section section : chapter.getSections()) {
                if (section.getEntries() == null) continue;
                for (Entry entry : section.getEntries()) {
                    if (entry.getSteps() == null) continue;
                    StepContext ctx = new StepContext(
                            chapter.getTitle(),
                            section.getTitle(),
                            entry.getId(),
                            entry.getOriginalText(),
                            entry.isDurationEstimated() ? null : entry.getEstimatedDurationMinutes(),
                            entry.getItemsNeeded());
                    for (GuideStep step : entry.getSteps()) {
                        map.put(step.getId(), ctx);
                    }
                }
            }
        }
        return map;
    }
}

package com.stepwise.guide;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * The object ids the loaded guide actually asks about, as a sorted primitive array.
 *
 * <p>An {@code objectPresent} sighting is recorded in the player's profile config and never
 * taken back. Object spawns fire in their thousands on every region load, so recording each
 * one would grow without bound. The watchlist limits the record to ids the guide names.
 *
 * <p>A sorted {@code int[]} rather than a {@code Set<Integer>} because the lookup runs in the
 * spawn handler. A boxed set allocates an {@code Integer} per spawn (object ids are above the
 * boxing cache), and a binary search allocates nothing.
 */
public final class WatchedObjectIds {
    private final int[] sortedIds;

    private WatchedObjectIds(int[] sortedIds) {
        this.sortedIds = sortedIds;
    }

    /** Whether the guide asks about this object id. Allocation-free; safe in a hot path. */
    public boolean contains(int objectId) {
        return Arrays.binarySearch(sortedIds, objectId) >= 0;
    }

    /** How many distinct ids the guide asks about. */
    public int size() {
        return sortedIds.length;
    }

    /** Collect the object ids named by every condition in the guide. */
    public static WatchedObjectIds fromGuide(StepwiseGuide guide) {
        Set<Integer> ids = new HashSet<>();
        for (CompletionCondition condition : guide.leafConditions()) {
            if (condition instanceof CompletionCondition.ObjectPresent) {
                ids.addAll(((CompletionCondition.ObjectPresent) condition).getObjectIds());
            }
        }
        int[] sorted = ids.stream().mapToInt(Integer::intValue).sorted().toArray();
        return new WatchedObjectIds(sorted);
    }
}

package com.stepwise.lamp;

import com.stepwise.guide.RoutePosition;
import com.stepwise.guide.StepId;
import com.stepwise.model.Skill;
import java.util.Collection;
import java.util.Map;
import java.util.function.ToIntFunction;
import javax.annotation.Nullable;

/**
 * Picks the guide's skill for an XP chooser session from the lamp policy. Pure: everything it
 * reads arrives as an argument, so it runs without a client.
 *
 * <p>Exceptions win over the schedule. An exception matches the item the player used to open
 * the chooser, inside its optional step window ({@code fromStep} inclusive, {@code untilStep}
 * exclusive, by guide order). When two match, a windowed exception beats an unwindowed one as
 * the more specific; among equals the first in the file wins. Otherwise the schedule entry in
 * force is the one with the latest {@code fromStep} at or before the player's guide position
 * ({@link RoutePosition}).
 */
public final class LampAdvisor
{
	private LampAdvisor()
	{
	}

	/**
	 * @param positionIndex step id to guide order, from the loaded guide
	 * @param activeStepId  the step the player is on, or null when none is active
	 * @param completed     completed steps
	 * @param realLevel     the player's real (unboosted) level in a skill
	 * @param itemId        the item used to open the chooser, or -1 when unknown
	 * @return the recommendation, or null when no rule is in force
	 */
	@Nullable
	public static LampRecommendation recommend(
		LampPolicy policy,
		Map<String, Integer> positionIndex,
		@Nullable String activeStepId,
		Collection<StepId> completed,
		ToIntFunction<Skill> realLevel,
		int itemId)
	{
		int position = RoutePosition.of(positionIndex, activeStepId, completed);

		LampRule match = null;
		for (LampRule rule : policy.getExceptions())
		{
			if (itemId > 0
				&& rule.getItemIds().contains(itemId)
				&& inWindow(rule, positionIndex, position)
				&& (match == null || (rule.isWindowed() && !match.isWindowed())))
			{
				match = rule;
			}
		}
		if (match != null)
		{
			return recommendation(match, realLevel);
		}

		LampRule inForce = null;
		int inForceAt = RoutePosition.NONE;
		for (LampRule rule : policy.getSchedule())
		{
			Integer from = positionIndex.get(rule.getFromStep());
			if (from != null && from <= position && from >= inForceAt)
			{
				inForce = rule;
				inForceAt = from;
			}
		}
		return inForce != null ? recommendation(inForce, realLevel) : null;
	}

	/**
	 * Whether {@code position} lies in the rule's window, from {@code fromStep} up to but not
	 * including {@code untilStep}. A bound the guide does not have closes the window.
	 */
	private static boolean inWindow(LampRule rule, Map<String, Integer> positionIndex, int position)
	{
		if (rule.getFromStep() != null)
		{
			Integer from = positionIndex.get(rule.getFromStep());
			if (from == null || position < from)
			{
				return false;
			}
		}
		if (rule.getUntilStep() != null)
		{
			Integer until = positionIndex.get(rule.getUntilStep());
			return until != null && position < until;
		}
		return true;
	}

	private static LampRecommendation recommendation(LampRule rule, ToIntFunction<Skill> realLevel)
	{
		Skill skill = rule.skillAt(realLevel.applyAsInt(rule.getSkill()));
		return new LampRecommendation(skill, rule.getFallback(), rule.getNote());
	}
}

package com.stepwise.lamp;

import java.util.Locale;
import java.util.Set;
import net.runelite.client.util.Text;

/**
 * Remembers which lamp, tome or book the player used to open the XP chooser.
 *
 * <p>Only the player's own click on an inventory item with an option that opens the chooser
 * counts, and only when the chooser opens within {@link #CAPTURE_TICKS} of it. The server
 * answers the click on its next tick or so, and the window leaves room for a few laggy ticks
 * but not for a conversation. A chooser an NPC hands over in dialogue after a lamp was rubbed
 * therefore opens with no item and gets the schedule. Closing the chooser forgets the item as
 * well, and one click explains one chooser at most.
 *
 * <p>Pure: callers pass the game tick, so it runs without a client.
 */
public final class LampChooserTracker
{
	/** The most ticks between the click and the chooser opening, 3 seconds. */
	static final int CAPTURE_TICKS = 5;

	/**
	 * Inventory options that open the chooser, lowercased: lamps are rubbed, tomes and books
	 * read, the blessed lamp prayed over, the dark relic communed with.
	 */
	private static final Set<String> CHOOSER_OPTIONS = Set.of("rub", "read", "pray-over", "commune");

	private static final int NONE = -1;

	private int clickedItemId = NONE;
	private int clickedTick;
	private boolean open;
	private int sessionItemId = NONE;

	/**
	 * The player chose {@code option} on inventory item {@code itemId}. Remembered only when
	 * the option is one that opens the chooser; any other click leaves the memory alone.
	 */
	public void onItemOp(int itemId, String option, int tick)
	{
		if (itemId > 0 && option != null
			&& CHOOSER_OPTIONS.contains(Text.removeTags(option).toLowerCase(Locale.ROOT)))
		{
			clickedItemId = itemId;
			clickedTick = tick;
		}
	}

	/**
	 * The chooser opened.
	 *
	 * @return the item that opened it, or -1 when no click just before explains it
	 */
	public int onChooserOpened(int tick)
	{
		if (open)
		{
			return sessionItemId;
		}
		open = true;
		int age = tick - clickedTick;
		sessionItemId = clickedItemId != NONE && age >= 0 && age <= CAPTURE_TICKS ? clickedItemId : NONE;
		clickedItemId = NONE;
		return sessionItemId;
	}

	/**
	 * The chooser's interface closed. Only an unload ends the session: a close without one
	 * moves the interface (a fixed/resizable layout switch) and is followed by a fresh load.
	 *
	 * @return whether a session ended, so the caller clears the highlight
	 */
	public boolean onChooserClosed(boolean unload)
	{
		if (!unload)
		{
			return false;
		}
		boolean wasOpen = open;
		endSession();
		return wasOpen;
	}

	/**
	 * A game tick passed.
	 *
	 * @param chooserPresent whether the chooser's interface is still loaded
	 * @return whether this ended a session the close event never reported
	 */
	public boolean onGameTick(boolean chooserPresent)
	{
		if (open && !chooserPresent)
		{
			endSession();
			return true;
		}
		return false;
	}

	public boolean isOpen()
	{
		return open;
	}

	/** Forget everything, for a logout or a plugin restart. */
	public void reset()
	{
		endSession();
		clickedTick = 0;
	}

	private void endSession()
	{
		open = false;
		sessionItemId = NONE;
		clickedItemId = NONE;
	}
}

package com.stepwise.lamp;

import com.stepwise.StepwiseConfig;
import com.stepwise.model.Skill;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Outlines the guide's skill on the XP reward chooser, with the guide's reason as a tooltip.
 *
 * <p>Draws only: it adds no menu entries, handles no clicks, and leaves the chooser's own
 * widgets untouched. When the recommended skill is faded on this lamp it draws the policy's
 * fallback instead, or nothing. It reads the game's own fade rather than repeating the game's
 * eligibility rules.
 *
 * <p>The recommendation is resolved once when the chooser opens; a frame reads only it, the
 * widgets and the mouse.
 */
public class LampHighlightOverlay extends Overlay
{
	private static final Color OUTLINE = new Color(0, 255, 255);
	private static final Color FILL = new Color(0, 255, 255, 65);
	private static final Stroke STROKE = new BasicStroke(2);

	/** Whether a skill's button can be chosen on the open chooser. */
	interface SkillProbe
	{
		boolean isSelectable(Skill skill);
	}

	private final Client client;
	private final StepwiseConfig config;
	private final TooltipManager tooltipManager;
	private final SkillProbe probe = this::isLayerSelectable;

	/**
	 * The open chooser's recommendation and its tooltip, swapped together as one value.
	 * Volatile: the event handlers and render run on the client thread, but plugin start and
	 * stop clear it from the EDT.
	 */
	private volatile Session session;

	/** A recommendation with the tooltip built for it once, not per frame. */
	private static final class Session
	{
		final LampRecommendation recommendation;
		final Tooltip tooltip;

		Session(LampRecommendation recommendation)
		{
			this.recommendation = recommendation;
			this.tooltip = recommendation.getNote().isEmpty() ? null : new Tooltip(recommendation.getNote());
		}
	}

	@Inject
	public LampHighlightOverlay(Client client, StepwiseConfig config, TooltipManager tooltipManager)
	{
		this.client = client;
		this.config = config;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Show {@code rec} for the chooser now open; null when it closes or nothing applies. */
	public void setRecommendation(@Nullable LampRecommendation rec)
	{
		session = rec != null ? new Session(rec) : null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Session current = session;
		if (current == null)
		{
			return null;
		}
		Skill target = highlightTarget(
			config.highlightLampSkill(), current.recommendation, probe);
		if (target == null)
		{
			return null;
		}
		Widget layer = client.getWidget(XpRewardSkills.componentId(target));
		if (layer == null || layer.isHidden())
		{
			return null;
		}
		Rectangle bounds = layer.getBounds();
		graphics.setColor(FILL);
		graphics.fill(bounds);
		graphics.setColor(OUTLINE);
		graphics.setStroke(STROKE);
		graphics.draw(bounds);

		if (current.tooltip != null)
		{
			Point mouse = client.getMouseCanvasPosition();
			if (mouse != null && bounds.contains(mouse.getX(), mouse.getY()))
			{
				tooltipManager.add(current.tooltip);
			}
		}
		return null;
	}

	/**
	 * The skill to outline: the recommended one when selectable, else its fallback when that
	 * is, else none.
	 */
	@Nullable
	static Skill highlightTarget(boolean enabled, @Nullable LampRecommendation rec, SkillProbe probe)
	{
		if (!enabled || rec == null)
		{
			return null;
		}
		if (probe.isSelectable(rec.getSkill()))
		{
			return rec.getSkill();
		}
		Skill fallback = rec.getFallback();
		if (fallback != null && fallback != rec.getSkill() && probe.isSelectable(fallback))
		{
			return fallback;
		}
		return null;
	}

	private boolean isLayerSelectable(Skill skill)
	{
		return isSelectable(client.getWidget(XpRewardSkills.componentId(skill)));
	}

	/**
	 * Whether the chooser lets the player pick this skill button.
	 *
	 * <p>The chooser's update script rebuilds each button layer's children: nine button tiles,
	 * then the skill icon. A selectable skill leaves all of them at transparency 0. One the
	 * player lacks the level or quest for gets its icon set to 150; one this lamp does not
	 * offer gets every child set to 220. So any child above 0 means faded. A layer with no
	 * children yet, before the script has run, reads as selectable.
	 */
	static boolean isSelectable(@Nullable Widget layer)
	{
		if (layer == null || layer.isHidden())
		{
			return false;
		}
		Widget[] children = layer.getChildren();
		if (children == null)
		{
			return true;
		}
		for (Widget child : children)
		{
			if (child != null && child.getOpacity() != 0)
			{
				return false;
			}
		}
		return true;
	}
}

package com.stepwise.lamp;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Which skill the guide puts XP lamps on: a schedule keyed to guide position, and exceptions
 * for particular lamp items. Immutable.
 */
public final class LampPolicy
{
	/** No rules: nothing is ever highlighted. */
	public static final LampPolicy EMPTY = new LampPolicy(List.of(), List.of());

	private final List<LampRule> schedule;
	private final List<LampRule> exceptions;

	public LampPolicy(List<LampRule> schedule, List<LampRule> exceptions)
	{
		this.schedule = List.copyOf(schedule);
		this.exceptions = List.copyOf(exceptions);
	}

	public List<LampRule> getSchedule()
	{
		return schedule;
	}

	public List<LampRule> getExceptions()
	{
		return exceptions;
	}

	public boolean isEmpty()
	{
		return schedule.isEmpty() && exceptions.isEmpty();
	}

	/**
	 * Step ids the policy names that {@code positionIndex} lacks. A rule naming one is never
	 * in force.
	 */
	public List<String> unknownSteps(Map<String, Integer> positionIndex)
	{
		List<String> unknown = new ArrayList<>();
		for (List<LampRule> rules : List.of(schedule, exceptions))
		{
			for (LampRule rule : rules)
			{
				for (String id : new String[]{rule.getFromStep(), rule.getUntilStep()})
				{
					if (id != null && !positionIndex.containsKey(id) && !unknown.contains(id))
					{
						unknown.add(id);
					}
				}
			}
		}
		return unknown;
	}
}

package com.stepwise.lamp;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.stepwise.guide.GuideLoader;
import com.stepwise.model.Skill;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads {@code lamp_policy.json} from plugin resources.
 *
 * <p>Never throws and never returns null: a missing, unreadable or malformed file yields
 * {@link LampPolicy#EMPTY}, and the plugin then highlights nothing on XP lamps. A missing
 * file logs a warning. A rule that names an unknown skill, lacks a required field, or puts
 * {@code untilStep} on a schedule entry is dropped on its own.
 */
@Slf4j
public final class LampPolicyLoader
{
	static final String RESOURCE = "/com/stepwise/lamp_policy.json";

	private LampPolicyLoader()
	{
	}

	public static LampPolicy loadFromResource(Gson gson)
	{
		return loadFromResource(RESOURCE, gson);
	}

	static LampPolicy loadFromResource(String resourcePath, Gson gson)
	{
		return GuideLoader.readResource(resourcePath, reader -> parse(reader, gson), () -> LampPolicy.EMPTY);
	}

	static LampPolicy parse(Reader reader, Gson gson)
	{
		RawPolicy raw;
		try
		{
			raw = gson.fromJson(reader, RawPolicy.class);
		}
		catch (JsonParseException e)
		{
			log.warn("Failed to parse lamp_policy.json; XP lamp highlight disabled", e);
			return LampPolicy.EMPTY;
		}
		if (raw == null)
		{
			log.warn("lamp_policy.json is empty; XP lamp highlight disabled");
			return LampPolicy.EMPTY;
		}
		List<LampRule> schedule = freeze(raw.schedule, false);
		List<LampRule> exceptions = freeze(raw.exceptions, true);
		log.debug("Loaded lamp policy: {} schedule entries, {} exceptions",
			schedule.size(), exceptions.size());
		return new LampPolicy(schedule, exceptions);
	}

	private static List<LampRule> freeze(List<RawRule> rawRules, boolean exception)
	{
		List<LampRule> rules = new ArrayList<>();
		if (rawRules == null)
		{
			return rules;
		}
		for (RawRule raw : rawRules)
		{
			LampRule rule = raw == null ? null : freeze(raw, exception);
			if (rule != null)
			{
				rules.add(rule);
			}
		}
		return rules;
	}

	private static LampRule freeze(RawRule raw, boolean exception)
	{
		Skill skill = skill(raw.skill);
		Skill then = skill(raw.then);
		Skill fallback = skill(raw.fallback);
		int untilLevel = raw.untilLevel != null ? raw.untilLevel : 0;
		boolean levelSwitchHalfSet = (untilLevel > 0) != (raw.then != null);
		boolean badSkill = skill == null
			|| (raw.then != null && then == null)
			|| (raw.fallback != null && fallback == null);
		// A schedule entry runs until the next one starts, so an untilStep on it is a mistake.
		boolean badTrigger = exception
			? raw.itemIds == null || raw.itemIds.isEmpty() || raw.itemIds.contains(null)
			: raw.fromStep == null || raw.untilStep != null;
		if (badSkill || levelSwitchHalfSet || badTrigger)
		{
			log.warn("lamp_policy.json: dropping unusable rule (skill {}, from {}, items {})",
				raw.skill, raw.fromStep, raw.itemIds);
			return null;
		}
		return new LampRule(
			raw.fromStep,
			raw.untilStep,
			skill,
			untilLevel,
			then,
			fallback,
			raw.note != null ? raw.note : "",
			exception ? Set.copyOf(raw.itemIds) : Set.of());
	}

	private static Skill skill(String name)
	{
		if (name == null)
		{
			return null;
		}
		try
		{
			return Skill.fromString(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/** The file's shape, as written; checked and frozen into {@link LampRule}s. */
	private static final class RawPolicy
	{
		List<RawRule> schedule;
		List<RawRule> exceptions;
	}

	private static final class RawRule
	{
		String fromStep;
		String untilStep;
		String skill;
		Integer untilLevel;
		String then;
		String fallback;
		String note;
		List<Integer> itemIds;
	}
}

