package com.stepwise.overlay;

import com.stepwise.engine.BirdhouseTracker;
import com.stepwise.engine.BirdhouseTracker.BirdhouseSpace;
import com.stepwise.engine.BirdhouseTracker.BirdhouseTier;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.util.Locale;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * One InfoBox for all four bird house spaces. The player runs Fossil Island once every
 * house is done, so the countdown shows the LONGEST remaining fill time. The colour goes
 * green (none ready), yellow-green (some ready), gold (all ready); the tooltip lists each
 * house. Text and colour are read live from {@link BirdhouseTracker} on every render.
 */
public class BirdhouseInfoBox extends InfoBox {

    private static final Color COLOR_FILLING = new Color(100, 160, 100);
    private static final Color COLOR_PARTIAL = new Color(180, 200, 90);
    private static final Color COLOR_READY = new Color(255, 200, 50);

    private final BirdhouseTracker tracker;

    // InfoBoxOverlay calls getTooltip() every frame for every visible box (only the display
    // is hover-gated), so the string is rebuilt at most once per second. Render calls are
    // single-threaded, so no synchronization.
    private String tooltipCache;
    private long tooltipBuiltAtSec;

    public BirdhouseInfoBox(BufferedImage image, Plugin plugin, BirdhouseTracker tracker) {
        super(image, plugin);
        this.tracker = tracker;
    }

    @Override
    public String getText() {
        long longest = longestRemaining(now());
        if (longest <= 0) {
            return "Ready";
        }
        return ceilMinutes(longest) + "m";
    }

    @Override
    public Color getTextColor() {
        long nowSec = now();
        if (longestRemaining(nowSec) <= 0) {
            return COLOR_READY;
        }
        return countReady(nowSec) > 0 ? COLOR_PARTIAL : COLOR_FILLING;
    }

    @Override
    public String getTooltip() {
        long nowSec = now();
        if (tooltipCache == null || nowSec != tooltipBuiltAtSec) {
            tooltipBuiltAtSec = nowSec;
            tooltipCache = buildTooltip(nowSec);
        }
        return tooltipCache;
    }

    private String buildTooltip(long nowSec) {
        StringBuilder sb = new StringBuilder("Bird houses");
        for (BirdhouseSpace space : BirdhouseSpace.values()) {
            if (!tracker.isSeeded(space)) {
                continue;
            }
            long remaining = tracker.remainingSeconds(space, nowSec);
            sb.append("</br>").append(space.getLabel());
            String tier = tierName(space);
            if (tier != null) {
                sb.append(" (").append(tier).append(')');
            }
            sb.append(": ").append(BirdhouseTracker.timeLeft(remaining));
        }
        return sb.toString();
    }

    @Override
    public boolean render() {
        // Hide once no house is seeded, before the plugin removes the InfoBox.
        return tracker.anySeeded();
    }

    /** Longest remaining fill time among seeded houses: when the whole run is ready. */
    private long longestRemaining(long nowSec) {
        long longest = 0;
        for (BirdhouseSpace space : BirdhouseSpace.values()) {
            if (tracker.isSeeded(space)) {
                long remaining = tracker.remainingSeconds(space, nowSec);
                if (remaining > longest) {
                    longest = remaining;
                }
            }
        }
        return longest;
    }

    private int countReady(long nowSec) {
        int count = 0;
        for (BirdhouseSpace space : BirdhouseSpace.values()) {
            if (tracker.isReady(space, nowSec)) {
                count++;
            }
        }
        return count;
    }

    /**
     * "oak" for an oak bird house, lowercase like the item name mid-line; null for a plain or
     * unknown one, which needs no tier. {@link Locale#ROOT} keeps "willow" dotted on a
     * Turkish-locale client.
     */
    private String tierName(BirdhouseSpace space) {
        BirdhouseTier tier = tracker.tierOf(space);
        if (tier == null || tier == BirdhouseTier.NORMAL) {
            return null;
        }
        return tier.name().toLowerCase(Locale.ROOT);
    }

    private static long now() {
        return Instant.now().getEpochSecond();
    }

    private static long ceilMinutes(long seconds) {
        return (seconds + 59) / 60;
    }
}

package com.stepwise.overlay;

import com.stepwise.StepwiseConfig;
import com.stepwise.engine.CoreEngine;
import com.stepwise.model.PlayerState;
import com.stepwise.panel.TextMarkup;
import com.stepwise.snapshot.AssumptionNudge;
import com.stepwise.snapshot.CompletionCriterion;
import com.stepwise.snapshot.CriterionProgress;
import com.stepwise.snapshot.CurrentStepSummary;
import com.stepwise.snapshot.DashboardSnapshot;
import com.stepwise.snapshot.GuidePosition;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * In-game overlay showing the current guide step, criteria, and progress.
 * Movable and resizable.
 */
public class StepOverlay extends OverlayPanel
{
	private static final Color COLOR_MET = new Color(0, 180, 0);
	private static final Color COLOR_UNMET = new Color(180, 180, 180);
	private static final Color COLOR_PROGRESS_BG = new Color(60, 60, 60);
	private static final Color COLOR_PROGRESS_FG = new Color(80, 180, 80);
	private static final Color COLOR_BANK_NUDGE = new Color(255, 220, 100);

	/** Wider than OverlayPanel's default to reduce text wrapping. */
	private static final int DEFAULT_WIDTH = 220;

	private final StepwiseConfig config;
	/**
	 * Volatile: set at startUp and cleared at shutDown, while the client thread renders.
	 * Read once per frame, since shutDown can clear it mid-render.
	 */
	private volatile CoreEngine coreEngine;
	/** The nudges {@link #cachedAssumptionLine} was built from. Render thread only. */
	private List<AssumptionNudge> cachedNudges;
	private String cachedAssumptionLine;
	/** The position {@link #cachedCounter} was built from. Render thread only. */
	private GuidePosition cachedCounterPosition;
	private String cachedCounter;

	@Inject
	public StepOverlay(StepwiseConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(Overlay.PRIORITY_LOW);
		setResizable(true);
		panelComponent.setPreferredSize(new Dimension(DEFAULT_WIDTH, 0));
	}

	public void setCoreEngine(CoreEngine coreEngine)
	{
		this.coreEngine = coreEngine;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		CoreEngine engine = coreEngine;
		if (!config.showStepOverlay() || engine == null)
		{
			return null;
		}

		DashboardSnapshot snapshot = engine.getLastSnapshot();
		if (snapshot == null)
		{
			return null;
		}

		CurrentStepSummary step = snapshot.getCurrentStep();
		if (step == null)
		{
			renderNoStep(snapshot);
		}
		else
		{
			renderGuideStep(step, snapshot, engine.getPlayerState());
		}
		return super.render(graphics);
	}

	private void renderNoStep(DashboardSnapshot snapshot)
	{
		GuidePosition pos = snapshot.getGuidePosition();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Stepwise")
			.color(Color.CYAN)
			.build());
		if (pos != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(stepCounter(pos))
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left(TextMarkup.plainInstruction(pos.getInstruction()))
				.build());
		}
		else
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Finding your step...")
				.build());
		}
	}

	/**
	 * The step counter, rebuilt only when the snapshot's position changes: it formats with
	 * {@code String.format}, which is too costly to run every frame.
	 */
	private String stepCounter(GuidePosition pos)
	{
		if (pos != cachedCounterPosition)
		{
			cachedCounterPosition = pos;
			cachedCounter = pos.stepCounter();
		}
		return cachedCounter;
	}

	private void renderGuideStep(CurrentStepSummary step, DashboardSnapshot snapshot,
		PlayerState state)
	{
		GuidePosition pos = snapshot.getGuidePosition();
		String title = "Stepwise";
		if (pos != null)
		{
			title = stepCounter(pos);
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(title)
			.color(Color.CYAN)
			.build());

		// Strip ~~markup~~: Graphics2D cannot render strikethrough.
		if (pos != null && pos.getChapter() != null)
		{
			String breadcrumb = TextMarkup.stripMarkup(pos.getChapter());
			if (pos.getSection() != null && !pos.getSection().equals(pos.getChapter()))
			{
				breadcrumb += " > " + TextMarkup.stripMarkup(pos.getSection());
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left(breadcrumb)
				.leftColor(Color.GRAY)
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(TextMarkup.plainInstruction(step.getInstruction()))
			.build());

		// Only with the bank open: the panel keeps a reminder for stock held anywhere up until
		// the player restocks, but on the game view it would cover the scene for many steps.
		String assumptionLine = state != null && state.isBankOpen()
			? assumptionLine(step.getAssumptionNudges()) : null;
		if (assumptionLine != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(assumptionLine)
				.leftColor(COLOR_BANK_NUDGE)
				.build());
		}

		List<CompletionCriterion> criteria = step.getCriteria();
		if (criteria != null)
		{
			for (CompletionCriterion criterion : criteria)
			{
				renderCriterion(criterion);
			}
		}
	}

	/**
	 * The one line the overlay gives the route-assumption reminders: the first, with a count
	 * of the rest, so an open bank never pushes the criteria far down. Cached by list
	 * identity, since the snapshot's list is fixed until the next snapshot replaces it.
	 */
	String assumptionLine(List<AssumptionNudge> nudges)
	{
		if (nudges == null || nudges.isEmpty())
		{
			return null;
		}
		if (nudges != cachedNudges)
		{
			cachedNudges = nudges;
			String first = nudges.get(0).getReminder();
			cachedAssumptionLine = nudges.size() == 1
				? first
				: first + " (+" + (nudges.size() - 1) + " more)";
		}
		return cachedAssumptionLine;
	}

	private void renderCriterion(CompletionCriterion criterion)
	{
		String icon = criterion.isMet() ? "\u2713" : "\u2022";
		// Amber when a bank withdrawal would satisfy an unmet inventory requirement
		// (see CompletionCriterion.inBankCount). Matches the panel's hint.
		Color color = criterion.isMet() ? COLOR_MET
			: criterion.getInBankCount() > 0 ? COLOR_BANK_NUDGE : COLOR_UNMET;

		// A waived criterion arrives met because the step it serves is done, not because the
		// game state meets it, so like the panel's row it says "(done)".
		String description = criterion.isWaived()
			? criterion.getDescription() + " (done)"
			: criterion.getDescription();
		panelComponent.getChildren().add(LineComponent.builder()
			.left(icon + " " + description)
			.leftColor(color)
			.build());

		CriterionProgress progress = criterion.getProgress();
		if (progress != null && progress.getRequired() > 1 && !criterion.isMet())
		{
			ProgressBarComponent progressBar = new ProgressBarComponent();
			progressBar.setMinimum(0);
			progressBar.setMaximum(progress.getRequired());
			progressBar.setValue(progress.getCurrent());
			progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.PERCENTAGE);
			progressBar.setBackgroundColor(COLOR_PROGRESS_BG);
			progressBar.setForegroundColor(COLOR_PROGRESS_FG);

			panelComponent.getChildren().add(progressBar);

			if (progress.getBankNudge() != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("  " + progress.getBankNudge())
					.leftColor(COLOR_BANK_NUDGE)
					.build());
			}
		}
	}
}

package com.stepwise.panel;

import java.awt.Color;
import javax.swing.JButton;
import javax.swing.Timer;

/**
 * A button for an action worth a second thought: the first click arms it, reading "Confirm?" in
 * the danger colour, and only a second click acts. {@link #disarm} puts it back to rest.
 */
class ConfirmButton extends JButton
{
	/** How long a timed button waits armed for its confirming click. */
	static final int CONFIRM_MS = 4_000;

	private final String label;
	/**
	 * Disarms a click never confirmed, or null when the button waits until {@link #disarm}.
	 * A card that is not rebuilt would otherwise keep a "Confirm?" waiting for any later stray
	 * click.
	 */
	private final Timer disarmTimer;
	private Color restingColour;
	private boolean armed;

	/**
	 * Styles nothing: the caller sets the font and colours, and the resting colour is read
	 * when the button arms.
	 *
	 * @param timed whether an unconfirmed click disarms after {@link #CONFIRM_MS}
	 */
	ConfirmButton(String label, boolean timed, Runnable action)
	{
		super(label);
		this.label = label;
		if (timed)
		{
			disarmTimer = new Timer(CONFIRM_MS, e -> disarm());
			disarmTimer.setRepeats(false);
		}
		else
		{
			disarmTimer = null;
		}
		addActionListener(e ->
		{
			if (armed)
			{
				disarm();
				action.run();
				return;
			}
			armed = true;
			restingColour = getForeground();
			setText("Confirm?");
			setForeground(PanelColors.DANGER);
			if (disarmTimer != null)
			{
				disarmTimer.restart();
			}
		});
	}

	/** Puts an armed button back to its label, so the next click arms it again. */
	void disarm()
	{
		if (disarmTimer != null)
		{
			disarmTimer.stop();
		}
		if (armed)
		{
			armed = false;
			setText(label);
			setForeground(restingColour);
		}
	}

	/** Test seam: the timer that disarms an unconfirmed click, or null. */
	Timer disarmTimerForTest()
	{
		return disarmTimer;
	}
}

package com.stepwise.panel;

import com.stepwise.guide.GuideStep;
import com.stepwise.guide.StepwiseGuide;
import com.stepwise.guide.StepContext;
import com.stepwise.guide.StepId;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.swing.BorderFactory;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The current entry, above the step card: a title line naming it, then three chips for its
 * original text, the items it asks for, and how the account compares with the route. One
 * chip is open at a time, and a new entry starts with all of them shut.
 *
 * <p>{@link ItemsNeededView} and {@link RouteDeficitPanel} keep their own views and update
 * logic. This block's chips open and shut them.
 */
class EntryBlock extends JPanel
{
	private static final Color COLOR_CHIP_TEXT = PanelColors.HEADER;
	private static final Color COLOR_DURATION = new Color(140, 140, 120);
	private static final Color COLOR_TEXT = new Color(180, 180, 160);

	private static final Border CHIP_SHUT = PanelSections.chipBorder(PanelColors.CONTAINER_BORDER);
	private static final Border CHIP_OPEN = PanelSections.chipBorder(ColorScheme.BRAND_ORANGE);

	/** The route chip's indicator icons, sized to the chip's text so the row keeps its height. */
	static final int CHIP_ICON_SIZE = 12;
	/** Space between the title and the duration beside it. */
	private static final int TITLE_GAP = 4;
	private static final int CHIP_GAP = PanelSections.CHIP_GAP;
	/** Room the first row must have to spare before the route chip moves back up to it. */
	static final int CHIP_RETURN_MARGIN = 20;
	private static final Border PART_FIRST = BorderFactory.createEmptyBorder();
	/** Space between two route indicators. */
	private static final Border PART_NEXT = BorderFactory.createEmptyBorder(0, 5, 0, 0);

	private static final String TEXT_TOOLTIP = "The guide's own words for this entry";
	private static final String ITEMS_TOOLTIP = "Items this entry asks for, and whether you have them";

	/** Which chip is open. */
	enum Open
	{
		NONE, TEXT, ITEMS, ROUTE
	}

	private final ItemsNeededView items;
	private final RouteDeficitPanel route;

	/** The current step's section header: the entry and the step's place in it. */
	private final JLabel title = PanelSections.smallLabel(" ", COLOR_CHIP_TEXT);
	/** The title, with the entry's duration on the right. */
	private final JPanel titleRow;
	private final JLabel duration = PanelSections.smallLabel(" ", COLOR_DURATION);
	private final JLabel textChip;
	private final JLabel itemsChip;
	/**
	 * One chip holding an indicator each for GP, skills, quests and diary tasks against the
	 * guide.
	 */
	private final JPanel routeChip;
	private final JLabel gpPart;
	private final JLabel skillsPart;
	private final JLabel questsPart;
	private final JLabel diaryPart;
	/** The indicators in chip order. */
	private final JLabel[] routeParts;
	private final JPanel chipRow;
	private final JPanel routeRow;
	private final JPanel textBody;
	/** The entry's source text: its links inline, or as rows when they end the text. */
	private final LinkedText text;

	private Open open = Open.NONE;
	private String entryId;
	/** Set on a new entry, so the route chip is placed without {@link #CHIP_RETURN_MARGIN}. */
	private boolean placeAfresh = true;
	/** The current step's place in its entry, recounted only when the step changes. */
	private String stepId;
	private int stepNumber;
	private int stepCount;
	/** Whether the entry has original text, so the Text chip has something to open. */
	private boolean hasText;

	EntryBlock(ItemsNeededView items, RouteDeficitPanel route)
	{
		this.items = items;
		this.route = route;

		PanelSections.column(this);
		setBorder(PanelSections.gap(PanelSections.SECTION_GAP));

		// The title is the current step's section header; the duration stays muted beside it.
		PanelSections.styleAsHeader(title);
		// The hgap keeps a space between a long title and the duration.
		titleRow = new JPanel(new BorderLayout(TITLE_GAP, 0));
		titleRow.setOpaque(false);
		titleRow.setAlignmentX(LEFT_ALIGNMENT);
		titleRow.setBorder(PanelSections.HEADER_INSET);
		titleRow.add(title, BorderLayout.WEST);
		titleRow.add(duration, BorderLayout.EAST);
		titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, titleRow.getPreferredSize().height));

		textChip = PanelSections.chip("Guide text", COLOR_CHIP_TEXT, CHIP_SHUT, () -> toggle(Open.TEXT));
		textChip.setToolTipText(TEXT_TOOLTIP);
		itemsChip = PanelSections.chip("Items", COLOR_CHIP_TEXT, CHIP_SHUT, () -> toggle(Open.ITEMS));
		itemsChip.setToolTipText(ITEMS_TOOLTIP);
		gpPart = routePart();
		skillsPart = routePart();
		questsPart = routePart();
		diaryPart = routePart();
		routeParts = new JLabel[]{gpPart, skillsPart, questsPart, diaryPart};
		routeChip = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		routeChip.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		routeChip.addMouseListener(PanelSections.clicks(() -> toggle(Open.ROUTE)));
		routeChip.add(gpPart);
		routeChip.add(skillsPart);
		routeChip.add(questsPart);
		routeChip.add(diaryPart);
		routeChip.setVisible(false);
		style(routeChip, false);
		chipRow = PanelSections.chipRow();
		chipRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		chipRow.add(textChip);
		chipRow.add(itemsChip);
		chipRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, chipRow.getPreferredSize().height));
		// The route chip's own row, used when it does not fit beside the other two chips.
		routeRow = PanelSections.chipRow();
		routeRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		routeRow.add(routeChip);
		routeRow.setMaximumSize(chipRow.getMaximumSize());
		routeRow.setVisible(false);

		text = new LinkedText(COLOR_TEXT, FontManager.getRunescapeSmallFont());
		text.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));
		textBody = PanelSections.box();
		textBody.add(text);
		textBody.setVisible(false);

		add(titleRow);
		add(chipRow);
		add(routeRow);
		add(textBody);
		add(items);
		add(route);
		setVisible(false);
	}

	/**
	 * A block with the title line and the Guide text chip only. Its items view and route
	 * panel are never fed, so they stay hidden and their chips with them.
	 */
	static EntryBlock textOnly()
	{
		return new EntryBlock(new ItemsNeededView(), new RouteDeficitPanel());
	}

	/**
	 * Follows the current step. Called on every refresh, after the items view and the route
	 * panel have taken the same snapshot. Every write is a no-op when nothing changed, so an
	 * unchanged refresh triggers no layout.
	 *
	 * @param context the current step's context, or null when there is no current step
	 */
	void update(StepContext context, String currentStepId, StepwiseGuide guide)
	{
		if (context == null || context.getEntryId() == null)
		{
			setVisible(false);
			entryId = null;
			stepId = null;
			return;
		}

		// The title, the duration and the text are written only when the entry or step changes.
		boolean newEntry = !Objects.equals(context.getEntryId(), entryId);
		if (newEntry)
		{
			entryId = context.getEntryId();
			open = Open.NONE;
			placeAfresh = true;
			String original = context.getOriginalText();
			hasText = original != null && !original.isEmpty();
			// Source text: its asterisks and underscores are literal, so no inline markup. Set
			// here, on a new entry only, so a same-entry refresh never rebuilds the wrapping text.
			text.setMarkdown(hasText ? original : "", false);
			String time = StepwisePanel.formatEntryDuration(context.getEntryDurationMinutes());
			duration.setText(time != null ? time : "");
		}
		if (newEntry || !Objects.equals(currentStepId, stepId))
		{
			stepId = currentStepId;
			countStep(guide);
			title.setText(titleOf(entryId, stepNumber, stepCount));
		}

		textChip.setVisible(hasText);
		itemsChip.setVisible(items.hasItems());
		itemsChip.setText("Items " + items.itemCount());
		updateRouteChip();

		// Close the open chip if it has just been hidden.
		if ((open == Open.TEXT && !textChip.isVisible())
			|| (open == Open.ITEMS && !itemsChip.isVisible())
			|| (open == Open.ROUTE && !routeChip.isVisible()))
		{
			open = Open.NONE;
		}
		applyOpen();
		setVisible(true);
	}

	/**
	 * One indicator each for GP, skills, quests and diary tasks, shown only once it has a
	 * reading. Every write below is guarded or a no-op on an unchanged value, because this
	 * runs on every refresh.
	 */
	private void updateRouteChip()
	{
		routeChip.setVisible(route.hasComparison());

		boolean gp = route.isGpKnown();
		setPart(gpPart, gp, route.coinsIcon(CHIP_ICON_SIZE), "Coins", gpText(route.gpDelta()),
			RouteDeficitPanel.toneOf(route.gpDelta()),
			gpTooltip(route.gpDelta(), route.isSkipOnOffer()));

		boolean skills = route.isSkillsKnown();
		int skillsDelta = countDelta(route.skillsBehind(), route.skillsAhead());
		setPart(skillsPart, skills, route.skillsIcon(CHIP_ICON_SIZE), "Skills",
			countText(skillsDelta), RouteDeficitPanel.toneOf(skillsDelta),
			countsTooltip("skill", "skills", route.skillsBehind(), route.skillsAhead()));

		boolean quests = route.isQuestsKnown();
		int questsDelta = countDelta(route.questsBehind(), route.questsAhead());
		setPart(questsPart, quests, route.questIcon(CHIP_ICON_SIZE), "Quests",
			countText(questsDelta), RouteDeficitPanel.toneOf(questsDelta),
			countsTooltip("quest", "quests", route.questsBehind(), route.questsAhead()));

		// Shown only when something is owed: a diary task done early is not tracked as ahead.
		int diaryBehind = route.diaryTasksBehind();
		setPart(diaryPart, diaryBehind > 0, route.diaryIcon(CHIP_ICON_SIZE), "Diary",
			countText(-diaryBehind), RouteDeficitPanel.toneOf(-diaryBehind),
			countsTooltip("diary task", "diary tasks", diaryBehind, 0));

		// The first indicator shown sits on the chip's own padding; the others keep apart.
		boolean first = true;
		for (JLabel part : routeParts)
		{
			if (!part.isVisible())
			{
				continue;
			}
			Border border = first ? PART_FIRST : PART_NEXT;
			if (part.getBorder() != border)
			{
				part.setBorder(border);
			}
			first = false;
		}
		placeRouteChip();
	}

	/**
	 * Puts the route chip beside the other chips when the row has room, and on a row of its
	 * own when it has not. FlowLayout would wrap an overflowing chip onto a line the row's
	 * fixed height never shows, so the chip would vanish.
	 *
	 * <p>The chip comes back up only with {@link #CHIP_RETURN_MARGIN} to spare. Its figures
	 * change width as coins move, and without the margin a player near the edge would see the
	 * whole panel below shift by a row every few ticks.
	 */
	private void placeRouteChip()
	{
		boolean inFirstRow = routeChip.getParent() == chipRow;
		int chip = routeChip.getPreferredSize().width + CHIP_GAP;
		int others = chipRow.getPreferredSize().width
			- (inFirstRow && routeChip.isVisible() ? chip : 0);
		boolean fits = fitsFirstRow(others + chip, inFirstRow, placeAfresh);
		placeAfresh = false;
		if (fits != inFirstRow)
		{
			(fits ? chipRow : routeRow).add(routeChip);
			chipRow.revalidate();
			routeRow.revalidate();
		}
		routeRow.setVisible(!fits && routeChip.isVisible());
	}

	/**
	 * Whether the route chip belongs on the first row, which it needs {@code needed} pixels of.
	 * A new entry places afresh: the margin only damps movement within one entry.
	 */
	static boolean fitsFirstRow(int needed, boolean inFirstRow, boolean afresh)
	{
		return needed <= StepwisePanel.CONTENT_WIDTH - (inFirstRow || afresh ? 0 : CHIP_RETURN_MARGIN);
	}

	private static void setPart(JLabel part, boolean shown, Icon icon, String name, String text,
		Color tone, String tooltip)
	{
		part.setVisible(shown);
		if (!shown)
		{
			return;
		}
		if (part.getIcon() != icon)
		{
			part.setIcon(icon);
		}
		// Without the icon to say which figure this is, the text names it.
		part.setText(icon != null ? text : name + " " + text);
		part.setForeground(tone);
		if (!tooltip.equals(part.getToolTipText()))
		{
			part.setToolTipText(tooltip);
		}
	}

	/**
	 * The direction a count indicator shows: minus the behind count when anything is behind,
	 * else the ahead count. Behind wins because it is the one a player can act on.
	 */
	static int countDelta(int behind, int ahead)
	{
		return behind > 0 ? -behind : ahead;
	}

	/** "-2", "+5", or "0" when the player is level with the guide. */
	static String countText(int delta)
	{
		return delta == 0 ? "0" : (delta > 0 ? "+" : "-") + Math.abs(delta);
	}

	/** "+1.2M", "-120k", or "0" when the player's coins match the guide's plan. */
	static String gpText(long delta)
	{
		return delta == 0 ? "0" : RouteDeficitPanel.signed(delta);
	}

	/** "1.2M gp ahead of the guide", plus the skip offer when there is one. */
	static String gpTooltip(long delta, boolean skipOnOffer)
	{
		String reading = delta == 0
			? "Coins level with the guide"
			: RouteDeficitPanel.compact(Math.abs(delta)) + " gp "
				+ (delta > 0 ? "ahead of" : "behind") + " the guide";
		return skipOnOffer ? reading + ", enough to skip this money-making stretch" : reading;
	}

	/** "2 quests behind the guide, 5 ahead", leaving out a count of zero. */
	static String countsTooltip(String one, String many, int behind, int ahead)
	{
		if (behind == 0 && ahead == 0)
		{
			return Character.toUpperCase(many.charAt(0)) + many.substring(1)
				+ " level with the guide";
		}
		if (behind == 0)
		{
			return ahead + " " + (ahead == 1 ? one : many) + " ahead of the guide";
		}
		return behind + " " + (behind == 1 ? one : many) + " behind the guide"
			+ (ahead > 0 ? ", " + ahead + " ahead" : "");
	}

	/**
	 * The title line: the entry, plus "N of M" when the entry has several steps and
	 * the current one was found among them.
	 */
	static String titleOf(String entryId, int stepNumber, int stepCount)
	{
		return "Entry " + entryId
			// The count omits the word "step" so the longest titles fit beside the duration in
			// the bold header font.
			+ (stepNumber > 0 && stepCount > 1 ? " · " + stepNumber + " of " + stepCount : "");
	}

	/** Where the current step sits among its entry's steps. Runs only when the step changes. */
	private void countStep(StepwiseGuide guide)
	{
		stepNumber = 0;
		stepCount = 0;
		if (guide == null)
		{
			return;
		}
		Map<StepId, StepContext> contexts = guide.stepContextMap();
		for (GuideStep step : guide.allSteps())
		{
			StepContext context = contexts.get(step.getId());
			if (context == null || !entryId.equals(context.getEntryId()))
			{
				// An entry's steps are contiguous, so the first one past them ends the count.
				if (stepCount > 0)
				{
					break;
				}
				continue;
			}
			stepCount++;
			if (step.getId().getValue().equals(stepId))
			{
				stepNumber = stepCount;
			}
		}
	}

	private void toggle(Open chip)
	{
		open = open == chip ? Open.NONE : chip;
		applyOpen();
		updateRouteChip();
		revalidate();
		repaint();
	}

	private void applyOpen()
	{
		if (textBody.isVisible() != (open == Open.TEXT))
		{
			textBody.setVisible(open == Open.TEXT);
		}
		items.setOpen(open == Open.ITEMS);
		route.setOpen(open == Open.ROUTE);
		style(textChip, open == Open.TEXT);
		style(itemsChip, open == Open.ITEMS);
		// The route chip's indicators keep their own tones open or shut; its border and
		// background show it open.
		style(routeChip, open == Open.ROUTE);
	}

	private JLabel routePart()
	{
		JLabel part = PanelSections.smallLabel(" ", COLOR_CHIP_TEXT);
		part.setIconTextGap(2);
		part.setVisible(false);
		// A label with a tooltip takes the mouse events, so each one opens the chip itself.
		part.addMouseListener(PanelSections.clicks(() -> toggle(Open.ROUTE)));
		return part;
	}

	private static void style(JComponent chip, boolean isOpen)
	{
		PanelSections.styleChip(chip, isOpen, CHIP_OPEN, CHIP_SHUT, COLOR_CHIP_TEXT);
	}

	// --- Test seams ---

	Open openForTest()
	{
		return open;
	}

	/**
	 * How wide the wider of the two chip rows would be with these labels, in the panel's own
	 * font, with all three route indicators showing a blank icon of the chip's icon size.
	 */
	int chipRowWidthForTest(String text, String items, String gp, String skills, String quests)
	{
		textChip.setText(text);
		itemsChip.setText(items);
		textChip.setVisible(true);
		itemsChip.setVisible(true);
		Icon icon = new ImageIcon(new BufferedImage(CHIP_ICON_SIZE, CHIP_ICON_SIZE,
			BufferedImage.TYPE_INT_ARGB));
		setPart(gpPart, true, icon, "Coins", gp, COLOR_CHIP_TEXT, "");
		setPart(skillsPart, true, icon, "Skills", skills, COLOR_CHIP_TEXT, "");
		setPart(questsPart, true, icon, "Quests", quests, COLOR_CHIP_TEXT, "");
		gpPart.setBorder(PART_FIRST);
		skillsPart.setBorder(PART_NEXT);
		questsPart.setBorder(PART_NEXT);
		routeChip.setVisible(true);
		placeRouteChip();
		return Math.max(chipRow.getPreferredSize().width, routeRow.getPreferredSize().width);
	}

	/** Whether the route chip sits beside the other chips rather than on its own row. */
	boolean routeChipInFirstRowForTest()
	{
		return routeChip.getParent() == chipRow;
	}

	/** Moves to an entry that asks for nothing, so the Items chip is hidden. */
	void newEntryWithoutItemsForTest()
	{
		itemsChip.setVisible(false);
		placeAfresh = true;
		placeRouteChip();
	}

	/** The route chip's indicator texts, in order, for those showing. */
	List<String> routePartsForTest()
	{
		List<String> texts = new ArrayList<>();
		for (JLabel part : routeParts)
		{
			if (part.isVisible())
			{
				texts.add(part.getText());
			}
		}
		return texts;
	}

	/** Simulates a click on the chip. */
	void toggleForTest(Open chip)
	{
		toggle(chip);
	}

	/** How wide the title line would be with this title and duration, in their own fonts. */
	int titleRowWidthForTest(String titleText, String durationText)
	{
		title.setText(titleText);
		duration.setText(durationText);
		return titleRow.getInsets().left + title.getPreferredSize().width + TITLE_GAP
			+ duration.getPreferredSize().width;
	}

	String titleForTest()
	{
		return title.getText();
	}

	LinkedText textForTest()
	{
		return text;
	}
}

package com.stepwise.panel;

import com.stepwise.engine.CoreEngine;
import com.stepwise.guide.StepId;
import com.stepwise.snapshot.CompletionCriterion;
import com.stepwise.snapshot.DashboardSnapshot;
import com.stepwise.snapshot.DetailedStep;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.FontManager;

/**
 * Shows recently completed and skipped steps with Undo buttons, behind a collapsible
 * toggle label from {@link PanelSections#foldToggle}.
 */
public class HistoryPanel extends JPanel
{
	private static final Color COLOR_HEADER = PanelColors.HEADER;
	private static final Color COLOR_STEP = new Color(120, 180, 120);
	/** A skipped step: the muted label grey, so it does not read as done. */
	private static final Color COLOR_SKIPPED = PanelColors.HEADER;
	static final String DONE_MARK = "✓ ";
	/** Reads as "passed over". */
	static final String SKIPPED_MARK = "» ";

	private final JLabel toggle;
	private final JPanel contentPanel;
	private boolean expanded = false;
	/** Rebuilds the rows only when the steps listed change. */
	private final RebuildGuard guard = new RebuildGuard();
	private CoreEngine rowsEngine;
	private IconProvider rowsIconProvider;

	public HistoryPanel()
	{
		PanelSections.column(this);
		setBorder(PanelSections.gap(PanelSections.FOLD_GAP));

		contentPanel = new JPanel();
		contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
		contentPanel.setOpaque(false);
		contentPanel.setVisible(false);

		toggle = PanelSections.foldToggle("Recent");
		toggle.addMouseListener(PanelSections.clicks(() ->
		{
			expanded = !expanded;
			toggle.setText(PanelSections.foldText("Recent", expanded));
			contentPanel.setVisible(expanded);
			revalidate();
		}));
		add(toggle);
		add(contentPanel);

		setVisible(false);
	}

	/**
	 * Redraws the rows when the set of steps listed changes. Called on every snapshot: a
	 * Mark Done or Skip from the In Progress list changes the rows without moving the
	 * current step.
	 */
	public void rebuild(DashboardSnapshot snapshot, CoreEngine coreEngine, IconProvider iconProvider)
	{
		if (snapshot == null)
		{
			contentPanel.removeAll();
			guard.reset();
			setVisible(false);
			return;
		}
		setVisible(true);

		List<DetailedStep> recent = snapshot.getRecentCompleted();
		// Rows hold the engine their Undo acts on and icons from the provider, so a new one
		// of either redraws them.
		if (coreEngine != rowsEngine || iconProvider != rowsIconProvider)
		{
			guard.reset();
			rowsEngine = coreEngine;
			rowsIconProvider = iconProvider;
		}
		// A row shows its step's instruction and criteria icons, both fixed per step, and a
		// done or skipped mark, so the step ids and that mark are the whole structure.
		if (!guard.shouldRebuild(signature(recent)))
		{
			return;
		}
		contentPanel.removeAll();
		if (recent == null || recent.isEmpty())
		{
			contentPanel.add(PanelSections.smallLabel("No completed steps yet", COLOR_HEADER));
			contentPanel.revalidate();
			return;
		}

		JPanel container = PanelSections.box();

		for (int i = 0; i < recent.size(); i++)
		{
			if (i > 0)
			{
				container.add(PanelColors.divider());
			}
			container.add(buildHistoryRow(recent.get(i), coreEngine, iconProvider));
		}

		contentPanel.add(container);
		contentPanel.revalidate();
	}

	/** Each row's step id paired with whether it is skipped. */
	private static List<List<Object>> signature(List<DetailedStep> steps)
	{
		List<List<Object>> rows = new ArrayList<>();
		if (steps != null)
		{
			for (DetailedStep step : steps)
			{
				rows.add(List.of(step.getStepId(), step.isSkipped()));
			}
		}
		return rows;
	}

	private JPanel buildHistoryRow(DetailedStep step, CoreEngine coreEngine,
		IconProvider iconProvider)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));

		JPanel iconStrip = buildIconStrip(step.getCriteria(), iconProvider);
		if (iconStrip != null)
		{
			row.add(iconStrip, BorderLayout.WEST);
		}

		String text = step.getInstruction();
		if (text == null)
		{
			text = "";
		}

		JTextArea instrText = StepCardPanel.textArea(
			(step.isSkipped() ? SKIPPED_MARK : DONE_MARK) + text,
			step.isSkipped() ? COLOR_SKIPPED : COLOR_STEP, FontManager.getRunescapeSmallFont());
		instrText.setToolTipText(step.isSkipped() ? "Skipped" : null);
		row.add(instrText, BorderLayout.CENTER);

		if (coreEngine != null)
		{
			JButton undoBtn = StepCardPanel.smallButton(new JButton("Undo"));
			Dimension size = new Dimension(56, 20);
			undoBtn.setPreferredSize(size);
			undoBtn.setMinimumSize(size);
			undoBtn.setMaximumSize(size);
			undoBtn.addActionListener(e -> coreEngine.undoStep(new StepId(step.getStepId())));
			row.add(undoBtn, BorderLayout.EAST);
		}

		return row;
	}

	/** Returns a strip of the criteria's icons, or null when none resolve. */
	private static JPanel buildIconStrip(List<CompletionCriterion> criteria,
		IconProvider iconProvider)
	{
		if (criteria == null || criteria.isEmpty() || iconProvider == null)
		{
			return null;
		}

		JPanel strip = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
		strip.setOpaque(false);
		boolean hasIcon = false;

		for (CompletionCriterion c : criteria)
		{
			ImageIcon icon = iconProvider.getIcon(c.getIconType(), c.getIconKey(), false);
			if (icon != null)
			{
				strip.add(new JLabel(icon));
				hasIcon = true;
			}
		}

		return hasIcon ? strip : null;
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Resolves icon type + key pairs from CompletionCriterion into ImageIcons
 * for display in the side panel. Caches resolved icons to avoid repeated lookups.
 */
public class IconProvider
{
	private static final Logger log = LoggerFactory.getLogger(IconProvider.class);
	/** Size for icons on upcoming steps. */
	static final int SMALL_ICON_SIZE = 24;
	static final int TIMER_ICON_SIZE = 24;

	private static final int COINS_ITEM_ID = 995;
	private static final int COMBAT_ACHIEVEMENTS_ITEM_ID = 25956;

	private final SkillIconManager skillIconManager;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;

	private final Map<String, ImageIcon> cache = new ConcurrentHashMap<>();
	/**
	 * Interface sprites as decoded, keyed by the criterion icon type that shows them. They need
	 * the client thread, so {@link #loadSprites} fetches them and the panel reads them on the EDT.
	 */
	private final Map<String, BufferedImage> sprites = new ConcurrentHashMap<>();

	private volatile Color inventoryPanelColour;
	private volatile boolean inventoryPanelColourAsked;

	/** Callback to repaint the panel when an async item sprite finishes loading. */
	private volatile Runnable onImageLoaded;

	public IconProvider(SkillIconManager skillIconManager, ItemManager itemManager,
		SpriteManager spriteManager)
	{
		this.skillIconManager = skillIconManager;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
	}

	public void setOnImageLoaded(Runnable callback)
	{
		this.onImageLoaded = callback;
	}

	/**
	 * An item's sprite, fetched from the item manager. Every item lookup goes through here
	 * and {@link #spriteAsync}.
	 */
	protected AsyncBufferedImage itemImage(int itemId, int quantity, boolean stackable)
	{
		return itemManager.getImage(itemId, quantity, stackable);
	}

	/**
	 * A game interface sprite, delivered to the callback once the client has decoded it.
	 * Never delivered when there is no client to decode it, which every caller already
	 * treats as "not loaded yet".
	 */
	protected void spriteAsync(int spriteId, int file,
		Consumer<BufferedImage> callback)
	{
		if (spriteManager != null)
		{
			spriteManager.getSpriteAsync(spriteId, file, callback);
		}
	}

	/**
	 * Pre-fetches game sprites. Call from the client thread. The panel reads the results
	 * on the EDT.
	 */
	@SuppressWarnings("deprecation") // SpriteID — gameval equivalent uses unreadable Jagex names
	public void loadSprites()
	{
		loadSprite("quest", SpriteID.TAB_QUESTS);
		loadSprite("diary", SpriteID.TAB_QUESTS_GREEN_ACHIEVEMENT_DIARIES);
		loadSprite("skills", SpriteID.TAB_STATS);
		loadSprite("hasItem", SpriteID.TAB_INVENTORY);
		loadSprite("location", SpriteID.MINIMAP_ORB_WORLD_MAP_PLANET);
	}

	private void loadSprite(String iconType, int spriteId)
	{
		if (!sprites.containsKey(iconType))
		{
			spriteAsync(spriteId, 0, img ->
			{
				if (img != null)
				{
					sprites.put(iconType, img);
				}
			});
		}
	}

	/** Runs the repaint hook, if one is set. EDT only. */
	private void repaint()
	{
		Runnable repaint = onImageLoaded;
		if (repaint != null)
		{
			repaint.run();
		}
	}

	/**
	 * The colour of the game's inventory panel, or null until the sprite has loaded.
	 *
	 * <p>Null is the normal first answer. The caller falls back to the flat container
	 * colour, and the repaint hook brings the real colour in once it lands.
	 *
	 * <p>Call <b>from the EDT</b> only. The asked flag is a plain check-then-set, so a
	 * caller on another thread could trigger a second fetch. On a {@code SpriteManager}
	 * cache hit the callback runs inline, so the averaging can run on the EDT inside a paint.
	 */
	public Color getInventoryPanelColour()
	{
		if (inventoryPanelColour != null)
		{
			return inventoryPanelColour;
		}
		if (!inventoryPanelColourAsked)
		{
			inventoryPanelColourAsked = true;
			spriteAsync(net.runelite.api.gameval.SpriteID.SIDE_BACKGROUND, 0, img ->
			{
				if (img == null)
				{
					return;
				}
				Color average = averageOfMiddle(img);
				if (average == null)
				{
					log.debug("Inventory panel sprite had no opaque middle to average");
					return;
				}
				SwingUtilities.invokeLater(() ->
				{
					inventoryPanelColour = average;
					repaint();
				});
			});
		}
		return null;
	}

	/**
	 * The mean colour of a sprite's middle, ignoring the outer quarter on every side.
	 *
	 * <p>The edges hold the panel's bevel decoration, which would skew the average.
	 * Mostly-transparent pixels are skipped so cut-away areas do not darken the result.
	 * Returns null when nothing in the middle is opaque.
	 */
	static Color averageOfMiddle(BufferedImage sprite)
	{
		int insetX = sprite.getWidth() / 4;
		int insetY = sprite.getHeight() / 4;
		long red = 0;
		long green = 0;
		long blue = 0;
		long counted = 0;
		for (int y = insetY; y < sprite.getHeight() - insetY; y++)
		{
			for (int x = insetX; x < sprite.getWidth() - insetX; x++)
			{
				int argb = sprite.getRGB(x, y);
				if ((argb >>> 24) < 128)
				{
					continue;
				}
				red += (argb >> 16) & 0xFF;
				green += (argb >> 8) & 0xFF;
				blue += argb & 0xFF;
				counted++;
			}
		}
		if (counted == 0)
		{
			return null;
		}
		return new Color((int) (red / counted), (int) (green / counted),
			(int) (blue / counted));
	}

	/**
	 * A skill's tab icon at a caller-chosen size.
	 *
	 * @param skillName the guide's spelling of the skill, matched case-insensitively
	 * @param size      width and height in pixels
	 * @return the icon, or null when the name is not one of the game's skills
	 */
	public ImageIcon getSkillIcon(String skillName, int size)
	{
		if (skillName == null)
		{
			return null;
		}

		String cacheKey = "skill:" + skillName.toLowerCase(java.util.Locale.ROOT) + ":" + size;
		ImageIcon cached = cache.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}

		for (Skill skill : Skill.values())
		{
			if (!skill.getName().equalsIgnoreCase(skillName))
			{
				continue;
			}
			BufferedImage img = skillIconManager.getSkillImage(skill, true);
			if (img == null)
			{
				return null;
			}
			ImageIcon icon = new ImageIcon(ImageUtil.resizeImage(img, size, size));
			cache.put(cacheKey, icon);
			return icon;
		}
		return null;
	}

	/**
	 * The quest tab's icon at a caller-chosen size, or null until {@link #loadSprites} has
	 * fetched it.
	 *
	 * @param size width and height in pixels
	 */
	public ImageIcon getQuestIcon(int size)
	{
		return resizedTab("quest", size);
	}

	/**
	 * The achievement diary tab's icon at a caller-chosen size, or null until
	 * {@link #loadSprites} has fetched it.
	 *
	 * @param size width and height in pixels
	 */
	public ImageIcon getDiaryIcon(int size)
	{
		return resizedTab("diary", size);
	}

	/**
	 * The stats tab's icon at a caller-chosen size, or null until {@link #loadSprites} has
	 * fetched it.
	 *
	 * @param size width and height in pixels
	 */
	public ImageIcon getSkillsIcon(int size)
	{
		return resizedTab("skills", size);
	}

	private ImageIcon resizedTab(String iconType, int size)
	{
		BufferedImage sprite = sprites.get(iconType);
		if (sprite == null)
		{
			return null;
		}
		return cache.computeIfAbsent("tab:" + iconType + ":" + size,
			k -> new ImageIcon(ImageUtil.resizeImage(sprite, size, size)));
	}

	/**
	 * A coin stack at a caller-chosen size, drawn as the large pile. Handed out blank at full
	 * size and filled in place on load: the panel rebuilds a row only when its content
	 * changes, so it never asks again for an icon that was missing at rebuild time.
	 *
	 * @param size width and height in pixels
	 */
	public ImageIcon getCoinsIcon(int size)
	{
		// Quantity 10000 selects the large stack sprite.
		return sizedItemIcon("coins:" + size, size, () -> itemImage(COINS_ITEM_ID, 10000, false));
	}

	/**
	 * An item's sprite at a caller-chosen size, handed out blank at that size and filled in
	 * place on load, for the same reason as {@link #getCoinsIcon(int)}.
	 *
	 * @param size width and height in pixels
	 */
	public ImageIcon getItemIcon(int itemId, int size)
	{
		return sizedItemIcon("item:" + itemId + ":" + size, size, () -> itemImage(itemId, 1, false));
	}

	private ImageIcon sizedItemIcon(String cacheKey, int size, Supplier<AsyncBufferedImage> sprite)
	{
		ImageIcon cached = cache.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}
		try
		{
			ImageIcon icon = resizedOnLoad(sprite.get(), size);
			cache.put(cacheKey, icon);
			return icon;
		}
		catch (Exception e)
		{
			log.debug("Failed to load icon {}", cacheKey, e);
			return null;
		}
	}

	/**
	 * Resolves an icon from type + key, or null for an unknown type.
	 *
	 * @param iconType "skill", "item", "gp", "quest", "diary", "combat_achievement",
	 *                 "location", "hasItem" or "skills"
	 * @param iconKey  skill name for skills, item ID or coin quantity string, null otherwise
	 * @param active   true for the current step, false for upcoming. Item and coin icons keep
	 *                 their natural size on the current step and are capped at 24px on
	 *                 upcoming ones; skill and sprite icons are 24px either way.
	 */
	public ImageIcon getIcon(String iconType, String iconKey, boolean active)
	{
		if (iconType == null)
		{
			return null;
		}

		String cacheKey = iconType + ":" + iconKey + ":" + (active ? "lg" : "sm");
		ImageIcon cached = cache.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}

		ImageIcon icon = resolve(iconType, iconKey, active);
		if (icon == null)
		{
			return null;
		}
		// An active item icon wraps the AsyncBufferedImage directly, so its pixels fill in
		// place and only need a repaint. A shrunk inactive icon repaints itself via
		// resizedOnLoad.
		cache.put(cacheKey, icon);
		registerAsyncRepaint(icon);
		return icon;
	}

	/**
	 * The same sprite the inventory draws for a stack of this size, at the size the game draws
	 * it, drained of colour when the player has not got it.
	 *
	 * <p>Unresized on purpose: a grid drawn as an inventory should hold the same 36×32
	 * sprites the inventory does.
	 *
	 * @param quantity how many, which changes the sprite for anything stackable
	 * @param held     false to render in greyscale
	 */
	public ImageIcon getInventoryIcon(int itemId, int quantity, boolean held)
	{
		int stack = Math.max(1, quantity);
		String cacheKey = "inv:" + itemId + ":" + stack + ":" + held;
		ImageIcon cached = cache.get(cacheKey);
		if (cached != null)
		{
			return cached;
		}

		AsyncBufferedImage sprite;
		try
		{
			// A non-stackable item ignores the stackable flag and draws a single sprite.
			sprite = itemImage(itemId, stack, stack > 1);
		}
		catch (Exception e)
		{
			log.debug("Failed to load inventory icon for item {}", itemId, e);
			return null;
		}
		if (sprite == null)
		{
			return null;
		}

		// A held item wraps the async image as-is. Greying waits for the pixels and
		// restyles the same instance, since labels already hold it.
		ImageIcon icon = new ImageIcon(sprite);
		cache.put(cacheKey, icon);
		if (held)
		{
			registerAsyncRepaint(icon);
		}
		else
		{
			sprite.onLoaded(() -> SwingUtilities.invokeLater(() ->
			{
				icon.setImage(ImageUtil.grayscaleImage(sprite));
				repaint();
			}));
		}
		return icon;
	}

	/**
	 * A blank icon at its final size, filled in place once the sprite's pixels load.
	 *
	 * <p>Handing out the full-size sprite meanwhile would lay rows out around a 36x32 icon
	 * and clip fixed-height rows. The load fires only a repaint, never a revalidate, so the
	 * icon's size must not change on arrival. An already-loaded sprite still fills a client
	 * tick later, because {@code AsyncBufferedImage} cannot report whether it has loaded.
	 */
	private ImageIcon resizedOnLoad(AsyncBufferedImage async, int size)
	{
		ImageIcon sized = new ImageIcon(new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB));
		async.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			sized.setImage(ImageUtil.resizeImage(async, size, size));
			repaint();
		}));
		return sized;
	}

	private void registerAsyncRepaint(ImageIcon icon)
	{
		if (icon.getImage() instanceof AsyncBufferedImage)
		{
			((AsyncBufferedImage) icon.getImage()).onLoaded(() ->
				SwingUtilities.invokeLater(this::repaint));
		}
	}

	private ImageIcon resolve(String iconType, String iconKey, boolean active)
	{
		try
		{
			ImageIcon icon;
			switch (iconType)
			{
				case "skill":
					return getSkillIcon(iconKey, SMALL_ICON_SIZE);
				case "item":
					icon = new ImageIcon(itemImage(Integer.parseInt(iconKey), 1, false));
					break;
				case "gp":
					// The inactive icon is the large pile. Active, OSRS draws different coin
					// sprites at 1, 2, 3, 4, 5, 25, 100, 250, 1000 and 10000+, and ItemManager
					// picks the one for the quantity.
					icon = new ImageIcon(active
						? itemImage(COINS_ITEM_ID, coinQuantity(iconKey), true)
						: itemImage(COINS_ITEM_ID, 10000, false));
					break;
				case "combat_achievement":
					icon = new ImageIcon(itemImage(COMBAT_ACHIEVEMENTS_ITEM_ID, 1, false));
					break;
				case "quest":
				case "diary":
				case "location":
				case "hasItem":
				case "skills":
					BufferedImage sprite = sprites.get(iconType);
					return sprite != null ? new ImageIcon(
						ImageUtil.resizeImage(sprite, SMALL_ICON_SIZE, SMALL_ICON_SIZE)) : null;
				default:
					return null;
			}
			if (!active && (icon.getIconWidth() > SMALL_ICON_SIZE
				|| icon.getIconHeight() > SMALL_ICON_SIZE))
			{
				icon = resizedOnLoad((AsyncBufferedImage) icon.getImage(), SMALL_ICON_SIZE);
			}
			return icon;
		}
		catch (Exception e)
		{
			log.debug("Failed to resolve icon type={} key={}", iconType, iconKey, e);
			return null;
		}
	}

	/** A coin criterion's quantity, or a single coin when the key is not a number. */
	private static int coinQuantity(String key)
	{
		try
		{
			return key != null ? Integer.parseInt(key) : 1;
		}
		catch (NumberFormatException e)
		{
			return 1;
		}
	}
}

package com.stepwise.panel;

import com.stepwise.engine.CoreEngine;
import com.stepwise.snapshot.DashboardSnapshot;
import com.stepwise.snapshot.DetailedStep;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;

/**
 * Shows the steps the resolver marks {@code BACKGROUND}: long skill grinds, recurring
 * activities and crop-growth waits that run alongside the current step.
 *
 * <p>The upcoming list excludes these steps, so this section is the only place the player
 * sees them, their progress, their guidance and a Mark Done for them. The last two sit in
 * each card's Details fold (see {@link StepCardPanel#inProgress}).
 */
public class InProgressPanel extends JPanel
{
	private static final Color COLOR_OCCASION = new Color(200, 180, 120);

	/** Tracked cards for in-place criteria updates on same-structure refreshes. */
	private final List<StepCardPanel> trackedCards = new ArrayList<>();
	/** Rebuilds the list only when its structure changes. */
	private final RebuildGuard guard = new RebuildGuard();
	/**
	 * Steps whose Details fold the player opened. Folds start shut, and a structural rebuild
	 * (a step joining or leaving the list) recreates every card, so the open ones are
	 * remembered by step id and rebuilt open.
	 */
	private final Set<String> expandedStepIds = new HashSet<>();

	public InProgressPanel()
	{
		PanelSections.column(this);
	}

	public void rebuild(DashboardSnapshot snapshot, CoreEngine coreEngine, IconProvider iconProvider)
	{
		if (snapshot == null)
		{
			removeAll();
			trackedCards.clear();
			guard.reset();
			// No snapshot means logout or a reset; the next account's steps start shut.
			expandedStepIds.clear();
			setVisible(false);
			return;
		}

		List<DetailedStep> background = snapshot.getBackgroundSteps();
		if (background == null)
		{
			background = List.of();
		}

		// Progress (skill XP, contract counts) changes constantly and updates in place.
		// Keep it out of the signature, or every XP drop rebuilds the cards and they flicker.
		if (!guard.shouldRebuild(structureSignature(background)))
		{
			for (int i = 0; i < trackedCards.size(); i++)
			{
				trackedCards.get(i).updateCriteria(background.get(i).getCriteria());
			}
			return;
		}

		removeAll();
		trackedCards.clear();
		// A step that left the list will not be back open; forget it so the set stays small.
		expandedStepIds.retainAll(stepIds(background));

		if (background.isEmpty())
		{
			setVisible(false);
			revalidate();
			repaint();
			return;
		}
		setVisible(true);

		setBorder(PanelSections.gap(PanelSections.SECTION_GAP));
		add(PanelSections.header("In Progress"));

		JPanel container = PanelSections.box();

		// The snapshot arrives grouped by occasion; print one heading per group, so rows done on
		// the same trip read as one batch. Steps with no occasion form one unlabelled group.
		boolean needsDivider = false;
		String openGroup = null;
		boolean firstGroup = true;

		for (DetailedStep step : background)
		{
			String occasion = step.getWhen();
			if (firstGroup || !Objects.equals(occasion, openGroup))
			{
				if (needsDivider)
				{
					container.add(PanelColors.divider());
					needsDivider = false;
				}
				if (occasion != null)
				{
					container.add(groupHeader(occasion, firstGroup));
				}
				openGroup = occasion;
				firstGroup = false;
			}

			if (needsDivider)
			{
				container.add(PanelColors.divider());
			}

			// No per-card eyebrow: the group header already names the occasion.
			String stepId = step.getStepId();
			StepCardPanel card = StepCardPanel.inProgress(coreEngine, stepId, step.getInstruction(),
				step.getGuidance(), step.getCriteria(), step.isCompletedByClick(),
				!expandedStepIds.contains(stepId), collapsed -> rememberDetails(stepId, collapsed),
				iconProvider);
			card.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 4));
			card.setBackground(PanelColors.CONTAINER_BG);
			card.presize(getWidth());
			container.add(card);
			trackedCards.add(card);
			needsDivider = true;
		}

		add(container);

		revalidate();
		repaint();
	}

	private void rememberDetails(String stepId, boolean collapsed)
	{
		if (collapsed)
		{
			expandedStepIds.remove(stepId);
		}
		else
		{
			expandedStepIds.add(stepId);
		}
	}

	private static Set<String> stepIds(List<DetailedStep> steps)
	{
		Set<String> ids = new HashSet<>();
		for (DetailedStep step : steps)
		{
			ids.add(step.getStepId());
		}
		return ids;
	}

	/** Test seam: the cards built by the last structural rebuild, in list order. */
	List<StepCardPanel> getCardsForTest()
	{
		return trackedCards;
	}

	/**
	 * Occasion heading above a run of cards that share a {@code when}.
	 *
	 * @param first whether this is the topmost group, which needs no separating space above it
	 */
	private static JLabel groupHeader(String occasion, boolean first)
	{
		JLabel label = PanelSections.smallLabel(occasion, COLOR_OCCASION);
		label.setAlignmentX(LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(first ? 5 : 7, 6, 2, 4));
		return label;
	}

	/**
	 * Structural signature keyed by step ID and occasion. The occasion decides where group
	 * headings fall, so a changed occasion forces a rebuild even when the steps are unchanged.
	 */
	private static List<String> structureSignature(List<DetailedStep> background)
	{
		List<String> sig = new ArrayList<>();
		for (DetailedStep step : background)
		{
			sig.add("b:" + step.getStepId() + "@" + step.getWhen());
		}
		return sig;
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.LayoutManager;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * The colour of the game's inventory panel, painted behind the slots of an item grid.
 *
 * <p>Only slot cells are filled. The gaps between them keep the tab's own background.
 *
 * <p>A flat colour, not the sprite: the inventory sprite carries a bevel and shading that
 * show up as artifacts when tiled or scaled into a sidebar grid. The colour still comes from
 * the sprite so it follows any change the game makes.
 */
class InventoryBackdrop extends JPanel
{
	/**
	 * Client-property key marking a child as a slot rather than a blank padding out a row.
	 * Blanks stay unfilled.
	 *
	 * <p>Stored on the child, not in a side list, so removing a child can never leave a stale
	 * entry that paints a rectangle where it used to be.
	 */
	private static final String SLOT = "stepwise.inventorySlot";

	private IconProvider icons;

	InventoryBackdrop(LayoutManager layout)
	{
		super(layout);
		// Transparent: paintComponent fills only the slots.
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	/**
	 * Sets the colour source on each rebuild. Not a constructor argument because some grids
	 * are built before {@code StepwisePlugin.startUp} creates the {@link IconProvider}.
	 */
	void setIcons(IconProvider icons)
	{
		this.icons = icons;
	}

	/** Adds a cell that should have the game's panel colour behind it. */
	void addSlot(JComponent slot)
	{
		slot.putClientProperty(SLOT, Boolean.TRUE);
		add(slot);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Color panel = icons == null ? null : icons.getInventoryPanelColour();
		// Fallback until the sprite loads (every first paint of a session).
		g.setColor(panel == null ? PanelColors.CONTAINER_BG : panel);
		// Reads x/y/width/height directly: getBounds() allocates a Rectangle per child, and
		// this runs on every snapshot's repaint.
		for (int i = 0, count = getComponentCount(); i < count; i++)
		{
			Component child = getComponent(i);
			if (!(child instanceof JComponent)
				|| ((JComponent) child).getClientProperty(SLOT) == null)
			{
				continue;
			}
			int width = child.getWidth();
			int height = child.getHeight();
			if (width > 0 && height > 0)
			{
				g.fillRect(child.getX(), child.getY(), width, height);
			}
		}
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Graphics;
import javax.swing.ImageIcon;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * One inventory square: a sprite and its stack count.
 *
 * <p>Painted by hand because a Swing label puts its text beside the icon, and the count
 * belongs on top of the sprite.
 */
class ItemSquare extends JPanel
{
	/**
	 * An item sprite (36×32) plus a margin. Sprites draw at full size because shrunken seed
	 * sprites are hard to tell apart.
	 */
	static final int SIZE = 42;
	static final int GAP = 3;

	/** The game's own stack-count colour. */
	private static final Color COLOR_COUNT = Color.YELLOW;

	private final ImageIcon sprite;
	private final String count;

	ItemSquare(ImageIcon sprite, String count)
	{
		this.sprite = sprite;
		this.count = count;
		// Transparent so the InventoryBackdrop slot colour shows through.
		setOpaque(false);
		setFont(FontManager.getRunescapeSmallFont());
	}

	String getCountForTest()
	{
		return count;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (sprite != null)
		{
			sprite.paintIcon(this, g,
				(getWidth() - sprite.getIconWidth()) / 2,
				(getHeight() - sprite.getIconHeight()) / 2);
		}
		if (count != null)
		{
			g.setFont(getFont());
			g.setColor(COLOR_COUNT);
			g.drawString(count, 3, g.getFontMetrics().getAscent() + 1);
		}
	}
}

package com.stepwise.panel;

import com.stepwise.snapshot.ItemNeededStatus;
import com.stepwise.snapshot.ItemNeededStatus.Ownership;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The active entry's items-needed list, drawn as an inventory-style sprite grid coloured
 * by whether the player is carrying each item, has it banked, is missing it, or the plugin
 * cannot yet say. {@link EntryBlock}'s Items chip opens and shuts it.
 *
 * <p>Lays its {@link ItemSquare} cells over an {@link InventoryBackdrop}, four wide like the
 * game's inventory. {@link Ownership#UNKNOWN} covers a bank never opened, or cleared since.
 */
class ItemsNeededView extends JPanel
{
	/** The game inventory's width. */
	private static final int COLUMNS = 4;
	private static final int SQUARE = ItemSquare.SIZE;
	private static final int GAP = ItemSquare.GAP;
	/** Muted, for the line naming items the grid cannot draw. */
	private static final Color COLOR_UNRESOLVED = new Color(130, 130, 130);

	// Shared instances: recolor() runs every tick, and setBorder repaints whenever the
	// instance differs, even if it draws identically. These borders hold no per-component state.
	private static final Border BORDER_CARRIED =
		BorderFactory.createLineBorder(ColorScheme.PROGRESS_COMPLETE_COLOR);
	private static final Border BORDER_BANKED =
		BorderFactory.createLineBorder(ColorScheme.BRAND_ORANGE);
	private static final Border BORDER_NONE = BorderFactory.createEmptyBorder(1, 1, 1, 1);

	/** Holds the grid and the unresolved line, shown while the view is open. */
	private final JPanel content = PanelSections.column();
	private final InventoryBackdrop grid;
	/** Rows that name no single item, comma-joined. Wraps, so it is never recreated. */
	private final JTextArea unresolved;
	private final RebuildGuard guard = new RebuildGuard();

	/** The squares on screen, in list order, so a border-only change recolours in place. */
	private List<ItemSquare> squares = Collections.emptyList();

	/** Listed items in the grid and the unresolved line combined. */
	private int shownCount;

	ItemsNeededView()
	{
		PanelSections.column(this);

		grid = new InventoryBackdrop(null);
		grid.setBorder(BorderFactory.createEmptyBorder(2, 4, 4, 0));
		grid.setAlignmentX(LEFT_ALIGNMENT);

		unresolved = StepCardPanel.textArea("", COLOR_UNRESOLVED, FontManager.getRunescapeSmallFont());
		unresolved.setVisible(false);

		content.add(grid);
		content.add(unresolved);
		content.setVisible(false);

		add(content);
		setVisible(false);
	}

	/**
	 * Redraws the grid. Called every tick, because ownership can flip mid-entry. The
	 * {@link RebuildGuard} rebuilds on a new entry, a changed row (text, item or quantity) or a
	 * MISSING↔held flip; other changes recolour in place.
	 *
	 * @param entryId the active entry id, so a new entry rebuilds even with the same rows
	 */
	void rebuild(String entryId, List<ItemNeededStatus> items, IconProvider icons)
	{
		List<ItemNeededStatus> kept = displayable(items);
		if (kept.isEmpty())
		{
			setVisible(false);
			squares = Collections.emptyList();
			guard.reset();
			return;
		}
		// Anti-flicker: every mutation below is gated on an actual change, and the layout
		// pass runs only if one happened. Re-setting identical text on the wrapping
		// unresolved line would re-measure it and make the height oscillate.
		boolean changed = false;
		if (!isVisible())
		{
			setVisible(true);
			changed = true;
		}
		grid.setIcons(icons);

		List<ItemNeededStatus> resolved = new ArrayList<>(kept.size());
		List<String> unresolvedLines = new ArrayList<>();
		for (ItemNeededStatus item : kept)
		{
			if (item.getItemId() > 0)
			{
				resolved.add(item);
			}
			else
			{
				unresolvedLines.add(item.getText());
			}
		}

		shownCount = kept.size();

		if (guard.shouldRebuild(signature(entryId, kept)))
		{
			rebuildGrid(resolved, icons);
			changed = true;
		}
		else
		{
			recolor(resolved);
		}

		boolean gridVisible = !resolved.isEmpty();
		if (grid.isVisible() != gridVisible)
		{
			grid.setVisible(gridVisible);
			changed = true;
		}
		String line = String.join(", ", unresolvedLines);
		if (!line.equals(unresolved.getText()))
		{
			unresolved.setText(line);
			changed = true;
		}
		boolean lineVisible = !unresolvedLines.isEmpty();
		if (unresolved.isVisible() != lineVisible)
		{
			unresolved.setVisible(lineVisible);
			changed = true;
		}

		if (changed)
		{
			revalidate();
			repaint();
		}
	}

	/** The rows with text to show. */
	private static List<ItemNeededStatus> displayable(List<ItemNeededStatus> items)
	{
		if (items == null || items.isEmpty())
		{
			return Collections.emptyList();
		}
		List<ItemNeededStatus> kept = new ArrayList<>(items.size());
		for (ItemNeededStatus item : items)
		{
			if (item != null && item.getText() != null)
			{
				kept.add(item);
			}
		}
		return kept;
	}

	/** Structural signature: the entry, plus each row's identity and whether it is held.
	 *  Full ownership is excluded because a BANKED↔CARRIED flip changes only the border,
	 *  which {@link #recolor} handles. */
	private static List<String> signature(String entryId, List<ItemNeededStatus> items)
	{
		List<String> sig = new ArrayList<>(items.size() + 1);
		sig.add(entryId);
		for (ItemNeededStatus item : items)
		{
			boolean held = item.getOwnership() != Ownership.MISSING;
			sig.add(item.getText() + "|" + item.getItemId() + "|" + item.getQuantity() + "|" + held);
		}
		return sig;
	}

	/** Full rebuild of the grid. */
	private void rebuildGrid(List<ItemNeededStatus> resolved, IconProvider icons)
	{
		grid.removeAll();
		int n = resolved.size();
		if (n == 0)
		{
			squares = Collections.emptyList();
			return;
		}

		int rows = (n + COLUMNS - 1) / COLUMNS;
		grid.setLayout(new GridLayout(rows, COLUMNS, GAP, GAP));
		// Capped, or GridLayout stretches each square to a quarter of the sidebar.
		Dimension size = new Dimension(
			COLUMNS * SQUARE + (COLUMNS - 1) * GAP + 4,
			rows * SQUARE + (rows - 1) * GAP + 6);
		grid.setMaximumSize(size);
		grid.setPreferredSize(size);

		List<ItemSquare> built = new ArrayList<>(n);
		for (ItemNeededStatus item : resolved)
		{
			ItemSquare cell = square(item, icons);
			grid.addSlot(cell);
			built.add(cell);
		}
		// Trailing cells are blank, not empty slots, which would read as "room for more".
		for (int i = n; i < rows * COLUMNS; i++)
		{
			grid.add(gap());
		}
		squares = built;
	}

	/** A blank, sprite-sized cell for the grid's trailing slots. */
	private static JPanel gap()
	{
		JPanel cell = new JPanel();
		cell.setOpaque(false);
		cell.setPreferredSize(new Dimension(SQUARE, SQUARE));
		return cell;
	}

	private void recolor(List<ItemNeededStatus> resolved)
	{
		int n = Math.min(resolved.size(), squares.size());
		for (int i = 0; i < n; i++)
		{
			applyBorder(squares.get(i), resolved.get(i).getOwnership());
		}
	}

	private static ItemSquare square(ItemNeededStatus item, IconProvider icons)
	{
		boolean held = item.getOwnership() != Ownership.MISSING;
		ImageIcon sprite = icons != null && item.getItemId() > 0
			? icons.getInventoryIcon(item.getItemId(), Math.max(1, item.getQuantity()), held)
			: null;
		// A stack sprite already draws its count. Only an exact quantity of one gets a badge;
		// an absent quantity gets none.
		ItemSquare cell = new ItemSquare(sprite, item.getQuantity() == 1 ? "1" : null);
		cell.setPreferredSize(new Dimension(SQUARE, SQUARE));
		cell.setMinimumSize(new Dimension(SQUARE, SQUARE));
		cell.setToolTipText(item.getText());
		applyBorder(cell, item.getOwnership());
		return cell;
	}

	/** Green when carried, orange when banked, no border otherwise. MISSING gets no warning
	 *  because a correctly-run entry consumes items as it goes. */
	private static void applyBorder(ItemSquare cell, Ownership ownership)
	{
		switch (ownership)
		{
			case CARRIED:
				cell.setBorder(BORDER_CARRIED);
				break;
			case BANKED:
				cell.setBorder(BORDER_BANKED);
				break;
			case MISSING:
			case UNKNOWN:
			default:
				cell.setBorder(BORDER_NONE);
				break;
		}
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	// --- Opened by the entry block's Items chip ---

	/** Opens or shuts the view. Shut, it takes no height. Only a change relays out. */
	void setOpen(boolean open)
	{
		if (content.isVisible() != open)
		{
			content.setVisible(open);
			revalidate();
		}
	}

	/** Whether there is an items-needed list to show. */
	boolean hasItems()
	{
		return isVisible();
	}

	/** Listed items in the grid and the unresolved line combined. */
	int itemCount()
	{
		return shownCount;
	}

	// --- Test seams ---

	List<ItemSquare> getSquaresForTest()
	{
		return squares;
	}

	JTextArea getUnresolvedForTest()
	{
		return unresolved;
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.util.ArrayList;
import java.util.List;
import javax.swing.Box;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * Guide text with its links, for the step card's guidance and the entry block's source text.
 * The author picks how a link shows by where they put it:
 *
 * <ul>
 *   <li>Links that end the text, apart only by whitespace ({@link MarkdownLinks#splitTrailing}),
 *       are lifted into rows of their own beneath it, one {@code ↗ label} per link.</li>
 *   <li>Every other link stays in the sentence, drawn inline by {@link LinkedTextPane}.</li>
 * </ul>
 *
 * <p>Set the text only when it changes ({@link #setMarkdown}): it rebuilds the rows and the
 * document, and a rebuilt wrapping component re-wraps (see {@link RebuildGuard}).
 */
class LinkedText extends JPanel
{
	/** Space above each trailing row. */
	private static final int ROW_GAP = 2;

	private final LinkedTextPane body;

	/**
	 * @param colour the colour of the body text
	 * @param font the body text's font; trailing rows use the small RuneScape font
	 */
	LinkedText(Color colour, Font font)
	{
		PanelSections.column(this);
		body = new LinkedTextPane(colour, font);
		add(body);
	}

	/**
	 * Replaces the text and its links. Call only when the text changes.
	 *
	 * @param markdown the text, with {@code [label](url)} links; null reads as empty
	 * @param inlineMarkup whether {@link TextMarkup} bold, italic and strikethrough apply to the
	 *     body. False for source text, whose asterisks are literal.
	 */
	void setMarkdown(String markdown, boolean inlineMarkup)
	{
		MarkdownLinks.Split split = MarkdownLinks.splitTrailing(markdown);
		body.setMarkdown(split.body, inlineMarkup);
		body.setVisible(!split.body.isEmpty());

		// The body is the first child; everything after it belongs to the trailing rows.
		while (getComponentCount() > 1)
		{
			remove(getComponentCount() - 1);
		}
		for (String[] link : split.trailing)
		{
			add(Box.createVerticalStrut(ROW_GAP));
			JTextArea row = link("↗ " + link[0], link[1]);
			row.setToolTipText(link[1]);
			add(row);
		}
		revalidate();
	}

	// --- Test seams ---

	/** The body text as it reads, inline links shown as their labels. */
	String bodyTextForTest()
	{
		return body.plainText();
	}

	LinkedTextPane bodyForTest()
	{
		return body;
	}

	/** The trailing rows' text, in order. */
	List<String> rowTextsForTest()
	{
		List<String> texts = new ArrayList<>();
		for (int i = 0; i < getComponentCount(); i++)
		{
			if (getComponent(i) instanceof JTextArea)
			{
				texts.add(((JTextArea) getComponent(i)).getText());
			}
		}
		return texts;
	}

	@Override
	public Dimension getMaximumSize()
	{
		// Never taller than its content, so a BoxLayout parent cannot pad it with spare height.
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/** Wrapping link text in small type: a hand cursor over it, and a click opens {@code url}. */
	static JTextArea link(String text, String url)
	{
		JTextArea link = StepCardPanel.textArea(text, PanelColors.LINK,
			FontManager.getRunescapeSmallFont());
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		// LinkBrowser.browse hands a URL to the browser. Its sibling open is for directories
		// (Desktop.open on a File) and fails on a URL wherever xdg-open is missing.
		link.addMouseListener(PanelSections.clicks(() -> LinkBrowser.browse(url)));
		return link;
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Rectangle2D;
import javax.swing.BorderFactory;
import javax.swing.JTextPane;
import javax.swing.ToolTipManager;
import javax.swing.text.AbstractDocument;
import javax.swing.text.BadLocationException;
import javax.swing.text.BoxView;
import javax.swing.text.ComponentView;
import javax.swing.text.IconView;
import javax.swing.text.LabelView;
import javax.swing.text.ParagraphView;
import javax.swing.text.SimpleAttributeSet;
import javax.swing.text.StyleConstants;
import javax.swing.text.StyledDocument;
import javax.swing.text.StyledEditorKit;
import javax.swing.text.View;
import javax.swing.text.ViewFactory;
import net.runelite.client.util.LinkBrowser;

/**
 * Wrapping panel text with inline {@code [label](url)} links: each link reads as its label, in
 * {@link PanelColors#LINK} and underlined, where the source put it in the sentence. A click on a
 * label opens it, the cursor is a hand over one, and its tooltip is the URL.
 *
 * <p>Shared by the step card's guidance and the entry block's source text. Not a JTextArea: a
 * JTextArea has one foreground colour, and a Highlighter painter draws beneath the glyphs, so a
 * label could be underlined there but never coloured; and guidance needs {@link TextMarkup}
 * bold and italic, which only a styled document can show. Not HTML either: a JLabel's CSS
 * widths do not match the panel's pixel width.
 *
 * <p>A JTextPane tracks its parent's width only as the direct view of a JScrollPane viewport.
 * Inside a BoxLayout it would take its one-line preferred width and overflow instead of
 * wrapping; clamping {@link #getMaximumSize()} to the laid-out width keeps it at the
 * container's width, so it wraps like a JTextArea.
 *
 * <p>Like every panel text component it is neither editable nor focusable, so nothing can be
 * selected. A refresh that does not change the text must not call {@link #setMarkdown}: the
 * document rebuild re-wraps the text (see {@link RebuildGuard}).
 */
class LinkedTextPane extends JTextPane
{
	private static final Color COLOR_LINK = PanelColors.LINK;
	private static final Cursor HAND = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);
	private static final Cursor DEFAULT = Cursor.getDefaultCursor();

	private final Color colour;
	private final Font font;
	private MarkdownLinks.Parsed parsed = MarkdownLinks.parse(null, false);

	/**
	 * @param colour the colour of the text around the links
	 * @param font the text's font; links use it too
	 */
	LinkedTextPane(Color colour, Font font)
	{
		this.colour = colour;
		this.font = font;
		// First: installing a kit replaces the document.
		setEditorKit(new WrappingKit());
		setEditable(false);
		setFocusable(false);
		setOpaque(false);
		setForeground(colour);
		setFont(font);
		setAlignmentX(LEFT_ALIGNMENT);
		setBorder(BorderFactory.createEmptyBorder());
		setCaret(new StepCardPanel.NonScrollingCaret());
		// Registered for getToolTipText(MouseEvent); a fixed tooltip would show off the links too.
		ToolTipManager.sharedInstance().registerComponent(this);

		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				String url = urlAt(e.getPoint());
				if (url != null)
				{
					LinkBrowser.browse(url);
				}
			}

			@Override
			public void mouseMoved(MouseEvent e)
			{
				Cursor wanted = urlAt(e.getPoint()) != null ? HAND : DEFAULT;
				if (getCursor() != wanted)
				{
					setCursor(wanted);
				}
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	/**
	 * Replaces the text. Call only when the text changes, not on every refresh.
	 *
	 * @param markdown the text, with inline {@code [label](url)} links; null reads as empty
	 * @param inlineMarkup whether {@code **bold**}, {@code *italic*} and {@code ~~strike~~}
	 *     markers are applied. False for source text, whose asterisks are literal.
	 */
	void setMarkdown(String markdown, boolean inlineMarkup)
	{
		parsed = MarkdownLinks.parse(markdown, inlineMarkup);
		StyledDocument doc = getStyledDocument();
		try
		{
			doc.remove(0, doc.getLength());
			for (MarkdownLinks.Run run : parsed.runs)
			{
				doc.insertString(doc.getLength(), run.text, style(run));
			}
		}
		catch (BadLocationException e)
		{
			// Unreachable: every offset used is 0 or the document's own length.
			throw new IllegalStateException(e);
		}
		setCursor(DEFAULT);
	}

	/** The text as it reads, links shown as their labels. */
	String plainText()
	{
		return parsed.text;
	}

	/**
	 * The URL of the label under a point, or null. A point past the end of a line, or in the
	 * gap beside a label, is not on it: {@code viewToModel2D} answers with the nearest offset
	 * however far away the point is, so the character's own box is checked as well.
	 *
	 * @param point a point in this component's coordinates
	 * @return the label's URL, or null when the point is not on a label
	 */
	String urlAt(Point point)
	{
		int offset = viewToModel2D(point);
		if (offset < 0)
		{
			return null;
		}
		// viewToModel2D rounds to the nearer caret position, so the character under the point
		// is either the one after that position or the one before it.
		for (int candidate = offset; candidate >= offset - 1 && candidate >= 0; candidate--)
		{
			String url = parsed.urlAt(candidate);
			if (url != null && characterContains(candidate, point))
			{
				return url;
			}
		}
		return null;
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		return urlAt(event.getPoint());
	}

	@Override
	public Dimension getMaximumSize()
	{
		// The preferred height already reflects wrapping at this width.
		int width = getWidth();
		if (width <= 0)
		{
			return super.getMaximumSize();
		}
		return new Dimension(width, getPreferredSize().height);
	}

	/** Whether the point falls inside the box the character at {@code offset} is drawn in. */
	private boolean characterContains(int offset, Point point)
	{
		try
		{
			Rectangle2D start = modelToView2D(offset);
			Rectangle2D end = modelToView2D(offset + 1);
			if (start == null || end == null
				|| point.y < start.getY() || point.y >= start.getMaxY())
			{
				return false;
			}
			// When the line wraps after this character the next offset sits on the line below,
			// so the box runs to the line's end.
			double right = end.getY() == start.getY() ? end.getX() : getWidth();
			return point.x >= start.getX() && point.x < right;
		}
		catch (BadLocationException e)
		{
			return false;
		}
	}

	/**
	 * A styled kit whose text runs report no minimum width. A BoxView lays each paragraph out
	 * at no less than the paragraph's minimum span, and the JDK's GlyphView reports a minimum
	 * that grows with the run, so a long run can lay out, and draw, wider than the pane and past
	 * the panel's edge. With a zero minimum the paragraph flows at the width it is given, and a
	 * word longer than a line breaks inside itself, as it would in a JTextArea.
	 */
	private static final class WrappingKit extends StyledEditorKit
	{
		private static final ViewFactory FACTORY = element ->
		{
			String kind = element.getName();
			if (AbstractDocument.ParagraphElementName.equals(kind))
			{
				return new ParagraphView(element);
			}
			if (AbstractDocument.SectionElementName.equals(kind))
			{
				return new BoxView(element, View.Y_AXIS);
			}
			if (StyleConstants.ComponentElementName.equals(kind))
			{
				return new ComponentView(element);
			}
			if (StyleConstants.IconElementName.equals(kind))
			{
				return new IconView(element);
			}
			return new LabelView(element)
			{
				@Override
				public float getMinimumSpan(int axis)
				{
					return axis == View.X_AXIS ? 0 : super.getMinimumSpan(axis);
				}
			};
		};

		@Override
		public ViewFactory getViewFactory()
		{
			return FACTORY;
		}
	}

	private SimpleAttributeSet style(MarkdownLinks.Run run)
	{
		SimpleAttributeSet style = new SimpleAttributeSet();
		StyleConstants.setFontFamily(style, font.getFamily());
		StyleConstants.setFontSize(style, font.getSize());
		StyleConstants.setForeground(style, run.url != null ? COLOR_LINK : colour);
		StyleConstants.setUnderline(style, run.url != null);
		StyleConstants.setBold(style, run.bold);
		StyleConstants.setItalic(style, run.italic);
		StyleConstants.setStrikeThrough(style, run.strike);
		return style;
	}
}

package com.stepwise.panel;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Inline {@code [label](url)} links in guide text: the text as it reads with each link replaced
 * by its label, and where each label sits so a click can find its URL.
 *
 * <p>Swing-free, like {@link TextMarkup}, so the trailing-group split, the parse and the
 * offset-to-URL mapping are unit testable. {@link LinkedText} draws the result: trailing links
 * as rows, the rest inline through {@link LinkedTextPane}.
 *
 * <p>Links are masked before {@link TextMarkup} sees the text. A screenshot label such as
 * {@code F3_Grapple_West.png} or a wiki URL such as {@code .../Gout_tuber/Strategies}
 * would otherwise pair its underscores into italics.
 */
final class MarkdownLinks
{
	/**
	 * A well-formed link: a one-line label with no brackets, then an http(s) URL with no
	 * whitespace and no raw parentheses (the guide data percent-encodes them as {@code %28}/
	 * {@code %29}). Anything else is plain text.
	 */
	static final Pattern LINK = Pattern.compile("\\[([^\\[\\]\\r\\n]+)]\\((https?://[^\\s()]+)\\)");

	/**
	 * A URL a click can open: http(s), a host, then only the characters RFC 3986 allows, with
	 * every {@code %} starting a two-digit escape. {@code LinkBrowser.browse} parses the URL
	 * and throws on anything else, which would happen on the EDT inside the click handler.
	 *
	 * @see <a href="https://www.rfc-editor.org/rfc/rfc3986#appendix-A">RFC 3986, appendix A</a>
	 */
	private static final Pattern BROWSABLE_URL = Pattern.compile(
		"https?://[A-Za-z0-9.-]+(?::[0-9]+)?(?:[/?#](?:[A-Za-z0-9\\-._~/?#@!$&'*+,;=:]|%[0-9A-Fa-f]{2})*)?");

	/**
	 * First character of the placeholders that stand in for links while {@link TextMarkup}
	 * parses. Private-use code points never occur in guide text, and each placeholder is one
	 * character, so no markup span can split a label.
	 */
	private static final char PLACEHOLDER_BASE = (char) 0xE000;
	private static final int PLACEHOLDER_LIMIT = 0xF8FF - 0xE000;

	private MarkdownLinks()
	{
	}

	/** A run of text in one style. {@link #url} is set only on a link's label. */
	static final class Run
	{
		final String text;
		final boolean bold;
		final boolean italic;
		final boolean strike;
		/** Where the run links to, or null for plain text. */
		final String url;

		Run(String text, boolean bold, boolean italic, boolean strike, String url)
		{
			this.text = text;
			this.bold = bold;
			this.italic = italic;
			this.strike = strike;
			this.url = url;
		}
	}

	/** Where a label sits in the rendered text: {@code [start, end)}. */
	static final class Link
	{
		final int start;
		final int end;
		final String url;

		Link(int start, int end, String url)
		{
			this.start = start;
			this.end = end;
			this.url = url;
		}
	}

	/** Parsed text: the runs to draw, the plain text they spell, and the link ranges in it. */
	static final class Parsed
	{
		final List<Run> runs;
		final String text;
		final List<Link> links;

		private Parsed(List<Run> runs)
		{
			this.runs = runs;
			StringBuilder text = new StringBuilder();
			List<Link> links = new ArrayList<>();
			for (Run run : runs)
			{
				if (run.url != null)
				{
					links.add(new Link(text.length(), text.length() + run.text.length(), run.url));
				}
				text.append(run.text);
			}
			this.text = text.toString();
			this.links = Collections.unmodifiableList(links);
		}

		/**
		 * The URL of the label covering a character.
		 *
		 * @param offset a character offset into {@link #text}
		 * @return the URL, or null when the character is not part of a label
		 */
		String urlAt(int offset)
		{
			for (Link link : links)
			{
				if (offset >= link.start && offset < link.end)
				{
					return link.url;
				}
			}
			return null;
		}
	}

	/** Guide text split into the body and the trailing link group lifted out of it. */
	static final class Split
	{
		/** The text before the trailing group, trailing whitespace removed. May be empty. */
		final String body;
		/** The trailing group's links in order, each {@code {label, url}}. Empty when none. */
		final List<String[]> trailing;

		private Split(String body, List<String[]> trailing)
		{
			this.body = body;
			this.trailing = Collections.unmodifiableList(trailing);
		}
	}

	/**
	 * Splits off the links an author put after the final sentence, which the panel lifts into
	 * rows of their own; every other link stays in the body, to be drawn inline.
	 *
	 * <p>The trailing group is the longest run of links at the very end of the text with
	 * nothing but whitespace after and between them. So "[the setup](url)." stays inline, as
	 * does a link followed by a comma. A link a browser could not open ends the group, so it
	 * stays in the body and reads as plain text there.
	 *
	 * @param markdown the text; null reads as empty
	 * @return the body and the trailing group
	 */
	static Split splitTrailing(String markdown)
	{
		if (markdown == null)
		{
			return new Split("", Collections.emptyList());
		}
		List<int[]> spans = new ArrayList<>();
		List<String[]> links = new ArrayList<>();
		Matcher m = LINK.matcher(markdown);
		while (m.find())
		{
			spans.add(new int[]{m.start(), m.end()});
			links.add(new String[]{m.group(1), m.group(2)});
		}

		// Walk back from the end while each gap holds only whitespace.
		int groupStart = markdown.length();
		int first = links.size();
		for (int i = links.size() - 1; i >= 0; i--)
		{
			if (!markdown.substring(spans.get(i)[1], groupStart).isBlank()
				|| !isBrowsable(links.get(i)[1]))
			{
				break;
			}
			groupStart = spans.get(i)[0];
			first = i;
		}
		return new Split(markdown.substring(0, groupStart).stripTrailing(),
			new ArrayList<>(links.subList(first, links.size())));
	}

	/**
	 * Parses guide text.
	 *
	 * <p>Text that only looks like a link stays as written: an unclosed bracket or parenthesis
	 * does not match, and nor does a link to anything but http or https. A well-formed http(s)
	 * link whose URL does not parse keeps its label as plain text, so the reader loses nothing
	 * and no click can fail.
	 *
	 * @param markdown the text; null reads as empty
	 * @param inlineMarkup whether to apply {@link TextMarkup} bold, italic and strikethrough.
	 *     Off for source text, whose asterisks and underscores are literal.
	 * @return the parsed text
	 */
	static Parsed parse(String markdown, boolean inlineMarkup)
	{
		if (markdown == null || markdown.isEmpty())
		{
			return new Parsed(Collections.emptyList());
		}

		List<String[]> found = new ArrayList<>();
		StringBuilder masked = new StringBuilder(markdown.length());
		Matcher m = LINK.matcher(markdown);
		int last = 0;
		while (m.find() && found.size() < PLACEHOLDER_LIMIT)
		{
			masked.append(markdown, last, m.start());
			masked.append((char) (PLACEHOLDER_BASE + found.size()));
			found.add(new String[]{m.group(1), m.group(2)});
			last = m.end();
		}
		masked.append(markdown, last, markdown.length());

		List<TextMarkup.Span> spans = inlineMarkup
			? TextMarkup.parse(masked.toString())
			: List.of(new TextMarkup.Span(masked.toString(), false, false, false));

		List<Run> runs = new ArrayList<>();
		for (TextMarkup.Span span : spans)
		{
			unmask(span, found, runs);
		}
		return new Parsed(runs);
	}

	/** Splits a span at its placeholders, putting each link's label back in its place. */
	private static void unmask(TextMarkup.Span span, List<String[]> found, List<Run> out)
	{
		String text = span.text;
		int plainStart = 0;
		for (int i = 0; i < text.length(); i++)
		{
			int index = text.charAt(i) - PLACEHOLDER_BASE;
			if (index < 0 || index >= found.size())
			{
				continue;
			}
			if (i > plainStart)
			{
				out.add(new Run(text.substring(plainStart, i), span.bold, span.italic, span.strike, null));
			}
			String label = found.get(index)[0];
			String url = found.get(index)[1];
			out.add(new Run(label, span.bold, span.italic, span.strike, isBrowsable(url) ? url : null));
			plainStart = i + 1;
		}
		if (plainStart < text.length())
		{
			out.add(new Run(text.substring(plainStart), span.bold, span.italic, span.strike, null));
		}
	}

	/**
	 * Whether a click could open this URL. {@link #LINK} admits any non-space run after
	 * {@code http(s)://}, so a link holding a character {@code LinkBrowser.browse} rejects
	 * ({@code |}, a brace, a quote) reads as plain text instead.
	 *
	 * @param url the link target
	 * @return true when the URL matches {@link #BROWSABLE_URL}
	 */
	static boolean isBrowsable(String url)
	{
		return BROWSABLE_URL.matcher(url).matches();
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Dimension;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * The panel's shared palette and rules. Colours that belong to one view's own look stay in
 * that view's file.
 */
final class PanelColors
{
	/** Muted text for fold headers, labels, unmet criteria, section breadcrumbs. */
	static final Color HEADER = ColorScheme.LIGHT_GRAY_COLOR;
	/** Clickable link text (markdown guidance links, wiki links). */
	static final Color LINK = new Color(100, 180, 255);
	/** De-emphasized text (waived criteria, step IDs, version footers). */
	static final Color SUBTLE = new Color(80, 80, 80);
	/** Destructive action highlights (skip confirm, reset, clear). */
	static final Color DANGER = new Color(255, 51, 51);
	/** Something the player should act on: a bank withdrawal, a restock, behind the route. */
	static final Color AMBER = new Color(199, 122, 24);
	/**
	 * The brand's colours, taken from the game's account-type chat icons: hardcore red from the
	 * hardcore group ironman icon and iron grey from the ironman icon. Only the header wears
	 * them, so red keeps its meaning elsewhere in the panel.
	 */
	static final Color BRAND_RED_LIGHT = new Color(196, 48, 42);
	static final Color BRAND_RED = new Color(148, 22, 21);
	static final Color BRAND_IRON_LIGHT = new Color(124, 129, 130);
	/** Divider line between items in a container. */
	static final Color DIVIDER = new Color(55, 55, 55);
	static final Color CONTAINER_BG = ColorScheme.DARKER_GRAY_COLOR.darker();
	static final Color CONTAINER_BORDER = ColorScheme.MEDIUM_GRAY_COLOR.darker();

	private PanelColors()
	{
	}

	/** A 1px horizontal divider line for use inside list containers. */
	static JPanel divider()
	{
		return divider(DIVIDER);
	}

	/** A full-width 1px horizontal line in {@code colour}. */
	static JPanel divider(Color colour)
	{
		return rule(colour, 1);
	}

	/** A full-width horizontal line {@code height} pixels tall in {@code colour}. */
	static JPanel rule(Color colour, int height)
	{
		JPanel line = new JPanel();
		line.setBackground(colour);
		line.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		line.setPreferredSize(new Dimension(0, height));
		return line;
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * The sidebar's section chrome: the header label, the fold toggle, the gap above a section
 * and the box around its rows. Every section builds these here, so they cannot drift apart.
 */
final class PanelSections
{
	/** Gap above the Recent fold: smaller than a section's, since a fold is not a section. */
	static final int FOLD_GAP = 4;
	/**
	 * Gap above a section that stands on its own (the entry block, Restock, In Progress,
	 * Upcoming, Timers), and above the Data fold, which belongs to none of them.
	 */
	static final int SECTION_GAP = 8;

	/**
	 * Between a header and its content. The 2px left puts every header and fold arrow on one
	 * vertical line.
	 */
	static final Border HEADER_INSET = BorderFactory.createEmptyBorder(0, 2, 3, 0);

	/** Space between chips in a row. */
	static final int CHIP_GAP = 2;

	private static final Color SECTION_HEADER = Color.WHITE;
	private static final Color CHIP_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color CHIP_OPEN_BG = ColorScheme.DARK_GRAY_HOVER_COLOR;

	// Shared, so a section that rebuilds every refresh sets the same border instance and
	// setBorder fires no relayout.
	private static final Border FOLD_GAP_BORDER = BorderFactory.createEmptyBorder(FOLD_GAP, 0, 0, 0);
	private static final Border SECTION_GAP_BORDER = BorderFactory.createEmptyBorder(SECTION_GAP, 0, 0, 0);

	private static final String SHUT = "▸ ";
	private static final String OPEN = "▾ ";

	private PanelSections()
	{
	}

	/** The gap above a section, set as the section wrapper's border. */
	static Border gap(int px)
	{
		if (px == FOLD_GAP)
		{
			return FOLD_GAP_BORDER;
		}
		if (px == SECTION_GAP)
		{
			return SECTION_GAP_BORDER;
		}
		return BorderFactory.createEmptyBorder(px, 0, 0, 0);
	}

	/**
	 * A section header that does not fold. White bold, so it outranks the tan group headings
	 * inside a section and the grey fold headers.
	 */
	static JLabel header(String text)
	{
		return label(text, SECTION_HEADER, FontManager.getRunescapeBoldFont());
	}

	/**
	 * Gives a label the section header's colour and font, for a header row that carries
	 * {@link #HEADER_INSET} itself because it holds a second label (the entry block's title
	 * and duration).
	 */
	static void styleAsHeader(JLabel label)
	{
		label.setForeground(SECTION_HEADER);
		label.setFont(FontManager.getRunescapeBoldFont());
	}

	/**
	 * A fold's header, shut. The caller adds the click handling and sets the text through
	 * {@link #foldText} as the fold opens and shuts. Grey small type: a fold holds detail
	 * on demand, below the sections in rank.
	 */
	static JLabel foldToggle(String label)
	{
		JLabel toggle = label(foldText(label, false), PanelColors.HEADER,
			FontManager.getRunescapeSmallFont());
		toggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		return toggle;
	}

	/** A fold header's text: the label after a small arrow pointing right when shut, down when open. */
	static String foldText(String label, boolean open)
	{
		return (open ? OPEN : SHUT) + label;
	}

	/** The bordered box a section's rows sit in. Its border is the 1px line alone, no padding. */
	static JPanel box()
	{
		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(PanelColors.CONTAINER_BG);
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		box.setBorder(BorderFactory.createLineBorder(PanelColors.CONTAINER_BORDER, 1));
		return box;
	}

	/** A one-line label in the small RuneScape font. */
	static JLabel smallLabel(String text, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(colour);
		return label;
	}

	/** Gives a panel a transparent, left-aligned column layout that stacks its children. */
	static <T extends JPanel> T column(T panel)
	{
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/** A new transparent, left-aligned column. */
	static JPanel column()
	{
		return column(new JPanel());
	}

	/**
	 * A chip's border: a 1px line in {@code line} around the label's padding. Shared instances
	 * matter: {@link #styleChip} compares borders by identity, so a fresh border per refresh
	 * would repaint the chip every tick.
	 */
	static Border chipBorder(Color line)
	{
		return BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(line),
			BorderFactory.createEmptyBorder(3, 5, 3, 5));
	}

	/** A transparent row of chips. FlowLayout's leading gap lines the first chip up with a header's 2px inset. */
	static JPanel chipRow()
	{
		JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, CHIP_GAP, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		return row;
	}

	/** A clickable chip, shut: small text in {@code colour} on the chip background. */
	static JLabel chip(String text, Color colour, Border shut, Runnable onClick)
	{
		JLabel chip = smallLabel(text, colour);
		chip.setOpaque(true);
		chip.setBackground(CHIP_BG);
		chip.setBorder(shut);
		chip.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		chip.addMouseListener(clicks(onClick));
		return chip;
	}

	/** Shows a chip open (white on the hover background) or shut. Writes nothing when unchanged. */
	static void styleChip(JComponent chip, boolean open, Border openBorder, Border shutBorder,
		Color shutColour)
	{
		if (chip.getBorder() == (open ? openBorder : shutBorder))
		{
			return;
		}
		chip.setBorder(open ? openBorder : shutBorder);
		chip.setBackground(open ? CHIP_OPEN_BG : CHIP_BG);
		chip.setForeground(open ? Color.WHITE : shutColour);
	}

	/** A listener that runs {@code action} on each click. */
	static MouseAdapter clicks(Runnable action)
	{
		return new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				action.run();
			}
		};
	}

	/** A callout's left rule: 2px in {@code colour}, then the text's padding. */
	static Border callout(Color colour)
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, colour),
			BorderFactory.createEmptyBorder(1, 5, 1, 0));
	}

	private static JLabel label(String text, Color colour, Font font)
	{
		JLabel label = smallLabel(text, colour);
		label.setFont(font);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(HEADER_INSET);
		return label;
	}
}

package com.stepwise.panel;

import java.util.Objects;

/**
 * Gates structural rebuilds of a Swing container so it recreates its children
 * only when its <em>structure</em> changes, not on every per-tick refresh.
 *
 * <p>The sidebar refreshes on every snapshot (one per game event). A freshly
 * added wrapping {@code JTextArea} reports a one-line preferred height until
 * layout assigns its width, then re-wraps on the next pass. Recreating it every
 * tick therefore makes its height oscillate and the panel flicker. Keeping the
 * component alive keeps its width and wrapped height stable.
 *
 * <p>Usage: build a value-equality <em>signature</em> from the structural inputs
 * only (row identities, text, met/unmet state). Progress values change
 * continuously and belong in in-place updates, <strong>not</strong> in the
 * signature. Rebuild only when the signature changes:
 *
 * <pre>{@code
 * if (guard.shouldRebuild(rowSignature(rows))) {
 *     container.removeAll();
 *     // ... add rows ...
 *     container.revalidate();
 *     container.repaint();
 * }
 * }</pre>
 *
 * <p>A signature is typically a {@code List<String>} with one delimited string
 * per row. See {@code StepCardPanel.criteriaSignature}.
 *
 * <p>Not thread-safe. Use only on the Swing EDT.
 */
final class RebuildGuard
{
	/** Signature of the last rebuild, or null before the first one. */
	private Object lastSignature;

	/**
	 * Returns true and records {@code signature} when it differs from the last
	 * one. Returns false when nothing structural changed, and the caller updates
	 * dynamic values in place instead.
	 *
	 * <p>A caller that builds its children at construction time must prime the
	 * guard with the initial signature, or the first refresh rebuilds needlessly.
	 */
	boolean shouldRebuild(Object signature)
	{
		if (Objects.equals(lastSignature, signature))
		{
			return false;
		}
		lastSignature = signature;
		return true;
	}

	/**
	 * Clears the recorded signature so the next {@link #shouldRebuild} call
	 * forces a rebuild. Call it whenever the container is emptied outside the
	 * guard, such as on a null snapshot.
	 */
	void reset()
	{
		lastSignature = null;
	}
}

package com.stepwise.panel;

import com.stepwise.snapshot.AssumptionNudge;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.border.Border;
import net.runelite.client.ui.FontManager;

/**
 * Under the current step card, a Restock section boxed like In Progress: one amber chip per
 * route assumption the player is not meeting, each an item icon and a short name. Clicking a
 * chip opens its reminder under the chips, and clicking it again shuts it. One reminder is
 * open at a time.
 *
 * <p>The chips follow the snapshot, so a chip goes away by itself once the player restocks.
 * They rebuild only when the set of nudges changes; an unchanged tick touches nothing.
 */
class RestockStrip extends JPanel
{
	private static final Color COLOR_AMBER = PanelColors.AMBER;

	private static final Border CHIP_SHUT = PanelSections.chipBorder(COLOR_AMBER);
	private static final Border CHIP_OPEN = PanelSections.chipBorder(COLOR_AMBER.brighter());

	static final int CHIP_ICON_SIZE = 14;
	private static final int CHIP_GAP = PanelSections.CHIP_GAP;
	private static final int ROW_GAP = 2;

	private final JPanel box = PanelSections.box();
	private final JPanel chips = PanelSections.column();
	private final JPanel callout = new JPanel(new BorderLayout());
	private final JTextArea calloutText;
	private final RebuildGuard guard = new RebuildGuard();
	private final List<JLabel> chipLabels = new ArrayList<>();

	private IconProvider iconProvider;
	private List<AssumptionNudge> nudges = List.of();
	/** The nudge whose reminder is open, or null with all shut. */
	private AssumptionNudge open;

	RestockStrip()
	{
		PanelSections.column(this);
		setBorder(PanelSections.gap(PanelSections.SECTION_GAP));
		JLabel header = PanelSections.header("Restock");

		calloutText = StepCardPanel.textArea(" ", COLOR_AMBER, FontManager.getRunescapeSmallFont());
		callout.setOpaque(false);
		callout.setAlignmentX(LEFT_ALIGNMENT);
		callout.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createEmptyBorder(4, 2, 0, 0), PanelSections.callout(COLOR_AMBER)));
		callout.add(calloutText, BorderLayout.CENTER);
		callout.setVisible(false);

		// The box's 1px line, padded inside. The chip rows' own 2px FlowLayout gap makes up the
		// rest of the left inset.
		box.setBorder(BorderFactory.createCompoundBorder(
			box.getBorder(),
			BorderFactory.createEmptyBorder(4, 2, 4, 4)));
		box.add(chips);
		box.add(callout);

		add(header);
		add(box);
		guard.shouldRebuild(List.of());
		setVisible(false);
	}

	/**
	 * Follows the current step's nudges. Called on every refresh.
	 *
	 * @param nudges the current step's nudges; null or empty hides the strip
	 */
	void update(List<AssumptionNudge> nudges, IconProvider iconProvider)
	{
		List<AssumptionNudge> next = nudges == null ? List.of() : nudges;
		this.iconProvider = iconProvider;
		if (!guard.shouldRebuild(next))
		{
			return;
		}
		this.nudges = next;
		if (open != null && !next.contains(open))
		{
			open = null;
		}
		buildChips();
		applyOpen();
		setVisible(!next.isEmpty());
		revalidate();
		repaint();
	}

	/**
	 * Packs the chips into rows that fit the panel's content width. FlowLayout would report
	 * one row however narrow the panel, and a chip pushed to a second row would never show.
	 */
	private void buildChips()
	{
		chips.removeAll();
		chipLabels.clear();
		JPanel row = null;
		int rowWidth = 0;
		for (AssumptionNudge nudge : nudges)
		{
			JLabel chip = chip(nudge);
			int width = chip.getPreferredSize().width + CHIP_GAP;
			if (row == null || rowWidth + width > innerWidth())
			{
				if (row != null)
				{
					chips.add(Box.createVerticalStrut(ROW_GAP));
				}
				row = PanelSections.chipRow();
				chips.add(row);
				rowWidth = CHIP_GAP;
			}
			row.add(chip);
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			rowWidth += width;
			chipLabels.add(chip);
		}
	}

	private JLabel chip(AssumptionNudge nudge)
	{
		JLabel chip = PanelSections.chip(nudge.getLabel(), COLOR_AMBER, CHIP_SHUT, () -> toggle(nudge));
		chip.setIconTextGap(4);
		chip.setToolTipText(nudge.getReminder());
		ImageIcon icon = iconProvider != null && nudge.getItemId() > 0
			? iconProvider.getItemIcon(nudge.getItemId(), CHIP_ICON_SIZE) : null;
		if (icon != null)
		{
			chip.setIcon(icon);
		}
		// A row always takes its first chip, so a label wider than the box would run past its
		// edge. Capped, the JLabel ends the text with "..."; the reminder, shown as the tooltip
		// and when the chip opens, still names what ran out in full.
		int widest = innerWidth() - 2 * CHIP_GAP;
		Dimension pref = chip.getPreferredSize();
		if (pref.width > widest)
		{
			chip.setPreferredSize(new Dimension(widest, pref.height));
		}
		return chip;
	}

	private void toggle(AssumptionNudge nudge)
	{
		open = Objects.equals(open, nudge) ? null : nudge;
		applyOpen();
		revalidate();
		repaint();
	}

	private void applyOpen()
	{
		for (int i = 0; i < chipLabels.size(); i++)
		{
			PanelSections.styleChip(chipLabels.get(i), nudges.get(i).equals(open), CHIP_OPEN,
				CHIP_SHUT, COLOR_AMBER);
		}
		if (open == null)
		{
			callout.setVisible(false);
			return;
		}
		calloutText.setText(open.getReminder());
		// Pre-size so the reminder wraps at its real width on first paint.
		int width = innerWidth() - callout.getInsets().left - callout.getInsets().right;
		calloutText.setSize(width, Short.MAX_VALUE);
		calloutText.setSize(width, calloutText.getPreferredSize().height);
		callout.setVisible(true);
	}

	/** The width inside the box: the panel's content width less the box's border and padding. */
	int innerWidth()
	{
		return StepwisePanel.CONTENT_WIDTH - box.getInsets().left - box.getInsets().right;
	}

	// --- Test seams ---

	/** The callout's text area, so a test can check it was sized before first paint. */
	JTextArea calloutTextForTest()
	{
		return calloutText;
	}
}

