			+ "when you log in."));
	}

	private static JTextArea muted(String text)
	{
		return StepCardPanel.textArea(text, COLOR_MUTED, FontManager.getRunescapeSmallFont());
	}

	/** The guide's title, size and version, and the guide's authors. */
	private void addGuideCredit(JPanel panel)
	{
		String title = guide != null && guide.getTitle() != null ? guide.getTitle() : "BRUHsailer";
		panel.add(StepCardPanel.textArea(title, Color.WHITE, FontManager.getRunescapeFont()));
		if (guide != null)
		{
			String info = String.format(Locale.ROOT, "%,d steps", guide.allSteps().size());
			if (guide.getVersion() != null)
			{
				// The BRUHsailer document's own version, the date stamp it puts on each chapter.
				info += "  \u00B7  " + versionText(guide.getVersion());
			}
			panel.add(muted(info));
		}
		panel.add(Box.createVerticalStrut(6));
		panel.add(muted("Written by So Iron BRUH and ParasailerOSRS. Stepwise follows their route "
			+ "and shows their text, but it is unofficial: the guide's authors did not make it and "
			+ "do not maintain it."));
		panel.add(Box.createVerticalStrut(2));
		panel.add(buildLink("Original guide",
			"https://docs.google.com/document/d/1CBkFM70SnrW4hJXvHM2F1fYCuBF_fRnEXnTYgRnRkAE"));
		panel.add(buildLink("Interactive guide", "https://umkyzn.github.io/BRUHsailer/"));
		panel.add(buildLink("Wiki page", "https://oldschool.runescape.wiki/w/Guide:BRUHsailer"));
	}

	/**
	 * Writes the chapter and section lines, each only when it changed. Setting a wrapping
	 * area's text re-measures it, and setToolTipText re-registers even for an unchanged value.
	 */
	void showHeading(String chapter, String section)
	{
		if (!chapter.equals(chapterText.getText()))
		{
			chapterText.setText(chapter);
			chapterText.setToolTipText(chapter.isBlank() ? null : chapter);
		}
		if (!section.equals(sectionText.getText()))
		{
			sectionText.setText(section);
			headerPanel.revalidate();
		}
	}

	/**
	 * Turns "2.1: Quests and combat" into "2.1 · Quests and combat". A title without a
	 * dotted number before its colon is returned unchanged.
	 */
	static String formatSectionLabel(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return "";
		}
		int colon = raw.indexOf(':');
		if (colon <= 0 || raw.substring(0, colon).indexOf('.') < 0)
		{
			return raw;
		}
		String number = raw.substring(0, colon).trim();
		String name = raw.substring(colon + 1).trim();
		return name.isEmpty() ? number : number + " · " + name;
	}

	JTextArea getSectionTextForTest()
	{
		return sectionText;
	}

	/**
	 * The guide title's first word ("BRUHsailer Complete Guide" gives "BRUHsailer"), or
	 * "Guide" when there is no title.
	 */
	private String shortGuideName()
	{
		if (guide == null || guide.getTitle() == null || guide.getTitle().isBlank())
		{
			return "Guide";
		}
		String title = guide.getTitle().trim();
		int space = title.indexOf(' ');
		return space > 0 ? title.substring(0, space) : title;
	}

	/**
	 * The guide's version as a player reads it. The BRUHsailer document stamps each version
	 * with its date as yyyyMMdd, which reads "dated" and the day, month and year; any other
	 * value reads "version" and the value.
	 */
	static String versionText(String version)
	{
		try
		{
			return "dated " + LocalDate.parse(version, DateTimeFormatter.BASIC_ISO_DATE).format(GUIDE_DATE);
		}
		catch (DateTimeParseException e)
		{
			return "version " + version;
		}
	}

	/**
	 * Formats an entry duration in minutes as "~45m" or "~1h30m", to the nearest minute and
	 * at least one. Returns null when there is no positive duration.
	 */
	static String formatEntryDuration(Double minutes)
	{
		if (minutes == null || minutes <= 0)
		{
			return null;
		}
		int mins = Math.max(1, (int) Math.round(minutes));
		if (mins < 60)
		{
			return "~" + mins + "m";
		}
		int hours = mins / 60;
		int rem = mins % 60;
		return rem > 0
			? "~" + hours + "h" + rem + "m"
			: "~" + hours + "h";
	}

	private static JPanel buildActionRow(String description, JButton button)
	{
		JPanel row = PanelSections.column();
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));

		row.add(muted(description));
		row.add(Box.createVerticalStrut(3));
		row.add(button);

		return row;
	}

	/** A Data action: it waits armed until confirmed, and does nothing without an engine. */
	private ConfirmButton dataButton(String text, Runnable action)
	{
		ConfirmButton btn = new ConfirmButton(text, false, () ->
		{
			if (coreEngine != null)
			{
				action.run();
			}
		});
		btn.setFocusPainted(false);
		btn.setFont(FontManager.getRunescapeSmallFont());
		btn.setBorderPainted(false);
		btn.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		btn.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return btn;
	}

	private static JTextArea buildLink(String label, String url)
	{
		JTextArea link = LinkedText.link(label, url);
		link.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		return link;
	}

	/**
	 * Collapsible "Data" section of destructive actions. Each button needs a second click
	 * to confirm, and collapsing the section cancels any pending confirmation.
	 */
	private JPanel buildResetControlsPanel()
	{
		JPanel wrapper = PanelSections.column();
		wrapper.setBorder(PanelSections.gap(PanelSections.SECTION_GAP));
		JLabel toggle = PanelSections.foldToggle("Data");

		ConfirmButton[] buttons = {
			// The reset moves the snapshot version, so the next refresh rebuilds by itself.
			dataButton("Reset Guide", () -> coreEngine.resetGuideProgress()),
			dataButton("Forget Bank", () -> coreEngine.clearBankSnapshot()),
			dataButton("Reset Bird Houses", () -> coreEngine.resetBirdhouseTimers())
		};
		String[] descriptions = {
			"Clear your guide progress. Every step the game shows as done is checked off again.",
			"Forget the bank contents Stepwise has seen. Open your bank for it to look again.",
			"Clear the bird house timers. Your guide progress is kept."
		};

		JPanel actionsPanel = PanelSections.column();
		actionsPanel.setVisible(false);

		JPanel container = PanelSections.box();
		for (int i = 0; i < buttons.length; i++)
		{
			if (i > 0)
			{
				container.add(PanelColors.divider());
			}
			container.add(buildActionRow(descriptions[i], buttons[i]));
		}
		actionsPanel.add(container);

		toggle.addMouseListener(PanelSections.clicks(() ->
		{
			boolean show = !actionsPanel.isVisible();
			actionsPanel.setVisible(show);
			toggle.setText(PanelSections.foldText("Data", show));
			if (!show)
			{
				for (ConfirmButton button : buttons)
				{
					button.disarm();
				}
			}
			wrapper.revalidate();
		}));

		wrapper.add(toggle);
		wrapper.add(actionsPanel);

		return wrapper;
	}

	/**
	 * The scroll pane's view, which stops its contents from scrolling the viewport.
	 *
	 * <p>Sections rebuild constantly while the player reads, and Swing components ask to be
	 * scrolled into view when added or focused. {@code scrollRectToVisible} propagates up the
	 * parent chain, so swallowing it here, directly below the viewport, blocks every such
	 * request. The scrollbar and mouse wheel drive the viewport directly and still work, and
	 * so does any code that sets the viewport's position itself.
	 */
	private static class ScrollAnchoredPanel extends JPanel
	{
		ScrollAnchoredPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public void scrollRectToVisible(Rectangle aRect)
		{
			// Empty on purpose. See class doc.
		}
	}

	/**
	 * A JPanel whose preferred width is {@link #CONTENT_WIDTH}, so text does not render
	 * behind the RuneLite sidebar icon strip.
	 */
	private static class FixedWidthPanel extends JPanel
	{

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(CONTENT_WIDTH, super.getPreferredSize().height);
		}
	}
}

package com.stepwise.panel;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Inline markup helpers for the Stepwise UI.
 * <p>
 * Supported markup: {@code **bold**}, {@code *italic*} / {@code _italic_},
 * and {@code ~~strikethrough~~}. Markers may nest. Unclosed markers render
 * literally.
 * <p>
 * {@link #parse(String)} stays Swing-free so Graphics2D overlays
 * ({@link #stripMarkup(String)}) and JTextPane documents can share it.
 */
public final class TextMarkup
{
	private TextMarkup()
	{
	}

	/**
	 * A run of text with its resolved inline styles. Styles are flattened from
	 * the (possibly nested) markup, so a span inside {@code **_..._**} carries
	 * both {@code bold} and {@code italic}.
	 */
	public static final class Span
	{
		public final String text;
		public final boolean bold;
		public final boolean italic;
		public final boolean strike;

		public Span(String text, boolean bold, boolean italic, boolean strike)
		{
			this.text = text;
			this.bold = bold;
			this.italic = italic;
			this.strike = strike;
		}
	}

	/**
	 * Tokenizes inline markup into a flat list of styled spans.
	 * <p>
	 * An opening marker counts only when a matching close exists later in the
	 * range. Otherwise it is emitted literally. All other characters, including
	 * {@code \n}, are preserved.
	 *
	 * @param text input markup (may be {@code null})
	 * @return styled spans in document order; empty for {@code null}/empty input
	 */
	public static List<Span> parse(String text)
	{
		if (text == null || text.isEmpty())
		{
			return Collections.emptyList();
		}
		List<Span> spans = new ArrayList<>();
		parseRange(text, 0, text.length(), false, false, false, new StringBuilder(), spans);
		return spans;
	}

	/**
	 * Parses {@code [start, end)} of {@code text} into {@code out}. The style
	 * flags hold the formatting in effect for this range.
	 */
	private static void parseRange(String text, int start, int end,
		boolean bold, boolean italic, boolean strike,
		StringBuilder buf, List<Span> out)
	{
		int i = start;
		while (i < end)
		{
			// Check "**" before "*" so bold wins over two italic toggles.
			int boldClose = !bold ? findClose(text, i, end, "**") : -1;
			if (boldClose >= 0)
			{
				flush(buf, out, bold, italic, strike);
				parseRange(text, i + 2, boldClose, true, italic, strike, buf, out);
				i = boldClose + 2;
				continue;
			}

			int strikeClose = !strike ? findClose(text, i, end, "~~") : -1;
			if (strikeClose >= 0)
			{
				flush(buf, out, bold, italic, strike);
				parseRange(text, i + 2, strikeClose, bold, italic, true, buf, out);
				i = strikeClose + 2;
				continue;
			}

			char c = text.charAt(i);
			if (!italic && (c == '*' || c == '_'))
			{
				int italicClose = findClose(text, i, end, String.valueOf(c));
				if (italicClose >= 0)
				{
					flush(buf, out, bold, italic, strike);
					parseRange(text, i + 1, italicClose, bold, true, strike, buf, out);
					i = italicClose + 1;
					continue;
				}
			}

			buf.append(c);
			i++;
		}
		flush(buf, out, bold, italic, strike);
	}

	/**
	 * Returns the index of the closing {@code marker} for the opener at
	 * {@code openStart}, or {@code -1} when there is none or the content between
	 * the markers is empty.
	 */
	private static int findClose(String text, int openStart, int end, String marker)
	{
		int len = marker.length();
		if (openStart + len > end || !text.startsWith(marker, openStart))
		{
			return -1;
		}
		int contentStart = openStart + len;
		for (int j = contentStart; j + len <= end; j++)
		{
			if (text.startsWith(marker, j))
			{
				return j > contentStart ? j : -1;
			}
		}
		return -1;
	}

	private static void flush(StringBuilder buf, List<Span> out,
		boolean bold, boolean italic, boolean strike)
	{
		if (buf.length() > 0)
		{
			out.add(new Span(buf.toString(), bold, italic, strike));
			buf.setLength(0);
		}
	}

	/**
	 * Strips inline markup and reduces each {@code [label](url)} link to its label, returning
	 * the visible text for contexts that cannot render formatting, such as Graphics2D overlays.
	 * Markup inside a label is stripped too.
	 *
	 * @param text input markup (may be {@code null})
	 * @return the text with markers removed and links reduced to their labels; unchanged when
	 *         it has neither
	 */
	public static String stripMarkup(String text)
	{
		if (text == null || text.isEmpty())
		{
			return text;
		}
		// Links first, so underscores in a URL are not read as italic markers. A label is still
		// parsed as markup.
		text = MarkdownLinks.LINK.matcher(text).replaceAll("$1");
		if (text.indexOf('*') < 0 && text.indexOf('_') < 0 && text.indexOf('~') < 0)
		{
			return text;
		}
		StringBuilder sb = new StringBuilder(text.length());
		for (Span s : parse(text))
		{
			sb.append(s.text);
		}
		return sb.toString();
	}

	/**
	 * A step instruction as one line of plain text, for the game overlay and notifications:
	 * {@link #stripMarkup} without the trailing links, which only the side panel can open.
	 *
	 * @param instruction the instruction (may be {@code null})
	 * @return the plain text; empty for {@code null}
	 */
	public static String plainInstruction(String instruction)
	{
		return stripMarkup(MarkdownLinks.splitTrailing(instruction).body);
	}
}

package com.stepwise.panel;

import com.stepwise.engine.BirdhouseTracker;
import com.stepwise.engine.CoreEngine;
import com.stepwise.engine.KingdomTracker;
import com.stepwise.engine.TearsOfGuthixTracker;
import com.stepwise.model.PlayerState;
import com.stepwise.snapshot.DashboardSnapshot;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.FontManager;

/**
 * "Timers" section: one collapsed row for bird houses, the weekly Tears of Guthix row, and
 * the Miscellania row.
 *
 * <p>The bird house row shares the countdown and colour of Stepwise's bird house InfoBox. Only
 * the InfoBox's tooltip names each house's tier. The countdown is the longest remaining of the
 * four houses, because the player goes when the whole run is ready. The colour walks green
 * (none ready), yellow-green (some ready), gold (all ready).
 *
 * <p>No var carries the Tears of Guthix wait, so
 * {@link com.stepwise.engine.TearsOfGuthixTracker} reads it from what the player sees: a
 * visit, Juna's lines and the Quest Journal page. Juna's second gate, new adventures since
 * the last visit, can keep her shut after the clock reads ready, so while it stands it takes
 * the row's second line and colour.
 */
public class TimerPanel extends JPanel
{
	private static final Color COLOR_HEADER = PanelColors.HEADER;
	private static final Color COLOR_READY = new Color(255, 200, 50);
	private static final Color COLOR_GROWING = new Color(100, 160, 100);
	private static final Color COLOR_PARTIAL = new Color(180, 200, 90);
	private static final Color COLOR_SUBTEXT = new Color(140, 140, 140);

	private static final String TEARS_NAME = "Tears of Guthix";

	/** Juna's stone bowl, the item the minigame hands you. */
	private static final int TEARS_ICON = ItemID.TOG_BOWL;

	private static final String TEARS_READY = "Ready";

	private static final String TEARS_UNKNOWN = "Check journal";

	/** Shown when the week is up but Juna is still owed new adventures. */
	private static final String TEARS_ADVENTURES = "Needs XP";

	private static final String KINGDOM_DUE = "Visit";

	/** Thirty days without a visit: the kingdom has stopped until the player returns. */
	private static final String KINGDOM_PAUSED = "Paused";

	private static final DateTimeFormatter TIME_FMT =
		DateTimeFormatter.ofPattern("HH:mm", Locale.ROOT).withZone(ZoneId.systemDefault());

	public TimerPanel()
	{
		PanelSections.column(this);
	}

	public void rebuild(DashboardSnapshot snapshot, CoreEngine coreEngine, IconProvider iconProvider)
	{
		removeAll();

		List<Row> rows = coreEngine == null ? new ArrayList<>() : collectRows(snapshot, coreEngine);
		if (rows.isEmpty())
		{
			setVisible(false);
			revalidate();
			repaint();
			return;
		}

		setVisible(true);
		setBorder(PanelSections.gap(PanelSections.SECTION_GAP));
		add(PanelSections.header("Timers"));

		JPanel container = PanelSections.box();

		for (int i = 0; i < rows.size(); i++)
		{
			if (i > 0)
			{
				container.add(PanelColors.divider());
			}
			container.add(buildTimerRow(rows.get(i), iconProvider));
		}
		add(container);

		revalidate();
		repaint();
	}

	private List<Row> collectRows(DashboardSnapshot snapshot, CoreEngine coreEngine)
	{
		List<Row> rows = new ArrayList<>();
		long nowSec = Instant.now().getEpochSecond();

		// Errands sort first: Tears of Guthix when it is a trip worth making, then a due
		// Miscellania. Bird houses follow, then whichever of the other two is still waiting.
		// Read once here, because the client thread can stamp a visit mid-pass, and two reads
		// could render the row twice or not at all.
		PlayerState player = coreEngine.getPlayerState();
		TearsOfGuthixTracker.Reading tears =
			TearsOfGuthixTracker.questCompleted(player)
				? coreEngine.getTearsOfGuthixTracker().readAt(nowSec,
					player.getTotalXp(), player.getQuestPoints())
				: null;

		if (tears != null && tearsIsAnErrand(tears))
		{
			rows.add(tearsOfGuthixRow(tears));
		}

		// Read once for the same reason as Tears of Guthix.
		KingdomTracker.Reading kingdom =
			KingdomTracker.questCompleted(player)
				? coreEngine.getKingdomTracker().readAt(nowSec,
					KingdomTracker.royalTroubleCompleted(player))
				: null;
		String hardwoodAdvice = kingdom != null && snapshot != null
			? coreEngine.getKingdomTracker().hardwoodAdvice(snapshot.getKingdomHardwood(),
				KingdomTracker.royalTroubleCompleted(player))
			: null;

		List<KingdomTracker.Yield> kingdomEstimate = kingdom != null
			? coreEngine.getKingdomTracker().collectionEstimate(kingdom.getPool())
			: null;

		if (kingdom != null && kingdom.isDue())
		{
			rows.add(kingdomRow(kingdom, hardwoodAdvice, kingdomEstimate));
		}

		Row birdhouseRow = birdhouseClassRow(coreEngine.getBirdhouseTracker(), nowSec);
		if (birdhouseRow != null)
		{
			rows.add(birdhouseRow);
		}

		if (tears != null && !tearsIsAnErrand(tears))
		{
			rows.add(tearsOfGuthixRow(tears));
		}

		if (kingdom != null && !kingdom.isDue())
		{
			rows.add(kingdomRow(kingdom, hardwoodAdvice, kingdomEstimate));
		}

		return rows;
	}

	/**
	 * The Kingdom of Miscellania row. Never null.
	 *
	 * <p>Gold once the trip is due or the kingdom has paused. Approval and coffer take the second line because together
	 * they set the daily yield, so the player sees what is slipping before the row turns gold.
	 * Advice about the hardwood workers takes that line instead while it stands: a wrong setting
	 * at collection costs the whole pool, and the fix is one click at the advisor.
	 *
	 * <p>The tooltip estimates what collecting now would give, and keeps approval and coffer
	 * readable while advice holds the second line.
	 *
	 * @param hardwoodAdvice what to change on the hardwood workers, or null when nothing needs
	 *                       changing
	 * @param estimate       what collecting now would give, possibly empty
	 */
	private Row kingdomRow(KingdomTracker.Reading kingdom, String hardwoodAdvice,
		List<KingdomTracker.Yield> estimate)
	{
		String summary = kingdomSummary(kingdom.getApprovalPercent(), kingdom.getCoffer(),
			kingdom.isCofferLow());
		String status;
		Color color;
		if (kingdom.isPaused())
		{
			status = KINGDOM_PAUSED;
			color = COLOR_READY;
		}
		else if (kingdom.isDue())
		{
			status = KINGDOM_DUE;
			color = COLOR_READY;
		}
		else
		{
			status = daysStatus(kingdom.getDaysUntilDue());
			color = COLOR_GROWING;
		}
		String subtext = hardwoodAdvice != null ? hardwoodAdvice : summary;
		String displaced = hardwoodAdvice != null ? summary : null;
		// Mahogany logs, what the guide keeps the kingdom producing.
		return new Row("Miscellania", ItemID.MAHOGANY_LOGS, status, color, subtext, null)
			.withTooltip(kingdomTooltip(displaced, estimate));
	}

	/**
	 * The row's tooltip: the summary when advice displaced it, then what collecting now would give.
	 * Null when there is nothing to say.
	 */
	static String kingdomTooltip(String displacedSummary, List<KingdomTracker.Yield> estimate)
	{
		boolean hasEstimate = estimate != null && !estimate.isEmpty();
		if (displacedSummary == null && !hasEstimate)
		{
			return null;
		}
		StringBuilder tip = new StringBuilder("<html>");
		if (displacedSummary != null)
		{
			tip.append(displacedSummary);
		}
		if (hasEstimate)
		{
			if (displacedSummary != null)
			{
				tip.append("<br>");
			}
			tip.append("Collecting now gives about:");
			for (KingdomTracker.Yield item : estimate)
			{
				tip.append("<br>").append(String.format(Locale.ROOT, "%,d", item.getQuantity()))
					.append(' ').append(item.getItem());
			}
		}
		return tip.append("</html>").toString();
	}

	/**
	 * "Approval 96% · 6.2M gp", the coffer's balance, with ", low" once it can no longer pay
	 * full wages. The line does not wrap, and "coffer" would push the longest reading past
	 * the row's width.
	 */
	static String kingdomSummary(int approvalPercent, int coffer, boolean cofferLow)
	{
		return "Approval " + approvalPercent + "% · " + compactGp(coffer) + " gp"
			+ (cofferLow ? ", low" : "");
	}

	/** Coins rounded down: 6_250_000 → "6.2M", 400_000 → "400k". Rounding down never flatters. */
	static String compactGp(int gp)
	{
		if (gp >= 1_000_000)
		{
			int tenths = gp / 100_000;
			return (tenths / 10) + (tenths % 10 == 0 ? "" : "." + (tenths % 10)) + "M";
		}
		return gp >= 1_000 ? (gp / 1_000) + "k" : Integer.toString(gp);
	}

	/**
	 * Whether the Tears of Guthix row is a trip the player can make right now, which decides
	 * where it sorts. Both insertion points use this one predicate so the row lands exactly once.
	 *
	 * <p>A finished clock with Juna's adventures gate still standing is not an errand: she
	 * would turn the player away.
	 */
	static boolean tearsIsAnErrand(TearsOfGuthixTracker.Reading tears)
	{
		return tears.isReady() && !tears.isAdventuresNeeded();
	}

	/**
	 * The weekly Tears of Guthix row. Never null.
	 *
	 * <p>No "mark done" action, because the visit is observed rather than declared. Until the
	 * tracker has a reading the row points at the Quest Journal, which states the exact wait.
	 *
	 * <p>A wait in whole days has no honest clock time, so the row has a second line only
	 * for the XP or quest point Juna is still owed.
	 */
	private Row tearsOfGuthixRow(TearsOfGuthixTracker.Reading tears)
	{
		String adventures = tears.isAdventuresNeeded() ? tearsAdventures(tears.getXpToGo()) : null;

		if (tears.isReady())
		{
			// Ready but gated must not be gold, or the player walks to the Chasm of Tears
			// for nothing. Grey marks "nothing to do here".
			return adventures == null
				? new Row(TEARS_NAME, TEARS_ICON, TEARS_READY, COLOR_READY, null, null)
				: new Row(TEARS_NAME, TEARS_ICON, TEARS_ADVENTURES, COLOR_SUBTEXT, adventures, null);
		}

		// An unread clock can still carry a gate, because Juna's gate message names no day
		// count. The row then shows both.
		if (tears.isUnknown())
		{
			return new Row(TEARS_NAME, TEARS_ICON, TEARS_UNKNOWN, COLOR_SUBTEXT, adventures, null);
		}

		return new Row(TEARS_NAME, TEARS_ICON, daysStatus(tears.getDaysRemaining()), COLOR_GROWING,
			adventures, tears.getProgress());
	}

	/**
	 * What Juna is still owed, as the row's second line. Names both options, since a quest
	 * point is often cheaper. The line does not wrap, so it is short enough for the row.
	 */
	static String tearsAdventures(long xpToGo)
	{
		return xpToGo <= 0
			? "1 quest point to go"
			: String.format(Locale.ROOT, "%,d XP or 1 quest point", xpToGo);
	}

	/**
	 * The countdown label for a day-valued wait: "3d", with no hours, because the wait
	 * moves only once a day.
	 */
	static String daysStatus(int daysRemaining)
	{
		return daysRemaining + "d";
	}

	/** One collapsed row for all seeded bird houses, or null when none are seeded. */
	static Row birdhouseClassRow(BirdhouseTracker birdhouses, long nowSec)
	{
		int seeded = 0;
		int ready = 0;
		long longestRemaining = 0;
		long latestReadyAt = 0;
		StringBuilder tip = new StringBuilder("<html>Bird houses");

		for (BirdhouseTracker.BirdhouseSpace space : BirdhouseTracker.BirdhouseSpace.values())
		{
			if (!birdhouses.isSeeded(space))
			{
				continue;
			}
			seeded++;
			long remaining = birdhouses.remainingSeconds(space, nowSec);
			long readyAt = birdhouses.readyAtEpochSeconds(space);
			if (remaining <= 0)
			{
				ready++;
			}
			if (remaining > longestRemaining)
			{
				longestRemaining = remaining;
			}
			if (readyAt > latestReadyAt)
			{
				latestReadyAt = readyAt;
			}
			tip.append("<br>").append(space.getLabel()).append(": ")
				.append(BirdhouseTracker.timeLeft(remaining));
		}

		if (seeded == 0)
		{
			return null;
		}
		tip.append("</html>");

		String counts = ready + "/" + seeded + " ready";
		String status = longestRemaining <= 0 ? "Ready" : ((longestRemaining + 59) / 60) + "m";
		Color color = longestRemaining <= 0 ? COLOR_READY
			: (ready > 0 ? COLOR_PARTIAL : COLOR_GROWING);
		// The finish time only while it is still ahead: once every house is ready it has passed.
		String doneAt = longestRemaining > 0
			? counts + " · all ready at " + TIME_FMT.format(Instant.ofEpochSecond(latestReadyAt))
			: counts;
		// The bar clamps a wait longer than one fill to empty.
		double progress = 1.0 - (double) longestRemaining / BirdhouseTracker.FILL_DURATION_SECONDS;
		// The plain (logs) bird house.
		return new Row("Bird houses", ItemID.BIRDHOUSE_NORMAL, status, color, doneAt, progress)
			.withTooltip(tip.toString());
	}

	private JPanel buildTimerRow(Row row, IconProvider iconProvider)
	{
		JPanel outer = new JPanel(new BorderLayout(6, 3));
		outer.setOpaque(false);
		outer.setAlignmentX(LEFT_ALIGNMENT);
		outer.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));

		ImageIcon icon = iconProvider != null
			? iconProvider.getItemIcon(row.itemId, IconProvider.TIMER_ICON_SIZE) : null;
		if (icon != null)
		{
			outer.add(new JLabel(icon), BorderLayout.WEST);
		}

		JPanel textBlock = new JPanel(new GridLayout(row.subtext != null ? 2 : 1, 1, 0, 0));
		textBlock.setOpaque(false);

		JPanel line1 = new JPanel(new BorderLayout(6, 0));
		line1.setOpaque(false);
		JTextArea nameText = StepCardPanel.textArea(row.name,
			COLOR_HEADER, FontManager.getRunescapeSmallFont());
		nameText.setLineWrap(false);
		line1.add(nameText, BorderLayout.CENTER);
		JTextArea statusText = StepCardPanel.textArea(row.status,
			row.color, FontManager.getRunescapeSmallFont());
		statusText.setLineWrap(false);
		line1.add(statusText, BorderLayout.EAST);
		textBlock.add(line1);

		JTextArea subText = null;
		if (row.subtext != null)
		{
			subText = StepCardPanel.textArea(row.subtext,
				COLOR_SUBTEXT, FontManager.getRunescapeSmallFont());
			subText.setLineWrap(false);
			textBlock.add(subText);
		}

		// The tooltip goes on the container AND the text areas: JTextArea children swallow
		// mouse events, so setting it only on the outer panel would leave dead zones over
		// the text.
		if (row.tooltip != null)
		{
			for (JComponent part : new JComponent[]{outer, nameText, statusText, subText})
			{
				if (part != null)
				{
					part.setToolTipText(row.tooltip);
				}
			}
		}

		outer.add(textBlock, BorderLayout.CENTER);

		boolean bar = showsBar(row.progress);
		if (bar)
		{
			outer.add(new TimerProgressBar(row.progress), BorderLayout.SOUTH);
		}

		// BoxLayout enforces this maximum to the pixel, so height must follow the line count
		// and the bar independently or a two-line row without a bar clips its second line.
		int textHeight = row.subtext != null ? 40 : 26;
		outer.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			textHeight + (bar ? 8 : 0)));
		return outer;
	}

	/** Whether a row draws its progress bar: only while filling, since "Ready" says the rest. */
	static boolean showsBar(Double progress)
	{
		return progress != null && progress < 1.0;
	}

	/**
	 * One timer row, headed by an item's sprite. Subtext is the optional second line. Progress
	 * is set only for rows with a fill duration.
	 */
	static final class Row
	{
		final String name;
		final int itemId;
		final String status;
		final Color color;
		final String subtext;
		final Double progress;
		/** Optional, HTML. */
		String tooltip;

		Row(String name, int itemId, String status, Color color, String subtext, Double progress)
		{
			this.name = name;
			this.itemId = itemId;
			this.status = status;
			this.color = color;
			this.subtext = subtext;
			this.progress = progress;
		}

		Row withTooltip(String tooltip)
		{
			this.tooltip = tooltip;
			return this;
		}
	}
}

package com.stepwise.panel;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import javax.swing.JComponent;

/**
 * A thin horizontal progress bar whose fill grows left to right. Progress is fixed at
 * construction, so each rebuild makes a new bar.
 */
class TimerProgressBar extends JComponent
{
	private static final Color TRACK = new Color(48, 48, 48);
	private static final Color FILL_GROWING = new Color(100, 160, 100);
	private static final int HEIGHT = 5;

	private final float progress;
	private final Color fill;

	/** A timer's bar, green while it fills. Clamps progress to [0, 1]. */
	TimerProgressBar(double progress)
	{
		this(progress, FILL_GROWING);
	}

	/**
	 * A bar in the given colour, for a measure with no good or bad end, such as how far
	 * through the guide an account is. Clamps progress to [0, 1].
	 */
	TimerProgressBar(double progress, Color fill)
	{
		this.progress = (float) Math.max(0.0, Math.min(1.0, progress));
		this.fill = fill;
		setOpaque(false);
		setPreferredSize(new Dimension(0, HEIGHT));
		setMinimumSize(new Dimension(0, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		int w = getWidth();
		int h = getHeight();
		g.setColor(TRACK);
		g.fillRect(0, 0, w, h);
		g.setColor(fill);
		g.fillRect(0, 0, Math.round(w * progress), h);
	}
}

package com.stepwise.panel;

import com.stepwise.engine.CoreEngine;
import com.stepwise.snapshot.CompletionCriterion;
import com.stepwise.snapshot.CriterionProgress;
import com.stepwise.snapshot.DashboardSnapshot;
import com.stepwise.snapshot.DetailedStep;
import com.stepwise.snapshot.NextStep;
import java.awt.Color;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.client.ui.FontManager;

/**
 * Shows upcoming steps as compact rows: icons, instruction, and a progress count when the
 * step has one. The icons and the count come from the detailed steps' criteria.
 */
public class UpcomingPanel extends JPanel
{
	private static final Color COLOR_ONE_LINER = PanelColors.HEADER;
	private static final Color COLOR_SECTION = PanelColors.SUBTLE.brighter();

	/** Icons drawn per row. More squeeze the instruction at the sidebar's width. */
	private static final int MAX_ICONS = 2;

	/** The active step's section. Rows in the same section omit their breadcrumb. */
	private String currentSection;

	/**
	 * The progress counts on screen, one per detailed step, null where the step has none.
	 * Updated in place on a same-structure refresh, so an XP drop does not rebuild the
	 * rows and re-wrap their text.
	 */
	private final List<JLabel> progressLabels = new ArrayList<>();
	/** Rebuilds the upcoming list only when its structure changes. */
	private final RebuildGuard guard = new RebuildGuard();

	public UpcomingPanel()
	{
		PanelSections.column(this);
	}

	public void rebuild(DashboardSnapshot snapshot, CoreEngine coreEngine, IconProvider iconProvider)
	{
		if (snapshot == null)
		{
			removeAll();
			progressLabels.clear();
			guard.reset();
			setVisible(false);
			return;
		}

		if (snapshot.getGuidePosition() != null)
		{
			currentSection = snapshot.getGuidePosition().getSection();
		}

		List<DetailedStep> detailed = snapshot.getNextDetailed();
		if (detailed == null)
		{
			detailed = List.of();
		}

		List<NextStep> oneLiners = snapshot.getNextSteps();

		if (!guard.shouldRebuild(structureSignature(detailed, oneLiners)))
		{
			for (int i = 0; i < progressLabels.size() && i < detailed.size(); i++)
			{
				JLabel label = progressLabels.get(i);
				if (label != null)
				{
					label.setText(progressText(detailed.get(i).getCriteria()));
				}
			}
			return;
		}

		removeAll();
		progressLabels.clear();

		boolean hasDetailed = !detailed.isEmpty();
		boolean hasOneLiners = oneLiners != null && !oneLiners.isEmpty();

		if (!hasDetailed && !hasOneLiners)
		{
			setVisible(false);
			revalidate();
			repaint();
			return;
		}

		// Visibility is set only on a rebuild: an unchanged snapshot keeps whatever the last
		// rebuild decided, so an empty list is not shown again.
		setVisible(true);
		setBorder(PanelSections.gap(PanelSections.SECTION_GAP));
		add(PanelSections.header("Upcoming"));

		JPanel container = PanelSections.box();

		boolean needsDivider = false;

		for (DetailedStep step : detailed)
		{
			if (needsDivider)
			{
				container.add(PanelColors.divider());
			}

			String section = step.getSection();
			if (section != null && section.equals(currentSection))
			{
				section = null;
			}
			else if (section != null)
			{
				// Written as the header writes the current section, "2.2 · Name".
				section = StepwisePanel.formatSectionLabel(TextMarkup.stripMarkup(section));
			}

			String progress = progressText(step.getCriteria());
			JLabel progressLabel = progress.isEmpty() ? null : progressLabel(progress);
			progressLabels.add(progressLabel);
			container.add(buildRow(section, iconsOf(step.getCriteria(), iconProvider),
				step.getInstruction(), progressLabel));
			needsDivider = true;
		}

		if (hasOneLiners)
		{
			for (NextStep step : oneLiners)
			{
				if (needsDivider)
				{
					container.add(PanelColors.divider());
				}
				container.add(buildRow(null, iconsOf(step, iconProvider),
					step.getInstruction(), null));
				needsDivider = true;
			}
		}

		add(container);

		revalidate();
		repaint();
	}

	/**
	 * Structural signature for the upcoming list. Detailed rows are keyed by step ID and
	 * the shape of their progress count, not its value. One-liners are keyed by their text.
	 */
	private static List<String> structureSignature(List<DetailedStep> detailed,
		List<NextStep> oneLiners)
	{
		List<String> sig = new ArrayList<>();
		for (DetailedStep step : detailed)
		{
			// The count's source criterion and length set the label's width, which wraps the
			// instruction beside it. A change to either needs a rebuild. Same-length values
			// update in place.
			sig.add("d:" + step.getStepId() + ":" + progressSource(step.getCriteria())
				+ ":" + progressText(step.getCriteria()).length());
		}
		if (oneLiners != null)
		{
			for (NextStep step : oneLiners)
			{
				sig.add("o:" + step.getInstruction());
			}
		}
		return sig;
	}

	/**
	 * How far along a step is, from its first criterion that is still counting: a level
	 * for a skill, a count for anything else. Empty when nothing on the step counts.
	 */
	static String progressText(List<CompletionCriterion> criteria)
	{
		int source = progressSource(criteria);
		if (source < 0)
		{
			return "";
		}
		CriterionProgress p = criteria.get(source).getProgress();
		// Show a skill in levels until the level is reached. After that an XP target
		// remains, and "50/50" would read as done.
		if (p.getTargetLevel() > 0 && p.getCurrentLevel() < p.getTargetLevel())
		{
			return p.getCurrentLevel() + "/" + p.getTargetLevel();
		}
		// Abbreviated so a large gold or item count does not squeeze the instruction.
		return RouteDeficitPanel.compact(p.getCurrent()) + "/" + RouteDeficitPanel.compact(p.getRequired());
	}

	/** The first criterion still counting towards something, or -1 when none is. */
	private static int progressSource(List<CompletionCriterion> criteria)
	{
		if (criteria == null)
		{
			return -1;
		}
		for (int i = 0; i < criteria.size(); i++)
		{
			if (StepCardPanel.isCounting(criteria.get(i)))
			{
				return i;
			}
		}
		return -1;
	}

	private static JLabel progressLabel(String text)
	{
		JLabel label = PanelSections.smallLabel(text, COLOR_ONE_LINER);
		label.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
		return label;
	}

	/** One icon per distinct criterion picture, at most {@link #MAX_ICONS}. */
	private static List<ImageIcon> iconsOf(List<CompletionCriterion> criteria,
		IconProvider iconProvider)
	{
		List<String[]> live = new ArrayList<>();
		List<String[]> all = new ArrayList<>();
		if (criteria != null)
		{
			for (CompletionCriterion criterion : criteria)
			{
				String[] hint = {criterion.getIconType(), criterion.getIconKey()};
				all.add(hint);
				if (!criterion.isMet() && !criterion.isWaived())
				{
					live.add(hint);
				}
			}
		}
		// Prefer unmet criteria. Fall back to all of them when every one is met.
		return icons(live.isEmpty() ? all : live, iconProvider);
	}

	private static List<ImageIcon> iconsOf(NextStep step, IconProvider iconProvider)
	{
		List<String[]> hints = new ArrayList<>();
		if (step.getIconHints() != null)
		{
			for (NextStep.IconHint hint : step.getIconHints())
			{
				hints.add(new String[]{hint.getIconType(), hint.getIconKey()});
			}
		}
		return icons(hints, iconProvider);
	}

	private static List<ImageIcon> icons(List<String[]> hints, IconProvider iconProvider)
	{
		List<ImageIcon> icons = new ArrayList<>();
		if (iconProvider == null)
		{
			return icons;
		}
		// Dedupe by icon type and key, so three criteria on one item draw one icon.
		Set<String> seen = new LinkedHashSet<>();
		for (String[] hint : hints)
		{
			if (hint[0] == null || !seen.add(hint[0] + ":" + hint[1]))
			{
				continue;
			}
			ImageIcon icon = iconProvider.getIcon(hint[0], hint[1], false);
			if (icon != null)
			{
				icons.add(icon);
				if (icons.size() == MAX_ICONS)
				{
					break;
				}
			}
		}
		return icons;
	}

	private static JPanel buildRow(String section, List<ImageIcon> icons, String instruction,
		JLabel progress)
	{
		JPanel row = new JPanel(new GridBagLayout());
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 4));
		row.setAlignmentX(LEFT_ALIGNMENT);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridy = 0;
		gbc.anchor = GridBagConstraints.CENTER;

		if (section != null)
		{
			JTextArea eyebrow = StepCardPanel.textArea(section, COLOR_SECTION,
				FontManager.getRunescapeSmallFont());
			gbc.gridx = 0;
			gbc.gridwidth = GridBagConstraints.REMAINDER;
			gbc.weightx = 1.0;
			gbc.fill = GridBagConstraints.HORIZONTAL;
			row.add(eyebrow, gbc);
			gbc.gridy = 1;
			gbc.gridwidth = 1;
		}

		int col = 0;
		for (ImageIcon icon : icons)
		{
			JLabel iconLabel = new JLabel(icon);
			iconLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 3));
			gbc.gridx = col++;
			gbc.weightx = 0;
			gbc.fill = GridBagConstraints.NONE;
			row.add(iconLabel, gbc);
		}

		JTextArea instrText = StepCardPanel.textArea(
			instruction != null ? instruction : "", COLOR_ONE_LINER,
			FontManager.getRunescapeSmallFont());
		gbc.gridx = col++;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		row.add(instrText, gbc);

		if (progress != null)
		{
			gbc.gridx = col;
			gbc.weightx = 0;
			gbc.fill = GridBagConstraints.NONE;
			row.add(progress, gbc);
		}

		return row;
	}
}

package com.stepwise.persistence;

import net.runelite.client.config.ConfigManager;

/**
 * The slice of {@link ConfigManager} that {@link StepwisePersistence} reads and writes.
 *
 * <p>Stepwise persists only pre-encoded strings, so this needs none of ConfigManager's typed
 * overloads.
 */
public interface ConfigStore {

    String getRSProfileConfiguration(String group, String key);

    void setRSProfileConfiguration(String group, String key, String value);

    void unsetRSProfileConfiguration(String group, String key);

    String getConfiguration(String group, String key);

    void setConfiguration(String group, String key, String value);

    void unsetConfiguration(String group, String key);

    /**
     * The key of the RS profile that the RS-profile methods read and write, or null when
     * there is none. RuneLite has no RS profile until an account logs in.
     */
    String rsProfileKey();

    /** Whether every write is dropped, as in {@link #readOnly}'s stores. */
    default boolean isReadOnly() {
        return false;
    }

    /** The live client's store. */
    static ConfigStore of(ConfigManager configManager) {
        return new ConfigStore() {
            @Override
            public String getRSProfileConfiguration(String group, String key) {
                return configManager.getRSProfileConfiguration(group, key);
            }

            @Override
            public void setRSProfileConfiguration(String group, String key, String value) {
                configManager.setRSProfileConfiguration(group, key, value);
            }

            @Override
            public void unsetRSProfileConfiguration(String group, String key) {
                configManager.unsetRSProfileConfiguration(group, key);
            }

            @Override
            public String getConfiguration(String group, String key) {
                return configManager.getConfiguration(group, key);
            }

            @Override
            public void setConfiguration(String group, String key, String value) {
                configManager.setConfiguration(group, key, value);
            }

            @Override
            public void unsetConfiguration(String group, String key) {
                configManager.unsetConfiguration(group, key);
            }

            @Override
            public String rsProfileKey() {
                return configManager.getRSProfileKey();
            }
        };
    }

    /**
     * A named RS profile's keys, readable while no account is logged in, with every write
     * dropped.
     *
     * <p>RS-profile reads go to {@code profileKey} rather than the current profile, which is
     * null at the login screen. Global reads pass through.
     */
    static ConfigStore readOnly(ConfigManager configManager, String profileKey) {
        return ReadOnlyConfigStore.over(configManager::getConfiguration,
                configManager::getConfiguration, profileKey);
    }
}

package com.stepwise.persistence;

import java.util.function.BiFunction;

/**
 * A {@link ConfigStore} that drops every write, so code handed one can read an account's
 * saved state and cannot change it however it is written.
 */
abstract class ReadOnlyConfigStore implements ConfigStore {

    /** Reads one key of a named RS profile, as {@code ConfigManager}'s three-argument getter. */
    @FunctionalInterface
    interface ProfileReads {
        String get(String group, String profileKey, String key);
    }

    /**
     * RS-profile reads from {@code profileKey} through {@code profileReads}, global reads
     * through {@code globalReads}.
     */
    static ConfigStore over(ProfileReads profileReads, BiFunction<String, String, String> globalReads,
            String profileKey) {
        return new ReadOnlyConfigStore() {
            @Override
            public String getRSProfileConfiguration(String group, String key) {
                return profileReads.get(group, profileKey, key);
            }

            @Override
            public String getConfiguration(String group, String key) {
                return globalReads.apply(group, key);
            }

            @Override
            public String rsProfileKey() {
                return profileKey;
            }
        };
    }

    @Override
    public final boolean isReadOnly() {
        return true;
    }

    @Override
    public final void setRSProfileConfiguration(String group, String key, String value) {
        // Dropped.
    }

    @Override
    public final void unsetRSProfileConfiguration(String group, String key) {
        // Dropped.
    }

    @Override
    public final void setConfiguration(String group, String key, String value) {
        // Dropped.
    }

    @Override
    public final void unsetConfiguration(String group, String key) {
        // Dropped.
    }
}

package com.stepwise.persistence;

import com.google.gson.Gson;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSerializer;
import com.google.gson.reflect.TypeToken;
import com.stepwise.engine.BirdhouseTracker;
import com.stepwise.guide.StepId;
import com.stepwise.model.PlayerState;
import lombok.extern.slf4j.Slf4j;

import java.lang.reflect.Type;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Saves and restores Stepwise's state through a {@link ConfigStore}. Progress lives under the
 * RS profile so each OSRS account keeps its own; the welcome screen's last-session summary
 * lives under global keys, readable before any account logs in.
 */
@Slf4j
public class StepwisePersistence {

    private static final String CONFIG_GROUP = "stepwise";
    /** Appended to a key whose saved value did not parse, to keep that value aside. */
    static final String UNREADABLE_SUFFIX = ".unreadable";
    private static final String KEY_PLAYER_STATE = "playerState";
    private static final String KEY_COMPLETED_STEPS = "completedSteps";
    private static final String KEY_SKIPPED_STEPS = "skippedSteps";
    private static final String KEY_SUPPRESSED_STEPS = "suppressedSteps";
    private static final String KEY_RECENT_MANUAL_STEPS = "recentManualSteps";
    private static final String KEY_GUIDE_VERSION = "guideVersion";
    private static final String KEY_BIRDHOUSE_PREFIX = "birdhouse.";
    private static final String KEY_TEARS_OF_GUTHIX_RESET = "tearsOfGuthixReset";
    private static final String KEY_TEARS_OF_GUTHIX_ADVENTURES = "tearsOfGuthixAdventures";
    private static final String KEY_KINGDOM = "kingdom";
    // Regular (non-RS-profile) config keys, readable before login: the welcome screen's
    // "last session" summary.
    private static final String KEY_LAST_PLAYER = "lastPlayer";
    private static final String KEY_LAST_STEP_INDEX = "lastStepIndex";
    private static final String KEY_LAST_TOTAL_STEPS = "lastTotalSteps";
    private static final String KEY_LAST_CHAPTER = "lastChapter";
    private static final String KEY_LAST_COMPLETED = "lastCompletedCount";
    private static final String KEY_LAST_MINUTES_DONE = "lastMinutesDone";
    private static final String KEY_LAST_TOTAL_MINUTES = "lastTotalMinutes";
    private static final String KEY_LAST_RS_PROFILE = "lastRsProfile";

    private static final long SAVE_DEBOUNCE_MS = 5000;

    private final ConfigStore store;
    private final Gson gson;
    /** The RS profile current at the last player-state load; null when there was none. */
    private String loadedProfileKey;

    private long lastSaveTime;
    private boolean dirty;

    public StepwisePersistence(ConfigStore store, Gson base) {
        this.store = store;
        this.gson = buildGson(base);
    }

    /**
     * Build the Gson used for every persisted value.
     *
     * <p>The {@link Instant} adapter fixes the stored format. {@link PlayerState} holds
     * {@code Instant} fields, saved as epoch seconds. {@code base} is the client's injected
     * Gson, which registers its own {@code Instant} adapter; the one registered here is added
     * later and wins, so the saved format does not depend on the client's choice.
     */
    static Gson buildGson(Gson base) {
        return base.newBuilder()
                .registerTypeAdapter(StepId.class, new StepId.TypeAdapter())
                .registerTypeAdapter(Instant.class,
                        (JsonSerializer<Instant>) (src, type, ctx) ->
                                new JsonPrimitive(src.getEpochSecond()))
                .registerTypeAdapter(Instant.class,
                        (JsonDeserializer<Instant>) (json, type, ctx) ->
                                Instant.ofEpochSecond(json.getAsLong()))
                .create();
    }

    /**
     * Put back what Gson could not have set: the concurrent collections and the "not looked
     * at yet" sentinels.
     *
     * <p>{@link PlayerState} has no no-arg constructor, so Gson allocates it through
     * {@code Unsafe} and runs neither the constructor nor the field initializers: every
     * transient primitive arrives as 0. For the Slayer task count, 0 is a real reading (see
     * {@link PlayerState#SLAYER_TASK_COUNT_UNREAD}).
     *
     * <p>Login resolves the whole guide before the first tick samples the count. A restored
     * zero would make {@code noSlayerTask} latch for a player holding a task, and the retract
     * pass only reconsiders inventory conditions, so the latch would persist.
     *
     * <p>Null-tolerant: a profile with no saved state stays null.
     */
    static PlayerState finishRestore(PlayerState restored) {
        if (restored != null) {
            restored.useConcurrentCollections();
            restored.setSlayerTaskCount(PlayerState.SLAYER_TASK_COUNT_UNREAD);
            // Re-sum the derived skill totals rather than trusting whatever the JSON held.
            restored.recalculateTotalLevel();
        }
        return restored;
    }

    /**
     * Whether this persistence only reads, so whatever an engine over it saves is dropped:
     * the logged-out page's view of the last account.
     */
    public boolean isReadOnly() {
        return store != null && store.isReadOnly();
    }

    /** Whether the RS profile holds saved player state, without parsing it. */
    public boolean hasSavedPlayerState() {
        String json = store.getRSProfileConfiguration(CONFIG_GROUP, KEY_PLAYER_STATE);
        return json != null && !json.isEmpty();
    }

    public PlayerState loadPlayerState() {
        // Taken even when null. A brand-new account has no RS profile yet when it loads, and
        // keeping the previous account's key would pair this player's name with that profile.
        loadedProfileKey = store.rsProfileKey();
        return finishRestore(loadJson(KEY_PLAYER_STATE, PlayerState.class, null));
    }

    public Set<StepId> loadCompletedSteps() {
        return loadStepIdSet(KEY_COMPLETED_STEPS);
    }

    public Set<StepId> loadSkippedSteps() {
        return loadStepIdSet(KEY_SKIPPED_STEPS);
    }

    public Set<StepId> loadSuppressedSteps() {
        return loadStepIdSet(KEY_SUPPRESSED_STEPS);
    }

    /**
     * Persist the latest Mark Done and Skip clicks, newest first, so Recent can still offer
     * their Undo after a relog. Written on each click rather than with the debounced save,
     * since the list is a handful of ids.
     */
    public void saveRecentManualSteps(List<StepId> newestFirst) {
        if (newestFirst == null || newestFirst.isEmpty()) {
            store.unsetRSProfileConfiguration(CONFIG_GROUP, KEY_RECENT_MANUAL_STEPS);
            return;
        }
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_RECENT_MANUAL_STEPS,
                gson.toJson(newestFirst));
    }

    /**
     * The latest Mark Done and Skip clicks, newest first; empty when none are saved or the
     * saved list does not parse.
     */
    public List<StepId> loadRecentManualSteps() {
        return new ArrayList<>(loadJson(KEY_RECENT_MANUAL_STEPS,
                new TypeToken<List<StepId>>() {}.getType(), List.<StepId>of()));
    }

    public String loadGuideVersion() {
        return store.getRSProfileConfiguration(CONFIG_GROUP, KEY_GUIDE_VERSION);
    }

    /** One RS-profile key as a number, or 0 when it is absent or not a number. */
    private long loadLong(String key) {
        try {
            return Long.parseLong(store.getRSProfileConfiguration(CONFIG_GROUP, key));
        } catch (NumberFormatException e) {
            return 0L;
        }
    }

    /** Mark state dirty; the write happens on the next debounced save or forceSave(). */
    public void markDirty() {
        this.dirty = true;
    }

    /** Save if dirty and the debounce period has elapsed. Call from a periodic handler such as GameTick. */
    public void saveIfNeeded(PlayerState playerState, Set<StepId> completed,
            Set<StepId> skipped, Set<StepId> suppressed) {
        if (!dirty) {
            return;
        }
        long now = System.currentTimeMillis();
        if (now - lastSaveTime < SAVE_DEBOUNCE_MS) {
            return;
        }
        forceSave(playerState, completed, skipped, suppressed);
    }

    /** Save immediately, ignoring the debounce. Call on shutDown() or logout. */
    public void forceSave(PlayerState playerState, Set<StepId> completed,
            Set<StepId> skipped, Set<StepId> suppressed) {
        try {
            if (playerState != null) {
                store.setRSProfileConfiguration(CONFIG_GROUP, KEY_PLAYER_STATE,
                        gson.toJson(playerState));
            }
            store.setRSProfileConfiguration(CONFIG_GROUP, KEY_COMPLETED_STEPS,
                    gson.toJson(completed));
            store.setRSProfileConfiguration(CONFIG_GROUP, KEY_SKIPPED_STEPS,
                    gson.toJson(skipped));
            store.setRSProfileConfiguration(CONFIG_GROUP, KEY_SUPPRESSED_STEPS,
                    gson.toJson(suppressed));

            lastSaveTime = System.currentTimeMillis();
            dirty = false;
            log.debug("Stepwise state saved ({} completed, {} skipped, {} suppressed)",
                    completed.size(), skipped.size(), suppressed.size());
        } catch (Exception e) {
            log.warn("Failed to save Stepwise state", e);
        }
    }

    public void saveGuideVersion(String version) {
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_GUIDE_VERSION, version);
    }

    /**
     * Persist bird house timers per RS profile, one key per space, as
     * "varpValue:seededAtEpochSec". Clears all four first so an emptied house
     * does not linger with a stale timestamp.
     */
    public void saveBirdhouses(Collection<BirdhouseTracker.PersistedEntry> entries) {
        for (BirdhouseTracker.BirdhouseSpace space : BirdhouseTracker.BirdhouseSpace.values()) {
            store.unsetRSProfileConfiguration(CONFIG_GROUP,
                    KEY_BIRDHOUSE_PREFIX + space.getVarpId());
        }
        if (entries == null) {
            return;
        }
        for (BirdhouseTracker.PersistedEntry e : entries) {
            store.setRSProfileConfiguration(CONFIG_GROUP,
                    KEY_BIRDHOUSE_PREFIX + e.getVarpId(),
                    e.getVarpValue() + ":" + e.getSeededAtEpochSec());
        }
    }

    /** Load persisted bird house timers for the current RS profile. */
    public Collection<BirdhouseTracker.PersistedEntry> loadBirdhouses() {
        List<BirdhouseTracker.PersistedEntry> out = new ArrayList<>();
        for (BirdhouseTracker.BirdhouseSpace space : BirdhouseTracker.BirdhouseSpace.values()) {
            String stored = store.getRSProfileConfiguration(CONFIG_GROUP,
                    KEY_BIRDHOUSE_PREFIX + space.getVarpId());
            if (stored == null || stored.isEmpty()) {
                continue;
            }
            String[] parts = stored.split(":");
            if (parts.length != 2) {
                continue;
            }
            try {
                int varp = Integer.parseInt(parts[0]);
                long ts = Long.parseLong(parts[1]);
                out.add(new BirdhouseTracker.PersistedEntry(space.getVarpId(), varp, ts));
            } catch (NumberFormatException ex) {
                // ignore malformed entry
            }
        }
        return out;
    }

    /**
     * Persist when Juna next resets, per RS profile, as epoch seconds. The wait is a week,
     * so most of it passes while the player is logged out.
     */
    public void saveTearsOfGuthixReset(long nextAvailableEpochSec) {
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_TEARS_OF_GUTHIX_RESET,
                Long.toString(nextAvailableEpochSec));
    }

    /** Load Juna's next reset, or 0 when no visit has been recorded for this profile. */
    public long loadTearsOfGuthixReset() {
        return loadLong(KEY_TEARS_OF_GUTHIX_RESET);
    }

    /**
     * Persist the totals Juna's adventuring gate is measured against, as
     * {@code {totalXp, questPoints}}, or null to forget them.
     *
     * <p>The gate can outlast the weekly wait, and only asking Juna again would re-arm it.
     */
    public void saveTearsOfGuthixAdventures(long[] baseline) {
        if (baseline == null || baseline.length != 2) {
            store.unsetRSProfileConfiguration(CONFIG_GROUP, KEY_TEARS_OF_GUTHIX_ADVENTURES);
            return;
        }
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_TEARS_OF_GUTHIX_ADVENTURES,
                baseline[0] + ":" + baseline[1]);
    }

    /** Load that baseline, or null when nothing says the gate is unmet for this profile. */
    public long[] loadTearsOfGuthixAdventures() {
        return parseTearsOfGuthixAdventures(store.getRSProfileConfiguration(
                CONFIG_GROUP, KEY_TEARS_OF_GUTHIX_ADVENTURES));
    }

    /**
     * The stored baseline as {@code {totalXp, questPoints}}, or null for any value that is
     * not two numbers (absent, half-written or hand-edited).
     */
    static long[] parseTearsOfGuthixAdventures(String stored) {
        if (stored == null || stored.isEmpty()) {
            return null;
        }
        int split = stored.indexOf(':');
        if (split <= 0) {
            return null;
        }
        try {
            return new long[]{
                Long.parseLong(stored.substring(0, split)),
                Long.parseLong(stored.substring(split + 1)),
            };
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /**
     * Persist the Kingdom of Miscellania observation, per RS profile, in
     * {@link com.stepwise.engine.KingdomTracker#exportForPersist()}'s format; null forgets it.
     */
    public void saveKingdom(String observation) {
        if (observation == null) {
            store.unsetRSProfileConfiguration(CONFIG_GROUP, KEY_KINGDOM);
            return;
        }
        store.setRSProfileConfiguration(CONFIG_GROUP, KEY_KINGDOM, observation);
    }

    /** Load that observation, or null when none has been recorded for this profile. */
    public String loadKingdom() {
        return store.getRSProfileConfiguration(CONFIG_GROUP, KEY_KINGDOM);
    }

    /**
     * Save a session summary to regular (non-profile) config, so the welcome screen can
     * show it before login.
     *
     * @param minutesDone  minutes of play the completed steps account for
     * @param totalMinutes the guide's whole length in minutes of play, or null when the guide
     *                     data carries no timings
     */
    public void saveSessionSummary(String playerName, int stepIndex, int totalSteps,
            String chapter, int completedCount, double minutesDone, Double totalMinutes) {
        try {
            if (totalMinutes != null && totalMinutes > 0) {
                store.setConfiguration(CONFIG_GROUP, KEY_LAST_MINUTES_DONE,
                        String.valueOf(minutesDone));
                store.setConfiguration(CONFIG_GROUP, KEY_LAST_TOTAL_MINUTES,
                        String.valueOf(totalMinutes));
            } else {
                store.unsetConfiguration(CONFIG_GROUP, KEY_LAST_MINUTES_DONE);
                store.unsetConfiguration(CONFIG_GROUP, KEY_LAST_TOTAL_MINUTES);
            }
            // The profile the account's progress is saved under, so the logged-out page can
            // read it back while RuneLite has no current profile. The key captured when the
            // progress loaded, because the client may already have dropped its current profile
            // by the time a logout save runs. The loaded key wins; the client's current profile
            // is the fallback.
            String profileKey = loadedProfileKey != null ? loadedProfileKey : store.rsProfileKey();
            if (profileKey != null) {
                store.setConfiguration(CONFIG_GROUP, KEY_LAST_RS_PROFILE, profileKey);
            } else {
                // With neither key, the old key goes: it would name another account's progress.
                store.unsetConfiguration(CONFIG_GROUP, KEY_LAST_RS_PROFILE);
            }
            store.setConfiguration(CONFIG_GROUP, KEY_LAST_PLAYER, playerName);
            store.setConfiguration(CONFIG_GROUP, KEY_LAST_STEP_INDEX,
                    String.valueOf(stepIndex));
            store.setConfiguration(CONFIG_GROUP, KEY_LAST_TOTAL_STEPS,
                    String.valueOf(totalSteps));
            store.setConfiguration(CONFIG_GROUP, KEY_LAST_CHAPTER,
                    chapter != null ? chapter : "");
            store.setConfiguration(CONFIG_GROUP, KEY_LAST_COMPLETED,
                    String.valueOf(completedCount));
        } catch (Exception e) {
            log.warn("Failed to save session summary", e);
        }
    }

    /** Load the last session summary, or null if there is none or it fails to parse. */
    public SessionSummary loadSessionSummary() {
        try {
            String player = store.getConfiguration(CONFIG_GROUP, KEY_LAST_PLAYER);
            if (player == null || player.isEmpty()) {
                return null;
            }
            String stepIdxStr = store.getConfiguration(CONFIG_GROUP, KEY_LAST_STEP_INDEX);
            String totalStr = store.getConfiguration(CONFIG_GROUP, KEY_LAST_TOTAL_STEPS);
            String chapter = store.getConfiguration(CONFIG_GROUP, KEY_LAST_CHAPTER);
            String completedStr = store.getConfiguration(CONFIG_GROUP, KEY_LAST_COMPLETED);

            int stepIndex = stepIdxStr != null ? Integer.parseInt(stepIdxStr) : 0;
            int totalSteps = totalStr != null ? Integer.parseInt(totalStr) : 0;
            int completedCount = completedStr != null ? Integer.parseInt(completedStr) : 0;
            String minutesDoneStr = store.getConfiguration(CONFIG_GROUP, KEY_LAST_MINUTES_DONE);
            String totalMinutesStr = store.getConfiguration(CONFIG_GROUP, KEY_LAST_TOTAL_MINUTES);
            // Both or neither: a summary without timings has neither. A bad value
            // drops only the timings, so the welcome page falls back to the step count.
            Double minutesDone = null;
            Double totalMinutes = null;
            if (minutesDoneStr != null && totalMinutesStr != null) {
                try {
                    minutesDone = Double.parseDouble(minutesDoneStr);
                    totalMinutes = Double.parseDouble(totalMinutesStr);
                } catch (NumberFormatException e) {
                    minutesDone = null;
                    totalMinutes = null;
                }
            }

            String profileKey = store.getConfiguration(CONFIG_GROUP, KEY_LAST_RS_PROFILE);
            return new SessionSummary(player, stepIndex, totalSteps, chapter, completedCount,
                    minutesDone, totalMinutes,
                    profileKey == null || profileKey.isEmpty() ? null : profileKey);
        } catch (Exception e) {
            log.warn("Failed to load session summary", e);
            return null;
        }
    }

    /** Snapshot of the last session, readable without an RS profile. */
    @lombok.Value
    public static class SessionSummary {
        String playerName;
        int stepIndex;
        int totalSteps;
        String chapter;
        int completedCount;
        /** Minutes of play done; null when the summary has no timings. */
        Double minutesDone;
        /** The guide's whole length in minutes of play; null when the summary has no timings. */
        Double totalMinutes;
        /**
         * The RS profile the account's progress is saved under; null when the summary
         * records none.
         */
        String rsProfileKey;
    }

    private Set<StepId> loadStepIdSet(String key) {
        return new HashSet<>(loadJson(key, new TypeToken<Set<StepId>>() {}.getType(), Set.<StepId>of()));
    }

    /**
     * One RS-profile key parsed as JSON, or {@code empty} when it is absent or does not parse.
     *
     * <p>A value that does not parse is copied to {@code <key>.unreadable} before the account
     * starts fresh, so the next save cannot destroy it and it can still be recovered by hand.
     * The first copy is kept if one exists, since it holds the progress from before the
     * failure. Starting fresh loses only steps the game cannot show: the first-login
     * fast-forward places the player again from the account itself.
     */
    private <T> T loadJson(String key, Type type, T empty) {
        String json = store.getRSProfileConfiguration(CONFIG_GROUP, key);
        if (json == null || json.isEmpty()) {
            return empty;
        }
        try {
            T result = gson.fromJson(json, type);
            return result != null ? result : empty;
        } catch (RuntimeException e) {
            String backupKey = key + UNREADABLE_SUFFIX;
            if (store.getRSProfileConfiguration(CONFIG_GROUP, backupKey) == null) {
                store.setRSProfileConfiguration(CONFIG_GROUP, backupKey, json);
            }
            log.warn("Saved '{}' does not parse; kept it as '{}' and starting fresh", key, backupKey, e);
            return empty;
        }
    }
}

package com.stepwise.quest;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.stepwise.guide.GuideLoader;
import lombok.extern.slf4j.Slf4j;

import java.io.Reader;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Quest stage data from {@code quest_stages.json}, for progress bars. Each quest maps to a
 * sorted array of stage values (varbit/varplayer progression points) and optional stage
 * descriptions.
 *
 * <p>A progress bar's numerator is the stage index; its denominator is the array length
 * or the target stage's index.
 */
@Slf4j
public final class QuestStageData
{
	private static final String RESOURCE = "/com/stepwise/quest_stages.json";

	/** Quest name → sorted stage values. */
	private final Map<String, int[]> stageValues;

	/** Quest name → stage descriptions; absent for quests without descriptions. */
	private final Map<String, String[]> stageDescriptions;

	private QuestStageData(Map<String, int[]> stageValues, Map<String, String[]> stageDescriptions)
	{
		this.stageValues = stageValues;
		this.stageDescriptions = stageDescriptions;
	}

	/**
	 * Loads quest stage data from plugin resources. Returns an empty instance if the
	 * resource is missing or unreadable, so quest criteria get no progress bars.
	 */
	public static QuestStageData loadFromResource(Gson gson)
	{
		return GuideLoader.readResource(RESOURCE, reader -> parse(reader, gson),
			() -> new QuestStageData(Collections.emptyMap(), Collections.emptyMap()));
	}

	public static QuestStageData parse(Reader reader, Gson gson)
	{
		JsonObject root = gson.fromJson(reader, JsonObject.class);
		JsonArray quests = root.getAsJsonArray("quests");
		Map<String, int[]> values = new HashMap<>();
		Map<String, String[]> descriptions = new HashMap<>();

		for (JsonElement el : quests)
		{
			JsonObject quest = el.getAsJsonObject();
			String name = quest.get("questName").getAsString();
			JsonArray sv = quest.getAsJsonArray("stageValues");
			int[] stages = new int[sv.size()];
			for (int i = 0; i < sv.size(); i++)
			{
				stages[i] = sv.get(i).getAsInt();
			}
			values.put(name, stages);

			JsonArray stagesArr = quest.getAsJsonArray("stages");
			if (stagesArr != null && stagesArr.size() > 0)
			{
				String[] descs = new String[stagesArr.size()];
				for (int i = 0; i < stagesArr.size(); i++)
				{
					JsonObject stage = stagesArr.get(i).getAsJsonObject();
					JsonElement desc = stage.get("description");
					descs[i] = desc != null && !desc.isJsonNull() ? desc.getAsString() : null;
				}
				descriptions.put(name, descs);
			}
		}
		log.debug("Loaded quest stage data for {} quests", values.size());
		return new QuestStageData(values, descriptions);
	}

	/**
	 * Returns the index of the largest stage value at or below {@code currentValue}.
	 * Returns 0 if the quest is unknown or the value precedes the first stage.
	 */
	public int getStageIndex(String questName, int currentValue)
	{
		int[] stages = stageValues.get(questName);
		if (stages == null)
		{
			return 0;
		}
		int idx = Arrays.binarySearch(stages, currentValue);
		if (idx >= 0)
		{
			return idx;
		}
		int insertionPoint = -idx - 1;
		return Math.max(0, insertionPoint - 1);
	}

	/**
	 * Returns the total number of stages for a quest, or -1 if unknown.
	 */
	public int getTotalStages(String questName)
	{
		int[] stages = stageValues.get(questName);
		return stages != null ? stages.length : -1;
	}

	/**
	 * Returns the index of an exact stage value, or -1 if not found. Used for
	 * {@code questProgress} conditions.
	 */
	public int getTargetStageIndex(String questName, int targetValue)
	{
		int[] stages = stageValues.get(questName);
		if (stages == null)
		{
			return -1;
		}
		int idx = Arrays.binarySearch(stages, targetValue);
		return idx >= 0 ? idx : -1;
	}

	/**
	 * Returns the stage description for a quest at the given stage index,
	 * or {@code null} if unavailable.
	 */
	public String getStageDescription(String questName, int stageIndex)
	{
		String[] descs = stageDescriptions.get(questName);
		if (descs == null || stageIndex < 0 || stageIndex >= descs.length)
		{
			return null;
		}
		return descs[stageIndex];
	}

	/**
	 * Returns true if stage data is available for the given quest.
	 */
	public boolean hasQuest(String questName)
	{
		return stageValues.containsKey(questName);
	}
}

